window.EXERCISE_LIBRARY={"version":"7.0","structure":"32 categories from v6 + supplemental Wzmocnienie pośladków; 33 categories x 5 exercises x 4 stages = 660 entries; 132 category-stage PDFs","stages":[{"meta":{"id":"week1","label":"1. tydzień","short":"Tydzień 1","desc":"Etap wprowadzający - technika, tolerancja ruchu, mała/umiarkowana objętość."},"categories":[{"id":"cat01","name":"Rwa kulszowa","goal":"Łagodne utrzymanie ruchu, poprawa tolerancji obciążenia i ślizgu struktur nerwowych bez nasilania objawów w nodze.","note":"W rwie nie ma jednego dobrego kierunku ruchu dla wszystkich. Wybieraj ćwiczenia, po których ból/drętwienie nie schodzi dalej do stopy. Pilna konsultacja: drętwienie okolicy krocza, zaburzenia oddawania moczu/stolca, szybko narastające osłabienie nogi lub objawy obustronne.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Sfinks - łagodny wyprost","description":"Połóż się na brzuchu, oprzyj przedramiona pod barkami i unieś klatkę bez zaciskania pośladków. Biodra zostają na podłożu. Oddychaj spokojnie. Wykonuj tylko wtedy, gdy objawy w nodze nie nasilają się ani nie schodzą niżej.","dose":"20-30 s x 3-5","tip":"Ruch ma być komfortowy; może być odczuwalny w plecach, ale nie powinien zwiększać promieniowania."},{"kind":"JOGA 2","title":"Pozycja dziecka z szeroko ustawionymi kolanami","description":"Usiądź pośladkami w kierunku pięt, kolana ustaw szerzej i wyciągnij ręce do przodu. Nie wciskaj się na siłę w zgięcie. Jeśli zgięcie nasila promieniowanie, pomiń tę pozycję.","dose":"20-40 s x 2-3","tip":"Wybieraj tylko kierunek, po którym noga czuje się tak samo lub lepiej."},{"kind":"POZIOM 1 - łatwy","title":"Ślizg nerwu kulszowego w leżeniu","description":"Połóż się na plecach. Zegnij biodro i kolano do wygodnej pozycji, podtrzymując udo rękami. Powoli prostuj kolano i jednocześnie kieruj palce stopy do siebie; wracając, zegnij kolano i rozluźnij stopę. To ma być płynny ślizg, nie mocne rozciąganie.","dose":"8-12 powt. x 1-2 serie","tip":"Bez długiego przytrzymania i bez wywoływania narastającego mrowienia."},{"kind":"POZIOM 2 - średni","title":"Most biodrowy","description":"Leżenie na plecach, kolana ugięte, stopy na szerokość bioder. Lekko napnij brzuch i unieś miednicę do linii barki-biodrakolana. Opuść powoli. Nie wyginaj mocno odcinka lędźwiowego.","dose":"8-12 powt. x 2-3 serie","tip":"Ciężar rozłóż równo na obu stopach."},{"kind":"POZIOM 3 - trudniejszy","title":"Bird dog - ręka i przeciwna noga","description":"Klęk podparty. Utrzymaj spokojny tułów i wyprostuj jednocześnie jedną nogę oraz przeciwną rękę. Wróć bez kołysania miednicą i zmień stronę.","dose":"6-10/stronę x 2-3 serie","tip":"Zakres kończyny mniejszy, jeśli pojawia się ból promieniujący."}]},{"id":"cat02","name":"Przodopochylenie miednicy","goal":"Nauka ustawienia miednicy bliżej pozycji neutralnej, poprawa kontroli mięśni brzucha i pośladków oraz tolerancji wyprostu biodra.","note":"Samo przodopochylenie nie jest chorobą. Ćwiczymy wtedy, gdy to ustawienie wiąże się z bólem, przeciążeniem lub słabą kontrolą ruchu.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Niski wykrok z podwinięciem miednicy","description":"Z klęku wysuń jedną stopę do przodu. Delikatnie podwiń miednicę „ogon pod siebie”, napnij pośladek nogi zakrocznej i przesuń tułów minimalnie do przodu. Nie rób przeprostu lędźwi.","dose":"20-30 s/stronę x 2-3","tip":"Rozciąganie powinno być z przodu biodra nogi zakrocznej."},{"kind":"JOGA 2","title":"Pozycja dziecka","description":"Usiądź w kierunku pięt i wydłuż plecy, wyciągając ręce przed siebie. Oddychaj do dolnych żeber i rozluźnij odcinek lędźwiowy.","dose":"30-45 s x 2-3","tip":"Nie dociskaj pośladków na siłę do pięt."},{"kind":"POZIOM 1 - łatwy","title":"Tyłopochylenie miednicy w leżeniu","description":"Leżenie na plecach, kolana ugięte. Na wydechu delikatnie zbliż dolne żebra do miednicy i spłaszcz lędźwie do podłoża. Wróć do neutralnej pozycji bez odrywania stóp.","dose":"8-12 powt. x 2 serie","tip":"Ruch ma pochodzić z miednicy, nie z mocnego napinania szyi."},{"kind":"POZIOM 2 - średni","title":"Most z kontrolą miednicy","description":"Najpierw delikatnie ustaw miednicę neutralnie lub lekko podwiń, potem unieś biodra. Utrzymaj żebra „nad miednicą”, bez wypychania brzucha w górę.","dose":"8-12 powt. x 2-3","tip":"Poczuj pośladki, nie tylko lędźwie."},{"kind":"POZIOM 3 - trudniejszy","title":"Wykrok w tył z kontrolą tułowia","description":"Stań prosto, zrób krok w tył i zejdź w dół. Utrzymuj żebra nad miednicą, brzuch lekko aktywny i pośladek nogi podporowej napięty. Wróć do stania.","dose":"6-10/stronę x 2-3","tip":"Nie pozwalaj, aby miednica uciekała w duży przeprost lędźwiowy."}]},{"id":"cat03","name":"Tyłopochylenie miednicy","goal":"Poprawa tolerancji lekkiego wyprostu, nauka swobodnego przodopochylenia miednicy i lepszego zgięcia w biodrach zamiast „podwijania” całych pleców.","note":"Tyłopochylenie samo w sobie bywa wariantem postawy. Ćwiczenia mają poprawiać kontrolę ruchu, a nie wymuszać jedną stałą pozycję.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Sfinks","description":"Połóż się na brzuchu i oprzyj na przedramionach. Unieś mostek, pozostawiając biodra i brzuch rozluźnione. Nie zaciskaj odcinka lędźwiowego.","dose":"20-30 s x 3","tip":"Oddychaj spokojnie; zmniejsz zakres przy bólu lędźwi."},{"kind":"JOGA 2","title":"Krowa w klęku podpartym","description":"Z klęku podpartego delikatnie unieś kość ogonową i mostek, tworząc łagodny łuk. Nie zapadaj się w barkach. Następnie wróć do neutralnej pozycji.","dose":"8-12 powt.","tip":"Ruch wykonuj segmentalnie i bez bólu."},{"kind":"POZIOM 1 - łatwy","title":"Przodopochylenie miednicy w siadzie","description":"Usiądź na brzegu krzesła. Bez poruszania klatką piersiową przetocz miednicę do przodu tak, aby poczuć ciężar bardziej na przedniej części guzów kulszowych. Wróć do środka.","dose":"10-15 powt. x 2","tip":"Mały, precyzyjny ruch jest lepszy niż duże wyginanie pleców."},{"kind":"POZIOM 2 - średni","title":"Hip hinge przy ścianie","description":"Stań 20-30 cm przed ścianą tyłem do niej. Cofnij biodra, jakbyś chciał dotknąć pośladkami ściany, utrzymując długi kręgosłup. Wróć przez wyprost bioder.","dose":"8-12 powt. x 2-3","tip":"Kolana lekko ugięte, ciężar na całej stopie."},{"kind":"POZIOM 3 - trudniejszy","title":"Skłon rumuński bez obciążenia","description":"Stań prosto. Cofnij biodra i pochyl tułów z prostym, wydłużonym kręgosłupem, aż poczujesz tył ud. Wróć, napinając pośladki.","dose":"8-12 powt. x 2-3","tip":"Nie podwijaj miednicy w dolnej fazie i nie zaokrąglaj lędźwi."}]},{"id":"cat04","name":"Koślawość kolan","goal":"Poprawa kontroli osi biodro-kolano-stopa podczas przysiadu, wstawania i podporu jednonóż.","note":"U dzieci i dorosłych część koślawości może wynikać z budowy anatomicznej. Ćwiczenia poprawiają kontrolę funkcjonalną, ale nie „prostują kości”.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Wojownik II","description":"Stań szeroko. Ugnij przednie kolano nad stopą, pilnując aby kierowało się w stronę 2.-3. palca. Tylna noga wyprostowana, miednica stabilna.","dose":"20-30 s/stronę x 2","tip":"Kolano nie zapada się do środka."},{"kind":"JOGA 2","title":"Krzesło - Utkatasana","description":"Stań na szerokość bioder, cofnij biodra jak do siadania i ugnij kolana. Utrzymuj stopy w trzech punktach podparcia i kolana nad stopami.","dose":"15-30 s x 2-3","tip":"Nie ściskaj kolan na siłę; utrzymuj naturalną oś."},{"kind":"POZIOM 1 - łatwy","title":"Odwodzenie nogi bokiem w leżeniu","description":"Połóż się na boku, dolna noga może być ugięta. Górną nogę wyprostuj i unieś lekko w bok, z palcami skierowanymi do przodu. Powoli opuść.","dose":"10-15/stronę x 2-3","tip":"Nie obracaj miednicy do tyłu."},{"kind":"POZIOM 2 - średni","title":"Wstawanie z krzesła z kontrolą kolan","description":"Usiądź na brzegu krzesła, stopy na szerokość bioder. Wstań, utrzymując kolana w osi stóp, potem powoli usiądź.","dose":"8-12 powt. x 2-3","tip":"Możesz zacząć od wyższego krzesła."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad jednonóż do krzesła","description":"Stań przed wysokim krzesłem na jednej nodze. Cofnij biodro i dotknij pośladkiem siedziska, następnie wstań. Kolano utrzymuj nad 2.-3. palcem stopy.","dose":"5-8/stronę x 2-3","tip":"Zacznij od bardzo wysokiego podparcia i małego zakresu."}]},{"id":"cat05","name":"Płaskostopie","goal":"Aktywacja mięśni krótkich stopy, poprawa kontroli łuku podłużnego i równowagi bez „zaciskania” palców.","note":"Ćwiczenia mogą poprawiać funkcję stopy, ale nie każda płaska stopa wymaga korekcji. Szczególnie u dzieci ocena zależy od wieku, elastyczności i objawów.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Góra - Tadasana z „trójnogiem” stopy","description":"Stań boso. Dociśnij trzy punkty: piętę, podstawę palucha i podstawę małego palca. Palce rozluźnione. Delikatnie unieś łuk stopy bez podwijania palców.","dose":"20-30 s x 3","tip":"Ciężar równomiernie na całej stopie."},{"kind":"JOGA 2","title":"Pies z głową w dół","description":"Z podporu unieś biodra w górę i cofnij je. Pięty mogą zostać uniesione. Wydłużaj tył nóg i łydki bez bólu w stopie.","dose":"20-30 s x 2-3","tip":"Nie wymuszaj kontaktu pięt z podłożem."},{"kind":"POZIOM 1 - łatwy","title":"Krótka stopa","description":"Siedząc lub stojąc, utrzymaj piętę i głowy I oraz V kości śródstopia na podłożu. Delikatnie „skróć” stopę, przyciągając przodostopie w stronę pięty bez zginania palców.","dose":"5-8 s x 6-10","tip":"Palce mają pozostać długie i rozluźnione."},{"kind":"POZIOM 2 - średni","title":"Wspięcia na palce z kontrolą łuku","description":"Stań przy ścianie. Utrzymaj trójnóg stopy i unieś pięty. Powoli zejdź w dół, nie pozwalając kostkom zapadać się do środka.","dose":"10-15 x 2-3","tip":"Nacisk pozostaje także pod podstawą palucha."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż z krótką stopą","description":"Stań na jednej nodze i utrzymaj aktywny łuk bez chwytania podłoża palcami. Gdy jest łatwo, wykonuj powolne ruchy drugą nogą w przód, bok i tył.","dose":"20-40 s/stronę x 2-3","tip":"Kolano ustawione nad stopą, miednica stabilna."}]},{"id":"cat06","name":"Wzmocnienie mięśni core","goal":"Poprawa kontroli tułowia podczas ruchu kończyn, bez wstrzymywania oddechu i bez nadmiernego usztywnienia.","note":"„Core” to nie tylko mięśnie brzucha. W ćwiczeniach współpracują przepona, mięśnie brzucha, grzbietu, dna miednicy i obręczy biodrowej.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Deska na kolanach lub stopach","description":"Oprzyj dłonie lub przedramiona pod barkami. Utrzymaj linię głowa-tułów-miednica. Zacznij od wersji na kolanach, potem przejdź na stopy.","dose":"10-30 s x 2-4","tip":"Oddychaj, nie zapadaj lędźwi."},{"kind":"JOGA 2","title":"Łódka - łatwa wersja","description":"Usiądź, ugnij kolana i odchyl tułów lekko do tyłu. Unieś jedną, a potem obie stopy, utrzymując długi kręgosłup. Ręce mogą trzymać uda.","dose":"10-20 s x 2-3","tip":"Zmniejsz zakres, jeśli czujesz lędźwie bardziej niż brzuch."},{"kind":"POZIOM 1 - łatwy","title":"Napięcie brzucha + ślizg pięty","description":"Leżenie na plecach, kolana ugięte. Delikatnie napnij brzuch jak przed kaszlnięciem i wysuwaj jedną piętę po podłożu, nie zmieniając ustawienia miednicy.","dose":"6-10/stronę x 2","tip":"Oddychaj swobodnie przez cały ruch."},{"kind":"POZIOM 2 - średni","title":"Dead bug","description":"Leżenie na plecach, biodra i kolana około 90°. Utrzymując stabilny tułów, opuszczaj jedną piętę w stronę podłogi i wracaj. Trudniej: dodaj przeciwną rękę.","dose":"6-10/stronę x 2-3","tip":"Plecy nie muszą być mocno dociśnięte - ważna jest kontrola bez bólu."},{"kind":"POZIOM 3 - trudniejszy","title":"Deska z naprzemiennym dotknięciem barku","description":"Pozycja wysokiej deski. Oderwij jedną dłoń i dotknij przeciwnego barku, nie kołysząc miednicą. Zmień stronę.","dose":"6-12/stronę x 2-3","tip":"Ustaw stopy szerzej, jeśli trudno utrzymać stabilność."}]},{"id":"cat07","name":"Poprawa ruchomości całego kręgosłupa","goal":"Łagodny ruch odcinka szyjnego, piersiowego i lędźwiowego w kilku kierunkach, bez forsowania końcowych zakresów.","note":"Przy osteoporozie, świeżym urazie, zawrotach głowy po ruchu szyi lub objawach neurologicznych zakres powinien ustalić fizjoterapeuta.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Kot-krowa","description":"W klęku podpartym na wydechu zaokrąglij plecy i opuść głowę, a na wdechu delikatnie unieś mostek i kość ogonową. Ruch prowadź płynnie od miednicy po szyję.","dose":"8-12 cykli","tip":"Nie dociskaj szyi do końcowego zakresu."},{"kind":"JOGA 2","title":"Dziecko -> sfinks","description":"Z pozycji dziecka przejdź płynnie do leżenia na brzuchu i podeprzyj się na przedramionach w sfinksie. Następnie wróć.","dose":"5-8 cykli","tip":"Ruch spokojny, bez ostrego bólu i bez szarpania."},{"kind":"POZIOM 1 - łatwy","title":"Rotacja „otwieranie książki”","description":"Leżenie na boku, biodra i kolana ugięte, ręce wyciągnięte przed sobą. Otwórz górną rękę do tyłu, prowadząc za nią klatkę piersiową. Kolana pozostają razem.","dose":"6-10/stronę","tip":"Głowa może podążać za dłonią, jeśli nie wywołuje zawrotów."},{"kind":"POZIOM 2 - średni","title":"Wyprost piersiowy na krześle","description":"Usiądź, oprzyj górną część pleców o oparcie. Dłonie za głową. Delikatnie odchyl klatkę piersiową nad oparciem, bez dużego przeprostu lędźwi.","dose":"6-10 powt. x 2","tip":"Ruch ma być głównie w piersiowym odcinku kręgosłupa."},{"kind":"POZIOM 3 - trudniejszy","title":"Skłon + wyprost segmentalny w staniu","description":"Z pozycji stojącej powoli opuszczaj brodę i zaokrąglaj kręgosłup od góry, schodząc tylko do wygodnego zakresu. Wróć powoli, ustawiając kręgi „jeden po drugim”.","dose":"5-8 powt.","tip":"Nie wykonuj przy osteoporozie bez wcześniejszej konsultacji."}]},{"id":"cat08","name":"Ból głowy","goal":"Zmniejszenie napięcia szyi i obręczy barkowej przy bólach napięciowych lub szyjnopochodnych oraz poprawa kontroli odcinka szyjnego.","note":"Te ćwiczenia nie są przeznaczone do nagłego, bardzo silnego bólu głowy ani bólu z niedowładem/drętwieniem twarzy lub kończyn, zaburzeniami mowy, widzenia, równowagi, gorączką ze sztywnością karku albo po urazie głowy.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pozycja dziecka z podparciem czoła","description":"Usiądź w kierunku pięt, oprzyj czoło na dłoniach lub poduszce i pozwól barkom opaść. Oddychaj spokojnie, wydłużając wydech.","dose":"1-2 min","tip":"Szyja ma być całkowicie rozluźniona."},{"kind":"JOGA 2","title":"Nogi na ścianie - Viparita Karani","description":"Połóż się na plecach blisko ściany i oprzyj na niej nogi. Podeprzyj głowę cienką poduszką, jeśli tego potrzebujesz. Rozluźnij szczękę i barki.","dose":"2-5 min","tip":"Pomiń, jeśli pozycja zwiększa ból głowy lub ciśnienie w głowie."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody","description":"Siedząc lub leżąc, przesuń głowę poziomo do tyłu, jakbyś robił delikatny „podwójny podbródek”. Nie pochylaj głowy w dół.","dose":"5 s x 8-10","tip":"Ruch ma być mały i bez bólu promieniującego."},{"kind":"POZIOM 2 - średni","title":"Łopatki w dół i lekko do tyłu","description":"Usiądź prosto. Delikatnie ustaw łopatki w dół i do środka, bez wypinania klatki i bez unoszenia barków. Utrzymaj, rozluźnij.","dose":"5 s x 8-12","tip":"Nie ściskaj łopatek maksymalnie."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrolowana rotacja szyi","description":"Usiądź prosto. Powoli obróć głowę w prawo do komfortowego zakresu, wróć do środka i powtórz w lewo.","dose":"6-10/stronę","tip":"Przerwij przy zawrotach, zaburzeniach widzenia lub wyraźnym nasileniu bólu głowy."}]},{"id":"cat09","name":"Ból karku","goal":"Utrzymanie ruchomości szyi, aktywacja głębokich mięśni szyi i poprawa pracy łopatek.","note":"Przy bólu po urazie, nasilającej się słabości ręki, niezgrabności dłoni, zaburzeniach chodu lub nowych zaburzeniach zwieraczy potrzebna jest pilna ocena lekarska.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Szczeniak - Uttana Shishosana","description":"Z klęku podpartego cofnij biodra lekko w stronę pięt, a dłonie wysuń daleko do przodu. Klatkę kieruj w dół, ale szyję utrzymuj długą i swobodną.","dose":"20-30 s x 2-3","tip":"Nie wciskaj głowy w podłoże."},{"kind":"JOGA 2","title":"Orzeł - same ramiona","description":"Siedząc lub stojąc, skrzyżuj ramiona przed sobą i połącz przedramiona tak, jak pozwala zakres. Unieś łokcie lekko, oddychając w górną część pleców.","dose":"20-30 s/stronę x 2","tip":"Barki pozostają z dala od uszu."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody","description":"Przesuń głowę prosto do tyłu, utrzymując wzrok na wprost. Utrzymaj krótko i wróć.","dose":"5 s x 8-12","tip":"Nie unoś ani nie opuszczaj brody."},{"kind":"POZIOM 2 - średni","title":"Izometria szyi","description":"Połóż dłoń na czole i delikatnie napieraj głową na dłoń bez ruchu. Powtórz z dłonią z boku głowy po obu stronach.","dose":"5-8 s x 4-6 w każdym kierunku","tip":"Siła umiarkowana, bez zaciskania zębów."},{"kind":"POZIOM 3 - trudniejszy","title":"Anioł przy ścianie","description":"Oprzyj plecy o ścianę, broda lekko cofnięta. Przesuwaj ramiona po ścianie w górę i w dół w wygodnym zakresie, utrzymując łopatki pod kontrolą.","dose":"8-12 x 2-3","tip":"Nie wypychaj żeber do przodu."}]},{"id":"cat10","name":"Drętwienie palców u dłoni","goal":"Łagodny ruch szyi, łopatki i nerwów kończyny górnej po wcześniejszej ocenie przyczyny objawów.","note":"Drętwienie palców może pochodzić z szyi, nadgarstka, łokcia lub innych przyczyn. Zestaw należy dobrać do rozpoznania. Pilna ocena, jeśli narasta osłabienie/chwyt, pojawia się niezgrabność obu rąk, zaburzenia chodu lub nagłe objawy neurologiczne.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Góra z rozluźnieniem barków","description":"Stań prosto, dłonie skieruj do przodu, barki opuść i wydłuż szyję. Zrób 5-6 spokojnych oddechów, nie zaciskając palców.","dose":"30-45 s x 2","tip":"Dłonie i szczęka pozostają rozluźnione."},{"kind":"JOGA 2","title":"Anjali Mudra - dłonie przed klatką","description":"Złącz dłonie przed mostkiem bez mocnego dociskania. Ustaw nadgarstki neutralnie lub tylko lekko zgięte. Oddychaj spokojnie.","dose":"20-30 s x 2","tip":"Jeśli drętwienie się nasila, zmniejsz zgięcie nadgarstka lub pomiń."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody + ustawienie łopatki","description":"Usiądź prosto. Lekko cofnij brodę, a łopatkę po stronie objawów ustaw swobodnie w dół. Nie ciągnij barku na siłę.","dose":"5 s x 8-10","tip":"Objawy w dłoni nie powinny narastać."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu pośrodkowego - delikatny","description":"Ramię przy boku, łokieć zgięty. Powoli prostuj łokieć, jednocześnie odchylając nadgarstek i palce tylko do lekkiego napięcia, potem wróć. Stosuj szczególnie, gdy objawy obejmują kciuk, palec wskazujący i środkowy - po ocenie fizjoterapeuty.","dose":"6-10 powt.","tip":"To ma być ślizg, nie mocne rozciąganie. Nie przytrzymuj końcowej pozycji."},{"kind":"POZIOM 3 - trudniejszy","title":"Ślizg ramion po ścianie","description":"Stań twarzą do ściany, przedramiona oprzyj o nią. Powoli przesuwaj ręce w górę, pozwalając łopatkom obracać się w górę, potem wróć.","dose":"8-12 x 2","tip":"Przerwij, jeśli drętwienie wyraźnie narasta lub utrzymuje się po ćwiczeniu."}]},{"id":"cat11","name":"Drętwienie pośladków","goal":"Poprawa ruchu lędźwi i bioder oraz tolerancji pozycji siedzącej, jeśli przyczyna ma charakter mechaniczny i poważne przyczyny neurologiczne zostały wykluczone.","note":"Drętwienie obu pośladków lub okolicy krocza, zwłaszcza z zaburzeniami oddawania moczu/stolca, jest objawem alarmowym - nie ćwiczyć, tylko pilnie zgłosić się do pomocy medycznej.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Gołąb na plecach - „4”","description":"Leżąc na plecach, połóż kostkę jednej nogi na przeciwległym udzie. Przyciągnij udo do siebie tylko do łagodnego rozciągania pośladka.","dose":"20-30 s/stronę x 2","tip":"Nie dociskaj kolana na siłę."},{"kind":"JOGA 2","title":"Kot-krowa","description":"W klęku podpartym naprzemiennie zaokrąglaj i delikatnie wyginaj kręgosłup, poruszając miednicą.","dose":"8-12 cykli","tip":"Wybierz zakres, który nie zwiększa drętwienia."},{"kind":"POZIOM 1 - łatwy","title":"Przetaczanie miednicy w leżeniu","description":"Leżenie na plecach, kolana ugięte. Naprzemiennie delikatnie spłaszczaj lędźwie i wracaj do lekkiego łuku.","dose":"10-15 powt.","tip":"Ruch ma być mały i płynny."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu kulszowego","description":"Leżenie na plecach. Unieś udo, podtrzymując je rękami. Prostuj i zginaj kolano w małym zakresie, synchronizując ruch stopy tak, aby nie utrzymywać napięcia.","dose":"8-12/stronę","tip":"Bez nasilania drętwienia po ćwiczeniu."},{"kind":"POZIOM 3 - trudniejszy","title":"Most biodrowy","description":"Unieś miednicę z leżenia na plecach, utrzymując ciężar na obu stopach i spokojny oddech. Powoli wróć.","dose":"8-12 x 2-3","tip":"Jeśli objawy stają się bardziej rozlane lub schodzą niżej do nogi - przerwij."}]},{"id":"cat12","name":"Drętwienie ud","goal":"Poprawa ruchomości biodra i odcinka lędźwiowego oraz zmniejszenie drażnienia tkanek w okolicy pachwiny/uda, gdy objawy są ocenione jako mechaniczne.","note":"Drętwienie bocznej części uda może mieć inne źródło niż drętwienie przedniej lub tylnej części. Przy narastającej słabości nogi, zaburzeniu chodu lub objawach obustronnych wymagana jest ocena neurologiczna.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Niski wykrok","description":"Jedna noga z przodu, drugie kolano na podłożu. Delikatnie podwiń miednicę i przesuń ją do przodu, czując przód biodra nogi zakrocznej.","dose":"20-30 s/stronę x 2","tip":"Nie rób przeprostu lędźwi."},{"kind":"JOGA 2","title":"Sfinks","description":"Leżenie na brzuchu, podpór na przedramionach. Unieś klatkę do komfortowego wyprostu.","dose":"20-30 s x 2-3","tip":"Wykonuj tylko, jeśli nie zwiększa drętwienia w udzie."},{"kind":"POZIOM 1 - łatwy","title":"Kołysanie miednicą w leżeniu","description":"Leżenie na plecach, kolana ugięte. Powoli przechodź między lekkim spłaszczeniem i lekkim łukiem lędźwi.","dose":"10-15 powt.","tip":"Bez forsowania końcowego zakresu."},{"kind":"POZIOM 2 - średni","title":"Rozciąganie zginaczy biodra w półklęku","description":"Z półklęku podwiń miednicę i napnij pośladek nogi z tyłu. Przesuń ciało lekko do przodu.","dose":"20-30 s/stronę x 2-3","tip":"Nie dociskaj do bólu lub mrowienia."},{"kind":"POZIOM 3 - trudniejszy","title":"Wykrok w tył","description":"Z pozycji stojącej cofnij jedną nogę i obniż ciało. Wróć do stania, aktywnie pracując pośladkiem nogi podporowej.","dose":"6-10/stronę x 2-3","tip":"Utrzymuj stabilną miednicę i kolano nad stopą."}]},{"id":"cat13","name":"Drętwienie łydek","goal":"Łagodny ruch nerwowo-mięśniowy kończyny dolnej, poprawa pracy stawu skokowego i łydki po wcześniejszej ocenie źródła drętwienia.","note":"Nagłe drętwienie z wyraźnym osłabieniem stopy, opadaniem stopy, obustronnymi objawami lub zaburzeniami zwieraczy wymaga pilnej oceny. Obrzęk, zaczerwienienie i ból łydki wymagają wykluczenia problemu naczyniowego.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół z ugiętymi kolanami","description":"Z podporu unieś biodra. Kolana pozostaw lekko ugięte i naprzemiennie kieruj pięty w dół, bez mocnego ciągnięcia łydki.","dose":"30-45 s","tip":"Nie trzymaj rozciągnięcia, jeśli wywołuje mrowienie."},{"kind":"JOGA 2","title":"Skłon do jednej nogi w siadzie - łagodny","description":"Usiądź z jedną nogą wyprostowaną, drugą ugiętą. Pochyl się z bioder tylko do lekkiego napięcia tyłu nogi.","dose":"15-20 s/stronę x 2","tip":"Przy drętwieniu nie pogłębiaj rozciągania nerwu."},{"kind":"POZIOM 1 - łatwy","title":"Pompowanie stopy","description":"Siedząc lub leżąc, naprzemiennie kieruj palce stopy do siebie i od siebie w pełnym, komfortowym zakresie.","dose":"15-20 x 2","tip":"Ruch płynny, bez bolesnego skurczu."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu kulszowego w siadzie","description":"Usiądź prosto. Prostuj kolano i jednocześnie unieś głowę; wracając zginaj kolano i lekko opuszczaj brodę. Ruch wykonuj płynnie, bez przytrzymania.","dose":"6-10/stronę","tip":"Zakres ma nie zwiększać mrowienia po serii."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcie na palce jednonóż z podparciem","description":"Stań przy ścianie. Unieś piętę jednej nogi, powoli opuść. Utrzymuj stopę w osi i nie skręcaj kostki.","dose":"6-12/stronę x 2-3","tip":"Jeśli pojawia się narastająca słabość, zakończ i skonsultuj objaw."}]},{"id":"cat14","name":"Poprawa ruchomości stawów skokowych","goal":"Poprawa zgięcia grzbietowego, ruchomości łydki i kontroli stopy potrzebnej do chodu, przysiadu i schodów.","note":"Po świeżym skręceniu, złamaniu lub operacji zakres obciążania powinien wynikać z zaleceń prowadzącego lekarza/fizjoterapeuty.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - naprzemienne pięty","description":"Ustaw się w psie z głową w dół. Naprzemiennie uginaj jedno kolano i kieruj przeciwną piętę w stronę podłoża.","dose":"8-12/stronę","tip":"Pięta nie musi dotykać podłogi."},{"kind":"JOGA 2","title":"Krzesło z ciężarem na całej stopie","description":"Z pozycji stojącej cofnij biodra i ugnij kolana, utrzymując pięty na podłożu. Kolana przesuwają się nad stopami w komfortowym zakresie.","dose":"15-30 s x 2-3","tip":"Nie zapadaj łuków stóp do środka."},{"kind":"POZIOM 1 - łatwy","title":"Kolano do ściany","description":"Stań przodem do ściany, stopa płasko. Prowadź kolano do ściany nad 2.-3. palcem bez odrywania pięty. Jeśli łatwo - odsuń stopę od ściany.","dose":"8-12/stronę x 2","tip":"Kolano nie zapada się do środka."},{"kind":"POZIOM 2 - średni","title":"Wspięcie i powolne opuszczanie pięty","description":"Stań na obu stopach przy ścianie. Unieś pięty wysoko, zatrzymaj 1 s i opuszczaj przez 3 s.","dose":"10-15 x 2-3","tip":"Ruch symetryczny, ciężar na podstawie palucha i małego palca."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad głęboki z podparciem","description":"Trzymając się stabilnego oparcia, zejdź do przysiadu tak głęboko, jak pozwalają biodra i kostki. Pięty pozostają na podłożu.","dose":"20-40 s x 2-3","tip":"Nie wymuszaj głębokości kosztem bólu kolan lub stóp."}]},{"id":"cat15","name":"Poprawa ruchomości bioder","goal":"Ruch biodra w zgięciu, wyproście, rotacji i odwiedzeniu przy możliwie stabilnej miednicy.","note":"Przy nasilającym się bólu pachwiny, blokowaniu stawu lub bólu nocnym zakres powinien być oceniony indywidualnie.","source":"original17","exercises":[{"kind":"JOGA 1","title":"90/90","description":"Usiądź z jedną nogą z przodu i drugą z boku, obie ugięte około 90°. Usiądź wysoko, a następnie delikatnie pochyl tułów nad przednią nogą.","dose":"20-30 s/stronę x 2","tip":"Nie dociskaj kolan na siłę do podłogi."},{"kind":"JOGA 2","title":"Niski wykrok","description":"Z półklęku podwiń lekko miednicę i przesuń ją do przodu, czując przód biodra nogi zakrocznej.","dose":"20-30 s/stronę x 2","tip":"Nie wyginaj lędźwi."},{"kind":"POZIOM 1 - łatwy","title":"Kolano do klatki + krążenie biodrem","description":"Leżąc na plecach, przyciągnij jedno kolano do komfortowego zakresu i wykonuj małe kółka udem w stawie biodrowym.","dose":"5-8 kółek w każdą stronę","tip":"Miednica pozostaje możliwie spokojna."},{"kind":"POZIOM 2 - średni","title":"Wycieraczki w leżeniu","description":"Leżenie na plecach, kolana ugięte, stopy szerzej. Opuszczaj oba kolana w jedną stronę, wróć i powtórz w drugą.","dose":"8-12/stronę","tip":"Zakres bez bólu w pachwinie."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad kozacki","description":"Stań szeroko. Przenieś ciężar na jedną nogę, uginając ją, a drugą pozostaw bardziej wyprostowaną. Wróć przez środek i zmień stronę.","dose":"5-8/stronę x 2","tip":"Zacznij płytko i trzymaj się oparcia, jeśli potrzeba."}]},{"id":"cat16","name":"Rozluźnienie przepony","goal":"Zmniejszenie nadmiernego udziału górnej klatki i mięśni pomocniczych oddechu, poprawa spokojnego oddechu dolnożebrowego.","note":"Ćwiczenia oddechowe wykonuj bez forsowania. Jeśli pojawi się zawrót głowy, przerwij, odpocznij i wróć do naturalnego oddechu.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pozycja krokodyla - Makarasana","description":"Połóż się na brzuchu, czoło oprzyj na złożonych dłoniach. Pozwól, by przy wdechu dolne żebra i brzuch delikatnie naciskały na podłoże.","dose":"1-3 min","tip":"Barki, szyja i szczęka rozluźnione."},{"kind":"JOGA 2","title":"Pozycja dziecka z oddechem do pleców","description":"Usiądź w kierunku pięt, oprzyj czoło. Wdychaj powietrze „do dolnych żeber i pleców”, a na wydechu rozluźniaj brzuch i barki.","dose":"5-8 spokojnych oddechów","tip":"Nie staraj się nabierać maksymalnie dużo powietrza."},{"kind":"POZIOM 1 - łatwy","title":"Oddech 360° w leżeniu","description":"Połóż dłonie na dolnych żebrach. Wdech nosem: żebra delikatnie rozszerzają się na boki i do tyłu. Wydech: swobodnie opadają.","dose":"6-10 oddechów x 2-3","tip":"Górna część klatki porusza się niewiele."},{"kind":"POZIOM 2 - średni","title":"Wydłużony wydech","description":"Wdech nosem przez około 3-4 s, następnie spokojny wydech przez lekko złączone usta przez 5-7 s. Nie opróżniaj płuc na siłę.","dose":"5-8 cykli","tip":"Jeśli kręci się w głowie - skróć oddech i zrób przerwę."},{"kind":"POZIOM 3 - trudniejszy","title":"Oddech boczno-żebrowy w leżeniu na boku","description":"Połóż się na boku, górną dłoń połóż na dolnych żebrach. Kieruj wdech pod dłoń, a przy wydechu pozwól żebrom opaść.","dose":"6-10/stronę","tip":"Oddychaj cicho i bez unoszenia barku."}]},{"id":"cat17","name":"Wzmocnienie przepony","goal":"Poprawa kontroli i wytrzymałości oddechowej bez sprzętu poprzez pracę przepony w coraz trudniejszych pozycjach i podczas lekkiego wysiłku.","note":"Bez urządzenia z oporem są to głównie ćwiczenia kontroli i wytrzymałości oddechowej, nie precyzyjny trening siły mięśni wdechowych. Przy chorobach płuc/serca dawkę należy ustalić indywidualnie.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Most z oddechem","description":"Leżenie na plecach. Na wydechu unieś miednicę do mostu. Utrzymując pozycję, wykonaj 2-3 spokojne oddechy do dolnych żeber i opuść biodra.","dose":"5-8 powt.","tip":"Nie wstrzymuj oddechu w górze."},{"kind":"JOGA 2","title":"Krzesło - Utkatasana z oddechem nosem","description":"Stań, cofnij biodra jak do siadania i ugnij kolana. Utrzymuj pozycję, wykonując spokojne wdechy nosem i dłuższe wydechy.","dose":"15-30 s x 2-3","tip":"Przerwij przy duszności nieproporcjonalnej do wysiłku lub zawrotach głowy."},{"kind":"POZIOM 1 - łatwy","title":"Oddech przeponowy w leżeniu","description":"Połóż jedną dłoń na mostku, drugą na brzuchu/dolnych żebrach. Wdech kieruj w dół i na boki, wydech swobodny. Z czasem wydłużaj serię bez zwiększania objętości pojedynczego oddechu.","dose":"10 oddechów x 2-3","tip":"Ruch ręki na górnej klatce ma być niewielki."},{"kind":"POZIOM 2 - średni","title":"Oddech przeponowy w klęku podpartym","description":"Klęk podparty, kręgosłup neutralny. Wdech nosem do boków i tyłu dolnych żeber; wydech spokojny, z lekkim napięciem brzucha.","dose":"8-12 oddechów x 2","tip":"Nie zapadaj się w barkach i nie unoś ich przy wdechu."},{"kind":"POZIOM 3 - trudniejszy","title":"Marsz w miejscu z kontrolowanym oddechem","description":"Maszeruj spokojnie, unosząc kolana do komfortowej wysokości. Utrzymuj rytm: 2-3 kroki na wdech i 3-4 kroki na wydech, bez zadyszki.","dose":"1-3 min x 2-3","tip":"Tempo pozwala mówić krótkim zdaniem; przerwij przy bólu w klatce lub znacznej duszności."}]},{"id":"cat18","name":"Ból barku / stożek rotatorów","goal":"Poprawa tolerancji unoszenia ramienia i stopniowe wzmacnianie stożka rotatorów oraz łopatki.","note":"Ćwiczenia dobieraj do drażliwości. Po świeżym urazie z nagłą utratą siły lub niemożnością uniesienia ramienia wymagana jest dalsza diagnostyka.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Szczeniak przy ścianie","description":"Stań przed ścianą, oprzyj dłonie i cofnij biodra, wydłużając boki tułowia oraz obręcz barkową bez wciskania barku w ból.","dose":"20-30 s x 2-3","tip":"Zakres ma być swobodny; nie unoś barków do uszu."},{"kind":"JOGA 2","title":"Orzeł - ramiona","description":"Skrzyżuj ramiona przed klatką, unieś łokcie do wygodnej wysokości i spokojnie oddychaj w górną część pleców.","dose":"20-30 s/stronę x 2","tip":"Bez mrowienia i ostrego bólu barku."},{"kind":"POZIOM 1 - łatwy","title":"Izometria rotacji zewnętrznej przy ścianie","description":"Stań bokiem do ściany, łokieć przy tułowiu i delikatnie naciskaj grzbietem dłoni na ścianę bez ruchu barku.","dose":"6-10 s x 6-8","tip":"Siła umiarkowana; ból nie powinien narastać po serii."},{"kind":"POZIOM 2 - średni","title":"Ślizg ramion po ścianie","description":"Przesuwaj przedramiona w górę po ścianie, utrzymując szyję rozluźnioną i łopatkę płynnie obracającą się ku górze.","dose":"8-12 x 2-3","tip":"Nie wypychaj żeber do przodu."},{"kind":"POZIOM 3 - trudniejszy","title":"Scaption bez obciążenia","description":"Unieś ramiona w płaszczyźnie około 30° przed bokiem ciała do tolerowanego zakresu, powoli opuść.","dose":"8-12 x 2-3","tip":"Ruch kontrolowany, bez szarpania i unoszenia barków."}]},{"id":"cat19","name":"Kontrola łopatki / dyskineza","goal":"Poprawa kontroli łopatki podczas unoszenia i obciążania kończyny górnej.","note":"Celem nie jest sztywne „ściąganie łopatek”, lecz płynna współpraca łopatki z ramieniem i klatką piersiową.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Koci grzbiet z aktywnym odepchnięciem dłoni","description":"W klęku podpartym zaokrąglij łagodnie odcinek piersiowy, aktywnie odpychając podłoże i pozwalając łopatkom rozsunąć się.","dose":"8-12 cykli","tip":"Nie zapadaj się między barkami."},{"kind":"JOGA 2","title":"Deska wysoka - aktywna łopatka","description":"W podporze na dłoniach utrzymaj łokcie proste i delikatnie „odepchnij podłogę”, nie zaokrąglając przesadnie pleców.","dose":"10-20 s x 2-3","tip":"Zacznij z kolan, jeśli pełny podpor jest za trudny."},{"kind":"POZIOM 1 - łatwy","title":"Serratus punch w leżeniu","description":"Leżąc na plecach unieś rękę do sufitu, a następnie bez zginania łokcia sięgnij dłonią wyżej, unosząc łopatkę od podłoża.","dose":"10-15 x 2","tip":"Ruch mały i płynny."},{"kind":"POZIOM 2 - średni","title":"Wall slide z odepchnięciem","description":"Przesuwaj przedramiona po ścianie do góry, utrzymując lekkie odepchnięcie i spokojną szyję.","dose":"8-12 x 2-3","tip":"Nie dociskaj łopatek do kręgosłupa."},{"kind":"POZIOM 3 - trudniejszy","title":"Y przy ścianie","description":"Stań twarzą do ściany, unieś ręce po skosie do litery Y i delikatnie odklej dłonie bez unoszenia barków.","dose":"6-10 x 2-3","tip":"Zakres mniejszy, jeśli pojawia się kompensacja szyją."}]},{"id":"cat20","name":"Sztywność barku / zamrożony bark","goal":"Stopniowa poprawa tolerancji ruchu i funkcji bez forsowania bolesnego końcowego zakresu.","note":"W wysokiej drażliwości preferuj częste, krótkie i łagodne ruchy. Agresywne rozciąganie może nasilić objawy.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pozycja dziecka z rękami na podwyższeniu","description":"Oprzyj dłonie na krześle lub łóżku i cofnij biodra, pozwalając barkom wejść w wygodne zgięcie.","dose":"20-30 s x 2-3","tip":"Nie wciskaj barku w ból."},{"kind":"JOGA 2","title":"Orzeł - łagodny wariant ramion","description":"Skrzyżuj ramiona przed klatką i unieś łokcie tylko do komfortowego poziomu.","dose":"20 s/stronę x 2","tip":"Pomiń przy ostrym bólu przedniej części barku."},{"kind":"POZIOM 1 - łatwy","title":"Wahadło Codmana","description":"Podeprzyj się zdrową ręką, rozluźnij bolesną kończynę i wykonuj małe koła oraz ruchy przód-tył.","dose":"30-60 s x 2-3","tip":"Ramię ma być rozluźnione."},{"kind":"POZIOM 2 - średni","title":"Ślizg ręki po stole","description":"Siedząc przesuń dłoń po stole do przodu, pozwalając tułowi lekko pochylić się za ręką.","dose":"8-12 x 2-3","tip":"Nie unoś barku do ucha."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspinanie palcami po ścianie","description":"Wejdź palcami po ścianie do tolerowanego poziomu i powoli wróć.","dose":"6-10 x 2","tip":"Nie utrzymuj długo bolesnego końca zakresu."}]},{"id":"cat21","name":"Łokieć tenisisty","goal":"Zmniejszenie bólu podczas chwytu i stopniowe zwiększenie tolerancji prostowników nadgarstka na obciążenie.","note":"Zmniejsz przeciążenie chwytu, ale unikaj całkowitego unieruchamiania. Nasilający się deficyt wyprostu palców wymaga diagnostyki neurologicznej.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Dłonie odwrócone w klęku - łagodnie","description":"W klęku podpartym ustaw dłonie palcami w stronę kolan tylko w tolerowanym zakresie i delikatnie cofnij biodra.","dose":"15-20 s x 2","tip":"Bez drętwienia i ostrego bólu."},{"kind":"JOGA 2","title":"Orzeł - ramiona","description":"Skrzyżuj ramiona i wydłuż tył barków, utrzymując przedramiona rozluźnione.","dose":"20-30 s/stronę x 2","tip":"Nie zaciskaj dłoni."},{"kind":"POZIOM 1 - łatwy","title":"Izometria wyprostu nadgarstka","description":"Przedramię oprzyj na stole, drugą dłonią staw opór grzbietowi ręki bez ruchu w nadgarstku.","dose":"8-10 s x 6","tip":"Siła umiarkowana."},{"kind":"POZIOM 2 - średni","title":"Powolny wyprost nadgarstka bez ciężaru","description":"Przedramię na stole, dłoń poza krawędzią. Unieś i bardzo powoli opuść nadgarstek.","dose":"10-15 x 2-3","tip":"Ruch ma być płynny."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrolowany chwyt ręcznika","description":"Ściskaj zrolowany ręcznik do umiarkowanej siły i powoli rozluźniaj.","dose":"8-12 x 2-3","tip":"Nie prowokuj bólu utrzymującego się po ćwiczeniu."}]},{"id":"cat22","name":"Łokieć golfisty","goal":"Stopniowe zwiększenie tolerancji zginaczy i pronatorów przedramienia na chwyt i obciążenie.","note":"Przy drętwieniu IV-V palca lub wyraźnym osłabieniu dłoni różnicuj problem z nerwem łokciowym.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Dłonie grzbietami przed klatką","description":"Połącz grzbiety dłoni przed klatką piersiową i delikatnie opuszczaj łokcie, utrzymując komfort w nadgarstkach.","dose":"15-20 s x 2","tip":"Bez mrowienia."},{"kind":"JOGA 2","title":"Szczeniak z dłońmi na podwyższeniu","description":"Oprzyj dłonie na krześle, cofnij biodra i wydłuż ramiona oraz boki tułowia.","dose":"20-30 s x 2","tip":"Łokcie miękkie, bez przeprostu."},{"kind":"POZIOM 1 - łatwy","title":"Izometria zgięcia nadgarstka","description":"Drugą dłonią staw opór stronie dłoniowej ręki bez wykonywania ruchu.","dose":"8-10 s x 6","tip":"Siła umiarkowana."},{"kind":"POZIOM 2 - średni","title":"Powolne zgięcie nadgarstka bez ciężaru","description":"Przedramię na stole, dłoń poza krawędzią. Zegnij i powoli wróć do neutralnej pozycji.","dose":"10-15 x 2-3","tip":"Nie ściskaj palców."},{"kind":"POZIOM 3 - trudniejszy","title":"Pronacja i supinacja kontrolowana","description":"Z łokciem przy tułowiu obracaj dłoń ku górze i ku dołowi w pełnym komfortowym zakresie.","dose":"10-15 x 2-3","tip":"Ruch wolny, łokieć stabilny."}]},{"id":"cat23","name":"Cieśń nadgarstka / nerw pośrodkowy","goal":"Zmniejszenie prowokacji objawów i utrzymanie łagodnego ślizgu nerwu pośrodkowego oraz ruchomości nadgarstka.","note":"Nasilające się drętwienie, zanik kłębu kciuka lub utrwalona słabość wymagają dalszej diagnostyki.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra z otwartymi dłońmi","description":"Stań swobodnie, ramiona wzdłuż tułowia, palce dłoni wydłużone i rozluźnione.","dose":"30-45 s x 2","tip":"Nie utrzymuj nadgarstków w skrajnym zgięciu."},{"kind":"JOGA 2","title":"Anjali Mudra - dłonie przed klatką","description":"Złącz dłonie przed klatką na wysokości, która nie wywołuje parestezji.","dose":"20-30 s x 2","tip":"Zmniejsz kąt w nadgarstku przy mrowieniu."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie i zamykanie dłoni","description":"Naprzemiennie szeroko rozprostuj palce i lekko zamknij dłoń bez silnego ścisku.","dose":"15-20 x 2","tip":"Ruch bez bólu."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu pośrodkowego","description":"Wykonuj stopniowe ustawienia dłoni, łokcia i barku jako płynny ślizg bez utrzymywania napięcia.","dose":"6-10 x 1-2","tip":"Nie rozciągaj nerwu na końcu ruchu."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrola nadgarstka przy lekkim podporze","description":"Oprzyj dłonie o ścianę i delikatnie przenoś ciężar przód-tył.","dose":"30-45 s x 2","tip":"Przerwij przy nasileniu drętwienia."}]},{"id":"cat24","name":"Sztywność odcinka piersiowego / garb posturalny","goal":"Poprawa wyprostu i rotacji odcinka piersiowego oraz pracy łopatek.","note":"Przy osteoporozie unikaj forsownego zgięcia i rotacji; ćwiczenia dobierz indywidualnie.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Szczeniak - Uttana Shishosana","description":"Z klęku podpartego przesuń dłonie do przodu, pozostawiając biodra nad kolanami i wydłużając klatkę.","dose":"20-30 s x 2-3","tip":"Nie zapadaj szyi."},{"kind":"JOGA 2","title":"Kobra niska","description":"Leżąc na brzuchu oprzyj przedramiona lub dłonie i unieś mostek, utrzymując ruch głównie w piersiowym odcinku.","dose":"15-25 s x 2-3","tip":"Bez kompresji lędźwi."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie książki","description":"Leżąc na boku obracaj górne ramię i klatkę do tyłu, kolana pozostają razem.","dose":"6-10/stronę x 2","tip":"Ruch płynny."},{"kind":"POZIOM 2 - średni","title":"Wyprost piersiowy na oparciu","description":"Usiądź, oprzyj górny odcinek pleców o krawędź oparcia i wykonaj łagodny wyprost.","dose":"8-12 x 2","tip":"Nie odchylaj głowy gwałtownie."},{"kind":"POZIOM 3 - trudniejszy","title":"Wall angel","description":"Plecy przy ścianie, przesuwaj ramiona w górę i w dół bez wypychania żeber.","dose":"8-12 x 2-3","tip":"Zakres dostosuj do barków."}]},{"id":"cat25","name":"Ból lędźwiowy nieswoisty","goal":"Utrzymanie ruchu, poprawa kontroli tułowia i stopniowy powrót do obciążeń dnia codziennego.","note":"Nie ma jednego kierunku ruchu dobrego dla wszystkich. Dobieraj ćwiczenia do reakcji objawów i funkcji.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Kot-krowa","description":"W klęku podpartym płynnie przechodź między łagodnym zgięciem i wyprostem kręgosłupa.","dose":"8-12 cykli","tip":"Ruch bez forsowania."},{"kind":"JOGA 2","title":"Pozycja dziecka - jeśli komfortowa","description":"Cofnij biodra w kierunku pięt, ręce przed sobą i oddychaj spokojnie.","dose":"20-40 s x 2","tip":"Pomiń, jeśli zgięcie nasila objawy."},{"kind":"POZIOM 1 - łatwy","title":"Przetaczanie miednicy","description":"Leżąc na plecach wykonuj małe ruchy przodo- i tyłopochylenia miednicy.","dose":"10-15 x 2","tip":"Bez mocnego dociskania pleców."},{"kind":"POZIOM 2 - średni","title":"Most biodrowy","description":"Unieś biodra do linii tułowia i ud, utrzymując swobodny oddech.","dose":"8-12 x 2-3","tip":"Nie przeprostuj lędźwi."},{"kind":"POZIOM 3 - trudniejszy","title":"Bird dog","description":"Z klęku podpartego wyprostuj przeciwną rękę i nogę bez rotacji miednicy.","dose":"6-10/stronę x 2-3","tip":"Zakres mniejszy przy bólu."}]},{"id":"cat26","name":"Stabilizacja miednicy / okolica SI","goal":"Poprawa kontroli obciążania miednicy i bioder w podporze obunóż i jednonóż.","note":"Ból okolicy SI wymaga różnicowania z odcinkiem lędźwiowym, biodrem i innymi źródłami bólu.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Wojownik I - krótki wykrok","description":"Ustaw krótki wykrok i utrzymaj miednicę skierowaną do przodu, bez zapadania tułowia.","dose":"20-30 s/stronę x 2","tip":"Obie stopy stabilne."},{"kind":"JOGA 2","title":"Most z oddechem","description":"Unieś biodra i wykonaj spokojne 2-3 oddechy, potem powoli opuść.","dose":"5-8 x 2","tip":"Bez bólu punktowego w okolicy SI."},{"kind":"POZIOM 1 - łatwy","title":"Naprzemienne odrywanie stopy w leżeniu","description":"W leżeniu z ugiętymi kolanami unieś jedną stopę kilka centymetrów i odstaw bez kołysania miednicą.","dose":"8-12/stronę x 2","tip":"Miednica spokojna."},{"kind":"POZIOM 2 - średni","title":"Most z naprzemiennym marszem","description":"W górze mostu odrywaj na zmianę jedną stopę minimalnie od podłoża.","dose":"6-10/stronę x 2","tip":"Nie opadaj biodrem."},{"kind":"POZIOM 3 - trudniejszy","title":"Step-down z niskiego stopnia","description":"Stań na niskim stopniu i powoli opuszczaj drugą piętę do podłoża, kontrolując miednicę.","dose":"6-10/stronę x 2-3","tip":"Kolano w osi stopy."}]},{"id":"cat27","name":"Ból rzepkowo-udowy","goal":"Zwiększenie tolerancji kolana na zgięcie i obciążenie oraz poprawa siły biodra i uda.","note":"Ćwiczenia powinny być dozowane według 24-godzinnej reakcji objawów. Nie dąż do „ustawiania rzepki” na siłę.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Krzesło - płytko","description":"Cofnij biodra jak do siadania, ugnij kolana tylko do komfortowego zakresu i utrzymaj stopy stabilnie.","dose":"15-25 s x 2","tip":"Kolana nad stopami."},{"kind":"JOGA 2","title":"Wojownik II - płytki","description":"Ugnij przednie kolano w małym zakresie, utrzymując oś biodro-kolano-stopa.","dose":"20-30 s/stronę x 2","tip":"Nie zapadaj kolana do środka."},{"kind":"POZIOM 1 - łatwy","title":"Wyprost kolana w siadzie","description":"Siedząc powoli wyprostuj kolano do tolerowanego zakresu i wróć.","dose":"10-15 x 2","tip":"Ruch bez szarpania."},{"kind":"POZIOM 2 - średni","title":"Wstawanie z krzesła","description":"Wstań i usiądź powoli, utrzymując kolana w osi stóp.","dose":"8-12 x 2-3","tip":"Zacznij od wyższego siedziska."},{"kind":"POZIOM 3 - trudniejszy","title":"Step-down","description":"Z niskiego stopnia opuszczaj wolną piętę ku podłożu i wracaj.","dose":"6-10/stronę x 2-3","tip":"Miednica i kolano stabilne."}]},{"id":"cat28","name":"Ścięgno Achillesa / łydka","goal":"Stopniowe zwiększenie siły i tolerancji ścięgna Achillesa oraz mięśni łydki.","note":"Nagły trzask, utrata odepchnięcia lub dodatni test Thompsona wymagają pilnej diagnostyki ruptury.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - łagodnie","description":"Unieś biodra, kolana mogą być ugięte, a pięty wysoko. Stopniowo wydłużaj łydki bez ostrego bólu.","dose":"20-30 s x 2","tip":"Bez sprężynowania."},{"kind":"JOGA 2","title":"Wykrok z tylną piętą na ziemi","description":"Stań w wykroku i delikatnie przenieś ciężar do przodu, utrzymując tylną piętę na podłożu.","dose":"20-30 s/stronę x 2","tip":"Rozciąganie łagodne."},{"kind":"POZIOM 1 - łatwy","title":"Wspięcia obunóż","description":"Przy podparciu unieś obie pięty i powoli opuść.","dose":"10-15 x 2-3","tip":"Ruch spokojny."},{"kind":"POZIOM 2 - średni","title":"Wspięcia z większym obciążeniem jednej nogi","description":"Unieś pięty obunóż, przenieś nieco więcej ciężaru na jedną stronę podczas opuszczania.","dose":"8-12/stronę x 2-3","tip":"Bez gwałtownego spadania pięty."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcie jednonóż","description":"Przy lekkim podparciu wykonuj wspięcia na jednej nodze.","dose":"6-12/stronę x 2-3","tip":"Zakres i tempo dostosuj do reakcji następnego dnia."}]},{"id":"cat29","name":"Ból pięty / rozcięgno podeszwowe","goal":"Poprawa tolerancji rozcięgna podeszwowego i łydki na obciążenie oraz kontrola łuku stopy.","note":"Przy bólu pięty z drętwieniem, znacznym obrzękiem lub urazem różnicuj inne przyczyny.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół z ugiętymi kolanami","description":"Utrzymaj biodra wysoko, pięty uniesione i stopniowo prostuj kolana bez wywoływania ostrego bólu pięty.","dose":"20-30 s x 2","tip":"Nie wymuszaj pięt na ziemi."},{"kind":"JOGA 2","title":"Góra z aktywnym łukiem","description":"Stań boso i utrzymaj trójnóg stopy, delikatnie unosząc łuk bez podwijania palców.","dose":"20-30 s x 3","tip":"Palce rozluźnione."},{"kind":"POZIOM 1 - łatwy","title":"Rozciąganie palucha w siadzie","description":"Załóż nogę na nogę i delikatnie odciągnij paluch ku górze, czując napięcie pod stopą.","dose":"15-20 s x 3","tip":"Bez ostrego bólu."},{"kind":"POZIOM 2 - średni","title":"Krótka stopa w staniu","description":"Aktywuj łuk stopy bez zginania palców i utrzymaj kilka sekund.","dose":"5-8 s x 8-10","tip":"Nacisk pod piętą i podstawami I/V śródstopia."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia z ręcznikiem pod palcami","description":"Umieść zrolowany ręcznik pod palcami i wykonuj powolne wspięcia na palce.","dose":"8-12 x 2-3","tip":"Zacznij obunóż."}]},{"id":"cat30","name":"Równowaga i stabilizacja","goal":"Poprawa kontroli postawy, reakcji równoważnych i pewności w podporze jednonóż.","note":"Zapewnij stabilne podparcie w zasięgu ręki. Przy częstych upadkach potrzebna jest pełna ocena ryzyka upadku.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra - Tadasana","description":"Stań boso lub w stabilnym obuwiu, ciężar rozłóż równo na stopach i utrzymuj wzrok na stałym punkcie.","dose":"30-60 s x 2","tip":"Oddychaj swobodnie."},{"kind":"JOGA 2","title":"Drzewo z podparciem","description":"Stań przy ścianie, oprzyj stopę nogi wolnej o kostkę lub łydkę i utrzymaj pozycję.","dose":"15-30 s/stronę x 2","tip":"Nie stawiaj stopy bezpośrednio na kolanie."},{"kind":"POZIOM 1 - łatwy","title":"Przenoszenie ciężaru bok-bok","description":"Stań szerzej i powoli przenoś ciężar z jednej nogi na drugą bez unoszenia stóp.","dose":"10-15/stronę x 2","tip":"Miednica nad stopą podporową."},{"kind":"POZIOM 2 - średni","title":"Stanie tandem","description":"Ustaw jedną stopę przed drugą jak na linie i utrzymaj równowagę.","dose":"20-40 s x 2-3","tip":"Podparcie ręką dostępne."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż z sięganiem","description":"Stań na jednej nodze i wykonuj drugą stopą lekkie sięgnięcia w przód, bok i tył.","dose":"5-8 kierunków/stronę x 2","tip":"Ruch wolny i kontrolowany."}]},{"id":"cat31","name":"Chód / przenoszenie ciężaru / wysoki marsz","goal":"Poprawa inicjacji kroku, obciążania kończyn i kontroli stopy podczas chodu.","note":"Przy chorobach neurologicznych dobierz objętość do zmęczenia, spastyczności i bezpieczeństwa. Nowy nagły deficyt wymaga diagnostyki.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra z przenoszeniem ciężaru","description":"Stań stabilnie i powoli przesuwaj ciężar przód-tył oraz bok-bok w małym zakresie.","dose":"45-60 s x 2","tip":"Nie odrywaj stóp."},{"kind":"JOGA 2","title":"Wojownik II przy podparciu","description":"Stań szeroko przy blacie, ugnij jedną nogę i utrzymaj stabilne obciążenie obu stóp.","dose":"20 s/stronę x 2","tip":"Podparcie ręką dozwolone."},{"kind":"POZIOM 1 - łatwy","title":"Marsz w miejscu z wysokim unoszeniem kolan","description":"Trzymając się blatu unoś naprzemiennie kolana do wygodnej wysokości.","dose":"10-20/stronę x 2","tip":"Tułów możliwie pionowo."},{"kind":"POZIOM 2 - średni","title":"Krok w przód i powrót","description":"Z pozycji stojącej wykonaj krok w przód, przenieś ciężar na przednią nogę i wróć.","dose":"8-12/stronę x 2","tip":"Pełny kontakt stopy z podłożem."},{"kind":"POZIOM 3 - trudniejszy","title":"Chód po linii z zatrzymaniem","description":"Idź powoli po wyznaczonej linii, co kilka kroków zatrzymaj się i ustabilizuj.","dose":"2-4 przejścia","tip":"Asekuracja według potrzeb."}]},{"id":"cat32","name":"Stopa po unieruchomieniu / po gipsie","goal":"Odzyskanie ruchomości stawu skokowego, kontroli stopy, siły łydki i pewnego obciążania po zakończeniu unieruchomienia.","note":"Zakres obciążania musi być zgodny z zaleceniem lekarza prowadzącego. Narastający obrzęk, zaczerwienienie lub ból łydki wymagają oceny.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - odciążony","description":"Z podporu unieś biodra, pozostaw kolana ugięte i przenoś delikatnie ciężar między stopami.","dose":"15-25 s x 2","tip":"Bez forsowania pięty."},{"kind":"JOGA 2","title":"Góra z równym obciążeniem","description":"Stań przy podparciu i stopniowo wyrównuj ciężar na obu stopach.","dose":"30-45 s x 2-3","tip":"Nie unikaj stopy, ale też nie przekraczaj zaleceń obciążania."},{"kind":"POZIOM 1 - łatwy","title":"Alfabet stopą","description":"Siedząc wykonuj stopą małe ruchy jak przy pisaniu liter alfabetu.","dose":"1 alfabet lub 1-2 min","tip":"Ruch z kostki, nie całej nogi."},{"kind":"POZIOM 2 - średni","title":"Kolano do ściany","description":"Przy pięcie na podłożu przesuwaj kolano w stronę ściany i wracaj.","dose":"8-12 x 2","tip":"Bez ostrego bólu."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż przy podparciu","description":"Przenieś ciężar na leczoną nogę i utrzymaj równowagę przy ścianie lub blacie.","dose":"15-30 s x 2-3","tip":"Nie progresuj, jeśli obrzęk wyraźnie narasta."}]},{"id":"cat33","name":"Wzmocnienie pośladków","goal":"Aktywacja mięśni pośladkowych i nauka wyprostu biodra bez przejmowania ruchu przez odcinek lędźwiowy.","note":"Ćwiczenia mają być odczuwalne głównie w pośladkach. Przy bólu promieniującym, ostrym bólu biodra lub nasileniu objawów neurologicznych zmniejsz zakres i dobierz ćwiczenie do badania.","source":"supplement_user_requested","exercises":[{"kind":"JOGA 1","title":"Most - Setu Bandha, łagodnie","description":"Połóż się na plecach, zegnij kolana i ustaw stopy na szerokość bioder. Unieś miednicę tylko do wysokości, przy której czujesz pracę pośladków bez mocnego wyginania lędźwi.","dose":"20-30 s x 2-3","tip":"Żebra utrzymuj spokojnie, nacisk rozłóż na całych stopach."},{"kind":"JOGA 2","title":"Krzesło - Utkatasana, płytko","description":"Stań na szerokość bioder, cofnij biodra jak do siadania i ugnij kolana w małym zakresie. Utrzymaj ciężar na całych stopach.","dose":"15-25 s x 2-3","tip":"Poczuj pośladki i uda; kolana prowadź w osi stóp."},{"kind":"POZIOM 1 - łatwy","title":"Izometryczne napięcie pośladków","description":"Leżąc na plecach lub brzuchu napnij oba pośladki bez unoszenia miednicy. Utrzymaj napięcie, oddychaj swobodnie i rozluźnij.","dose":"5-8 s x 8-10","tip":"Nie napinaj mocno brzucha ani lędźwi."},{"kind":"POZIOM 2 - średni","title":"Most biodrowy","description":"Leżenie na plecach, kolana ugięte. Napnij pośladki i unieś biodra do linii barki-biodra-kolana, następnie powoli opuść.","dose":"8-12 x 2-3 serie","tip":"Nie wypychaj brzucha i nie przeprostuj lędźwi."},{"kind":"POZIOM 3 - trudniejszy","title":"Odwodzenie nogi bokiem","description":"Połóż się na boku. Górną nogę wyprostuj, ustaw palce do przodu i unieś nogę lekko w bok, bez obracania miednicy.","dose":"10-15/stronę x 2-3","tip":"Ruch ma być mały i kontrolowany; poczuj boczny pośladek."}]}]},{"meta":{"id":"week2","label":"+2. tydzień","short":"+2 tydzień","desc":"Progresja - większa kontrola, nieco większy zakres lub dłuższy czas pracy."},"categories":[{"id":"cat01","name":"Rwa kulszowa","goal":"Łagodne utrzymanie ruchu, poprawa tolerancji obciążenia i ślizgu struktur nerwowych bez nasilania objawów w nodze.","note":"W rwie nie ma jednego dobrego kierunku ruchu dla wszystkich. Wybieraj ćwiczenia, po których ból/drętwienie nie schodzi dalej do stopy. Pilna konsultacja: drętwienie okolicy krocza, zaburzenia oddawania moczu/stolca, szybko narastające osłabienie nogi lub objawy obustronne.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Sfinks z aktywnym wydłużeniem","description":"Połóż się na brzuchu, oprzyj przedramiona pod barkami i unieś klatkę bez zaciskania pośladków. Biodra zostają na podłożu. Oddychaj spokojnie. Wykonuj tylko wtedy, gdy objawy w nodze nie nasilają się ani nie schodzą niżej. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Ruch ma być komfortowy; może być odczuwalny w plecach, ale nie powinien zwiększać promieniowania.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Pozycja dziecka z sięganiem bocznym","description":"Usiądź pośladkami w kierunku pięt, kolana ustaw szerzej i wyciągnij ręce do przodu. Nie wciskaj się na siłę w zgięcie. Jeśli zgięcie nasila promieniowanie, pomiń tę pozycję. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Wybieraj tylko kierunek, po którym noga czuje się tak samo lub lepiej.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Ślizg nerwu w większym bezbolesnym zakresie","description":"Połóż się na plecach. Zegnij biodro i kolano do wygodnej pozycji, podtrzymując udo rękami. Powoli prostuj kolano i jednocześnie kieruj palce stopy do siebie; wracając, zegnij kolano i rozluźnij stopę. To ma być płynny ślizg, nie mocne rozciąganie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Bez długiego przytrzymania i bez wywoływania narastającego mrowienia.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Most z pauzą 2-3 s","description":"Leżenie na plecach, kolana ugięte, stopy na szerokość bioder. Lekko napnij brzuch i unieś miednicę do linii barki-biodrakolana. Opuść powoli. Nie wyginaj mocno odcinka lędźwiowego. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ciężar rozłóż równo na obu stopach.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Bird dog z pauzą 3 s","description":"Klęk podparty. Utrzymaj spokojny tułów i wyprostuj jednocześnie jedną nogę oraz przeciwną rękę. Wróć bez kołysania miednicą i zmień stronę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zakres kończyny mniejszy, jeśli pojawia się ból promieniujący.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat02","name":"Przodopochylenie miednicy","goal":"Nauka ustawienia miednicy bliżej pozycji neutralnej, poprawa kontroli mięśni brzucha i pośladków oraz tolerancji wyprostu biodra.","note":"Samo przodopochylenie nie jest chorobą. Ćwiczymy wtedy, gdy to ustawienie wiąże się z bólem, przeciążeniem lub słabą kontrolą ruchu.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Niski wykrok z podwinięciem miednicy - progresja","description":"Z klęku wysuń jedną stopę do przodu. Delikatnie podwiń miednicę „ogon pod siebie”, napnij pośladek nogi zakrocznej i przesuń tułów minimalnie do przodu. Nie rób przeprostu lędźwi. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Rozciąganie powinno być z przodu biodra nogi zakrocznej.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Pozycja dziecka z sięganiem bocznym","description":"Usiądź w kierunku pięt i wydłuż plecy, wyciągając ręce przed siebie. Oddychaj do dolnych żeber i rozluźnij odcinek lędźwiowy. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie dociskaj pośladków na siłę do pięt.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Tyłopochylenie miednicy w leżeniu - progresja","description":"Leżenie na plecach, kolana ugięte. Na wydechu delikatnie zbliż dolne żebra do miednicy i spłaszcz lędźwie do podłoża. Wróć do neutralnej pozycji bez odrywania stóp. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch ma pochodzić z miednicy, nie z mocnego napinania szyi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Most z pauzą 2-3 s","description":"Najpierw delikatnie ustaw miednicę neutralnie lub lekko podwiń, potem unieś biodra. Utrzymaj żebra „nad miednicą”, bez wypychania brzucha w górę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Poczuj pośladki, nie tylko lędźwie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Wykrok w tył z kontrolą tułowia - progresja","description":"Stań prosto, zrób krok w tył i zejdź w dół. Utrzymuj żebra nad miednicą, brzuch lekko aktywny i pośladek nogi podporowej napięty. Wróć do stania. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie pozwalaj, aby miednica uciekała w duży przeprost lędźwiowy.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat03","name":"Tyłopochylenie miednicy","goal":"Poprawa tolerancji lekkiego wyprostu, nauka swobodnego przodopochylenia miednicy i lepszego zgięcia w biodrach zamiast „podwijania” całych pleców.","note":"Tyłopochylenie samo w sobie bywa wariantem postawy. Ćwiczenia mają poprawiać kontrolę ruchu, a nie wymuszać jedną stałą pozycję.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Sfinks z aktywnym wydłużeniem","description":"Połóż się na brzuchu i oprzyj na przedramionach. Unieś mostek, pozostawiając biodra i brzuch rozluźnione. Nie zaciskaj odcinka lędźwiowego. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Oddychaj spokojnie; zmniejsz zakres przy bólu lędźwi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Krowa w klęku podpartym - progresja","description":"Z klęku podpartego delikatnie unieś kość ogonową i mostek, tworząc łagodny łuk. Nie zapadaj się w barkach. Następnie wróć do neutralnej pozycji. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Ruch wykonuj segmentalnie i bez bólu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Przodopochylenie miednicy w siadzie - progresja","description":"Usiądź na brzegu krzesła. Bez poruszania klatką piersiową przetocz miednicę do przodu tak, aby poczuć ciężar bardziej na przedniej części guzów kulszowych. Wróć do środka. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Mały, precyzyjny ruch jest lepszy niż duże wyginanie pleców.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Hip hinge przy ścianie - progresja","description":"Stań 20-30 cm przed ścianą tyłem do niej. Cofnij biodra, jakbyś chciał dotknąć pośladkami ściany, utrzymując długi kręgosłup. Wróć przez wyprost bioder. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Kolana lekko ugięte, ciężar na całej stopie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Skłon rumuński bez obciążenia - progresja","description":"Stań prosto. Cofnij biodra i pochyl tułów z prostym, wydłużonym kręgosłupem, aż poczujesz tył ud. Wróć, napinając pośladki. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie podwijaj miednicy w dolnej fazie i nie zaokrąglaj lędźwi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat04","name":"Koślawość kolan","goal":"Poprawa kontroli osi biodro-kolano-stopa podczas przysiadu, wstawania i podporu jednonóż.","note":"U dzieci i dorosłych część koślawości może wynikać z budowy anatomicznej. Ćwiczenia poprawiają kontrolę funkcjonalną, ale nie „prostują kości”.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Wojownik II z dłuższym utrzymaniem","description":"Stań szeroko. Ugnij przednie kolano nad stopą, pilnując aby kierowało się w stronę 2.-3. palca. Tylna noga wyprostowana, miednica stabilna. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Kolano nie zapada się do środka.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Krzesło - dłuższe utrzymanie","description":"Stań na szerokość bioder, cofnij biodra jak do siadania i ugnij kolana. Utrzymuj stopy w trzech punktach podparcia i kolana nad stopami. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie ściskaj kolan na siłę; utrzymuj naturalną oś.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Odwodzenie nogi bokiem w leżeniu - progresja","description":"Połóż się na boku, dolna noga może być ugięta. Górną nogę wyprostuj i unieś lekko w bok, z palcami skierowanymi do przodu. Powoli opuść. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie obracaj miednicy do tyłu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wstawanie z niższego krzesła","description":"Usiądź na brzegu krzesła, stopy na szerokość bioder. Wstań, utrzymując kolana w osi stóp, potem powoli usiądź. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Możesz zacząć od wyższego krzesła.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad jednonóż do krzesła - progresja","description":"Stań przed wysokim krzesłem na jednej nodze. Cofnij biodro i dotknij pośladkiem siedziska, następnie wstań. Kolano utrzymuj nad 2.-3. palcem stopy. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zacznij od bardzo wysokiego podparcia i małego zakresu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat05","name":"Płaskostopie","goal":"Aktywacja mięśni krótkich stopy, poprawa kontroli łuku podłużnego i równowagi bez „zaciskania” palców.","note":"Ćwiczenia mogą poprawiać funkcję stopy, ale nie każda płaska stopa wymaga korekcji. Szczególnie u dzieci ocena zależy od wieku, elastyczności i objawów.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Góra - Tadasana z „trójnogiem” stopy - progresja","description":"Stań boso. Dociśnij trzy punkty: piętę, podstawę palucha i podstawę małego palca. Palce rozluźnione. Delikatnie unieś łuk stopy bez podwijania palców. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Ciężar równomiernie na całej stopie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Pies z głową w dół - progresja","description":"Z podporu unieś biodra w górę i cofnij je. Pięty mogą zostać uniesione. Wydłużaj tył nóg i łydki bez bólu w stopie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie wymuszaj kontaktu pięt z podłożem.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Krótka stopa w staniu","description":"Siedząc lub stojąc, utrzymaj piętę i głowy I oraz V kości śródstopia na podłożu. Delikatnie „skróć” stopę, przyciągając przodostopie w stronę pięty bez zginania palców. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Palce mają pozostać długie i rozluźnione.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wspięcia z pauzą w górze","description":"Stań przy ścianie. Utrzymaj trójnóg stopy i unieś pięty. Powoli zejdź w dół, nie pozwalając kostkom zapadać się do środka. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nacisk pozostaje także pod podstawą palucha.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż z krótką stopą - progresja","description":"Stań na jednej nodze i utrzymaj aktywny łuk bez chwytania podłoża palcami. Gdy jest łatwo, wykonuj powolne ruchy drugą nogą w przód, bok i tył. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Kolano ustawione nad stopą, miednica stabilna.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat06","name":"Wzmocnienie mięśni core","goal":"Poprawa kontroli tułowia podczas ruchu kończyn, bez wstrzymywania oddechu i bez nadmiernego usztywnienia.","note":"„Core” to nie tylko mięśnie brzucha. W ćwiczeniach współpracują przepona, mięśnie brzucha, grzbietu, dna miednicy i obręczy biodrowej.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Deska - dłuższa pauza","description":"Oprzyj dłonie lub przedramiona pod barkami. Utrzymaj linię głowa-tułów-miednica. Zacznij od wersji na kolanach, potem przejdź na stopy. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Oddychaj, nie zapadaj lędźwi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Łódka - łatwa wersja - progresja","description":"Usiądź, ugnij kolana i odchyl tułów lekko do tyłu. Unieś jedną, a potem obie stopy, utrzymując długi kręgosłup. Ręce mogą trzymać uda. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Zmniejsz zakres, jeśli czujesz lędźwie bardziej niż brzuch.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Napięcie brzucha + ślizg pięty - progresja","description":"Leżenie na plecach, kolana ugięte. Delikatnie napnij brzuch jak przed kaszlnięciem i wysuwaj jedną piętę po podłożu, nie zmieniając ustawienia miednicy. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Oddychaj swobodnie przez cały ruch.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Dead bug - progresja","description":"Leżenie na plecach, biodra i kolana około 90°. Utrzymując stabilny tułów, opuszczaj jedną piętę w stronę podłogi i wracaj. Trudniej: dodaj przeciwną rękę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Plecy nie muszą być mocno dociśnięte - ważna jest kontrola bez bólu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Deska - dłuższa pauza","description":"Pozycja wysokiej deski. Oderwij jedną dłoń i dotknij przeciwnego barku, nie kołysząc miednicą. Zmień stronę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ustaw stopy szerzej, jeśli trudno utrzymać stabilność.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat07","name":"Poprawa ruchomości całego kręgosłupa","goal":"Łagodny ruch odcinka szyjnego, piersiowego i lędźwiowego w kilku kierunkach, bez forsowania końcowych zakresów.","note":"Przy osteoporozie, świeżym urazie, zawrotach głowy po ruchu szyi lub objawach neurologicznych zakres powinien ustalić fizjoterapeuta.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Kot-krowa z oddechem","description":"W klęku podpartym na wydechu zaokrąglij plecy i opuść głowę, a na wdechu delikatnie unieś mostek i kość ogonową. Ruch prowadź płynnie od miednicy po szyję. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie dociskaj szyi do końcowego zakresu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Sfinks z aktywnym wydłużeniem","description":"Z pozycji dziecka przejdź płynnie do leżenia na brzuchu i podeprzyj się na przedramionach w sfinksie. Następnie wróć. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Ruch spokojny, bez ostrego bólu i bez szarpania.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie książki z pełniejszym oddechem","description":"Leżenie na boku, biodra i kolana ugięte, ręce wyciągnięte przed sobą. Otwórz górną rękę do tyłu, prowadząc za nią klatkę piersiową. Kolana pozostają razem. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Głowa może podążać za dłonią, jeśli nie wywołuje zawrotów.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wyprost piersiowy na krześle - progresja","description":"Usiądź, oprzyj górną część pleców o oparcie. Dłonie za głową. Delikatnie odchyl klatkę piersiową nad oparciem, bez dużego przeprostu lędźwi. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch ma być głównie w piersiowym odcinku kręgosłupa.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Skłon + wyprost segmentalny w staniu - progresja","description":"Z pozycji stojącej powoli opuszczaj brodę i zaokrąglaj kręgosłup od góry, schodząc tylko do wygodnego zakresu. Wróć powoli, ustawiając kręgi „jeden po drugim”. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie wykonuj przy osteoporozie bez wcześniejszej konsultacji.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat08","name":"Ból głowy","goal":"Zmniejszenie napięcia szyi i obręczy barkowej przy bólach napięciowych lub szyjnopochodnych oraz poprawa kontroli odcinka szyjnego.","note":"Te ćwiczenia nie są przeznaczone do nagłego, bardzo silnego bólu głowy ani bólu z niedowładem/drętwieniem twarzy lub kończyn, zaburzeniami mowy, widzenia, równowagi, gorączką ze sztywnością karku albo po urazie głowy.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pozycja dziecka z sięganiem bocznym","description":"Usiądź w kierunku pięt, oprzyj czoło na dłoniach lub poduszce i pozwól barkom opaść. Oddychaj spokojnie, wydłużając wydech. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Szyja ma być całkowicie rozluźniona.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Nogi na ścianie - Viparita Karani - progresja","description":"Połóż się na plecach blisko ściany i oprzyj na niej nogi. Podeprzyj głowę cienką poduszką, jeśli tego potrzebujesz. Rozluźnij szczękę i barki. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Pomiń, jeśli pozycja zwiększa ból głowy lub ciśnienie w głowie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody przy ścianie","description":"Siedząc lub leżąc, przesuń głowę poziomo do tyłu, jakbyś robił delikatny „podwójny podbródek”. Nie pochylaj głowy w dół. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch ma być mały i bez bólu promieniującego.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Łopatki w dół i lekko do tyłu - progresja","description":"Usiądź prosto. Delikatnie ustaw łopatki w dół i do środka, bez wypinania klatki i bez unoszenia barków. Utrzymaj, rozluźnij. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie ściskaj łopatek maksymalnie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrolowana rotacja szyi - progresja","description":"Usiądź prosto. Powoli obróć głowę w prawo do komfortowego zakresu, wróć do środka i powtórz w lewo. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Przerwij przy zawrotach, zaburzeniach widzenia lub wyraźnym nasileniu bólu głowy.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat09","name":"Ból karku","goal":"Utrzymanie ruchomości szyi, aktywacja głębokich mięśni szyi i poprawa pracy łopatek.","note":"Przy bólu po urazie, nasilającej się słabości ręki, niezgrabności dłoni, zaburzeniach chodu lub nowych zaburzeniach zwieraczy potrzebna jest pilna ocena lekarska.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Szczeniak - Uttana Shishosana - progresja","description":"Z klęku podpartego cofnij biodra lekko w stronę pięt, a dłonie wysuń daleko do przodu. Klatkę kieruj w dół, ale szyję utrzymuj długą i swobodną. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie wciskaj głowy w podłoże.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Orzeł - same ramiona - progresja","description":"Siedząc lub stojąc, skrzyżuj ramiona przed sobą i połącz przedramiona tak, jak pozwala zakres. Unieś łokcie lekko, oddychając w górną część pleców. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Barki pozostają z dala od uszu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody przy ścianie","description":"Przesuń głowę prosto do tyłu, utrzymując wzrok na wprost. Utrzymaj krótko i wróć. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie unoś ani nie opuszczaj brody.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Izometria szyi - progresja","description":"Połóż dłoń na czole i delikatnie napieraj głową na dłoń bez ruchu. Powtórz z dłonią z boku głowy po obu stronach. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Siła umiarkowana, bez zaciskania zębów.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Anioł przy ścianie - progresja","description":"Oprzyj plecy o ścianę, broda lekko cofnięta. Przesuwaj ramiona po ścianie w górę i w dół w wygodnym zakresie, utrzymując łopatki pod kontrolą. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie wypychaj żeber do przodu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat10","name":"Drętwienie palców u dłoni","goal":"Łagodny ruch szyi, łopatki i nerwów kończyny górnej po wcześniejszej ocenie przyczyny objawów.","note":"Drętwienie palców może pochodzić z szyi, nadgarstka, łokcia lub innych przyczyn. Zestaw należy dobrać do rozpoznania. Pilna ocena, jeśli narasta osłabienie/chwyt, pojawia się niezgrabność obu rąk, zaburzenia chodu lub nagłe objawy neurologiczne.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Góra z rozluźnieniem barków - progresja","description":"Stań prosto, dłonie skieruj do przodu, barki opuść i wydłuż szyję. Zrób 5-6 spokojnych oddechów, nie zaciskając palców. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Dłonie i szczęka pozostają rozluźnione.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Anjali Mudra - dłonie przed klatką - progresja","description":"Złącz dłonie przed mostkiem bez mocnego dociskania. Ustaw nadgarstki neutralnie lub tylko lekko zgięte. Oddychaj spokojnie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Jeśli drętwienie się nasila, zmniejsz zgięcie nadgarstka lub pomiń.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody przy ścianie","description":"Usiądź prosto. Lekko cofnij brodę, a łopatkę po stronie objawów ustaw swobodnie w dół. Nie ciągnij barku na siłę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Objawy w dłoni nie powinny narastać.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu w większym bezbolesnym zakresie","description":"Ramię przy boku, łokieć zgięty. Powoli prostuj łokieć, jednocześnie odchylając nadgarstek i palce tylko do lekkiego napięcia, potem wróć. Stosuj szczególnie, gdy objawy obejmują kciuk, palec wskazujący i środkowy - po ocenie fizjoterapeuty. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"To ma być ślizg, nie mocne rozciąganie. Nie przytrzymuj końcowej pozycji.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Ślizg ramion po ścianie z pauzą","description":"Stań twarzą do ściany, przedramiona oprzyj o nią. Powoli przesuwaj ręce w górę, pozwalając łopatkom obracać się w górę, potem wróć. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Przerwij, jeśli drętwienie wyraźnie narasta lub utrzymuje się po ćwiczeniu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat11","name":"Drętwienie pośladków","goal":"Poprawa ruchu lędźwi i bioder oraz tolerancji pozycji siedzącej, jeśli przyczyna ma charakter mechaniczny i poważne przyczyny neurologiczne zostały wykluczone.","note":"Drętwienie obu pośladków lub okolicy krocza, zwłaszcza z zaburzeniami oddawania moczu/stolca, jest objawem alarmowym - nie ćwiczyć, tylko pilnie zgłosić się do pomocy medycznej.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Gołąb na plecach - „4” - progresja","description":"Leżąc na plecach, połóż kostkę jednej nogi na przeciwległym udzie. Przyciągnij udo do siebie tylko do łagodnego rozciągania pośladka. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie dociskaj kolana na siłę.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Kot-krowa z oddechem","description":"W klęku podpartym naprzemiennie zaokrąglaj i delikatnie wyginaj kręgosłup, poruszając miednicą. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Wybierz zakres, który nie zwiększa drętwienia.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Przetaczanie miednicy w leżeniu - progresja","description":"Leżenie na plecach, kolana ugięte. Naprzemiennie delikatnie spłaszczaj lędźwie i wracaj do lekkiego łuku. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch ma być mały i płynny.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu w większym bezbolesnym zakresie","description":"Leżenie na plecach. Unieś udo, podtrzymując je rękami. Prostuj i zginaj kolano w małym zakresie, synchronizując ruch stopy tak, aby nie utrzymywać napięcia. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Bez nasilania drętwienia po ćwiczeniu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Most z pauzą 2-3 s","description":"Unieś miednicę z leżenia na plecach, utrzymując ciężar na obu stopach i spokojny oddech. Powoli wróć. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Jeśli objawy stają się bardziej rozlane lub schodzą niżej do nogi - przerwij.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat12","name":"Drętwienie ud","goal":"Poprawa ruchomości biodra i odcinka lędźwiowego oraz zmniejszenie drażnienia tkanek w okolicy pachwiny/uda, gdy objawy są ocenione jako mechaniczne.","note":"Drętwienie bocznej części uda może mieć inne źródło niż drętwienie przedniej lub tylnej części. Przy narastającej słabości nogi, zaburzeniu chodu lub objawach obustronnych wymagana jest ocena neurologiczna.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Niski wykrok - progresja","description":"Jedna noga z przodu, drugie kolano na podłożu. Delikatnie podwiń miednicę i przesuń ją do przodu, czując przód biodra nogi zakrocznej. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie rób przeprostu lędźwi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Sfinks z aktywnym wydłużeniem","description":"Leżenie na brzuchu, podpór na przedramionach. Unieś klatkę do komfortowego wyprostu. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Wykonuj tylko, jeśli nie zwiększa drętwienia w udzie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Kołysanie miednicą w leżeniu - progresja","description":"Leżenie na plecach, kolana ugięte. Powoli przechodź między lekkim spłaszczeniem i lekkim łukiem lędźwi. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Bez forsowania końcowego zakresu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Rozciąganie zginaczy biodra w półklęku - progresja","description":"Z półklęku podwiń miednicę i napnij pośladek nogi z tyłu. Przesuń ciało lekko do przodu. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie dociskaj do bólu lub mrowienia.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Wykrok w tył - progresja","description":"Z pozycji stojącej cofnij jedną nogę i obniż ciało. Wróć do stania, aktywnie pracując pośladkiem nogi podporowej. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Utrzymuj stabilną miednicę i kolano nad stopą.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat13","name":"Drętwienie łydek","goal":"Łagodny ruch nerwowo-mięśniowy kończyny dolnej, poprawa pracy stawu skokowego i łydki po wcześniejszej ocenie źródła drętwienia.","note":"Nagłe drętwienie z wyraźnym osłabieniem stopy, opadaniem stopy, obustronnymi objawami lub zaburzeniami zwieraczy wymaga pilnej oceny. Obrzęk, zaczerwienienie i ból łydki wymagają wykluczenia problemu naczyniowego.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół z ugiętymi kolanami - progresja","description":"Z podporu unieś biodra. Kolana pozostaw lekko ugięte i naprzemiennie kieruj pięty w dół, bez mocnego ciągnięcia łydki. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie trzymaj rozciągnięcia, jeśli wywołuje mrowienie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Skłon do jednej nogi w siadzie - łagodny - progresja","description":"Usiądź z jedną nogą wyprostowaną, drugą ugiętą. Pochyl się z bioder tylko do lekkiego napięcia tyłu nogi. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Przy drętwieniu nie pogłębiaj rozciągania nerwu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Pompowanie stopy - progresja","description":"Siedząc lub leżąc, naprzemiennie kieruj palce stopy do siebie i od siebie w pełnym, komfortowym zakresie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch płynny, bez bolesnego skurczu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu w większym bezbolesnym zakresie","description":"Usiądź prosto. Prostuj kolano i jednocześnie unieś głowę; wracając zginaj kolano i lekko opuszczaj brodę. Ruch wykonuj płynnie, bez przytrzymania. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zakres ma nie zwiększać mrowienia po serii.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia z pauzą w górze","description":"Stań przy ścianie. Unieś piętę jednej nogi, powoli opuść. Utrzymuj stopę w osi i nie skręcaj kostki. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Jeśli pojawia się narastająca słabość, zakończ i skonsultuj objaw.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat14","name":"Poprawa ruchomości stawów skokowych","goal":"Poprawa zgięcia grzbietowego, ruchomości łydki i kontroli stopy potrzebnej do chodu, przysiadu i schodów.","note":"Po świeżym skręceniu, złamaniu lub operacji zakres obciążania powinien wynikać z zaleceń prowadzącego lekarza/fizjoterapeuty.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - naprzemienne pięty - progresja","description":"Ustaw się w psie z głową w dół. Naprzemiennie uginaj jedno kolano i kieruj przeciwną piętę w stronę podłoża. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Pięta nie musi dotykać podłogi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Krzesło - dłuższe utrzymanie","description":"Z pozycji stojącej cofnij biodra i ugnij kolana, utrzymując pięty na podłożu. Kolana przesuwają się nad stopami w komfortowym zakresie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie zapadaj łuków stóp do środka.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Kolano do ściany z większym zakresem","description":"Stań przodem do ściany, stopa płasko. Prowadź kolano do ściany nad 2.-3. palcem bez odrywania pięty. Jeśli łatwo - odsuń stopę od ściany. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Kolano nie zapada się do środka.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wspięcia z pauzą w górze","description":"Stań na obu stopach przy ścianie. Unieś pięty wysoko, zatrzymaj 1 s i opuszczaj przez 3 s. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch symetryczny, ciężar na podstawie palucha i małego palca.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad głęboki z podparciem - progresja","description":"Trzymając się stabilnego oparcia, zejdź do przysiadu tak głęboko, jak pozwalają biodra i kostki. Pięty pozostają na podłożu. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie wymuszaj głębokości kosztem bólu kolan lub stóp.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat15","name":"Poprawa ruchomości bioder","goal":"Ruch biodra w zgięciu, wyproście, rotacji i odwiedzeniu przy możliwie stabilnej miednicy.","note":"Przy nasilającym się bólu pachwiny, blokowaniu stawu lub bólu nocnym zakres powinien być oceniony indywidualnie.","source":"original17","exercises":[{"kind":"JOGA 1","title":"90/90 - progresja","description":"Usiądź z jedną nogą z przodu i drugą z boku, obie ugięte około 90°. Usiądź wysoko, a następnie delikatnie pochyl tułów nad przednią nogą. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie dociskaj kolan na siłę do podłogi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Niski wykrok - progresja","description":"Z półklęku podwiń lekko miednicę i przesuń ją do przodu, czując przód biodra nogi zakrocznej. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie wyginaj lędźwi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Kolano do klatki + krążenie biodrem - progresja","description":"Leżąc na plecach, przyciągnij jedno kolano do komfortowego zakresu i wykonuj małe kółka udem w stawie biodrowym. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Miednica pozostaje możliwie spokojna.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wycieraczki w leżeniu - progresja","description":"Leżenie na plecach, kolana ugięte, stopy szerzej. Opuszczaj oba kolana w jedną stronę, wróć i powtórz w drugą. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zakres bez bólu w pachwinie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad kozacki - progresja","description":"Stań szeroko. Przenieś ciężar na jedną nogę, uginając ją, a drugą pozostaw bardziej wyprostowaną. Wróć przez środek i zmień stronę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zacznij płytko i trzymaj się oparcia, jeśli potrzeba.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat16","name":"Rozluźnienie przepony","goal":"Zmniejszenie nadmiernego udziału górnej klatki i mięśni pomocniczych oddechu, poprawa spokojnego oddechu dolnożebrowego.","note":"Ćwiczenia oddechowe wykonuj bez forsowania. Jeśli pojawi się zawrót głowy, przerwij, odpocznij i wróć do naturalnego oddechu.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pozycja krokodyla - Makarasana - progresja","description":"Połóż się na brzuchu, czoło oprzyj na złożonych dłoniach. Pozwól, by przy wdechu dolne żebra i brzuch delikatnie naciskały na podłoże. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Barki, szyja i szczęka rozluźnione.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Pozycja dziecka z sięganiem bocznym","description":"Usiądź w kierunku pięt, oprzyj czoło. Wdychaj powietrze „do dolnych żeber i pleców”, a na wydechu rozluźniaj brzuch i barki. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie staraj się nabierać maksymalnie dużo powietrza.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Oddech 360° w leżeniu - progresja","description":"Połóż dłonie na dolnych żebrach. Wdech nosem: żebra delikatnie rozszerzają się na boki i do tyłu. Wydech: swobodnie opadają. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Górna część klatki porusza się niewiele.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wydłużony wydech - progresja","description":"Wdech nosem przez około 3-4 s, następnie spokojny wydech przez lekko złączone usta przez 5-7 s. Nie opróżniaj płuc na siłę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Jeśli kręci się w głowie - skróć oddech i zrób przerwę.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Oddech boczno-żebrowy w leżeniu na boku - progresja","description":"Połóż się na boku, górną dłoń połóż na dolnych żebrach. Kieruj wdech pod dłoń, a przy wydechu pozwól żebrom opaść. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Oddychaj cicho i bez unoszenia barku.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat17","name":"Wzmocnienie przepony","goal":"Poprawa kontroli i wytrzymałości oddechowej bez sprzętu poprzez pracę przepony w coraz trudniejszych pozycjach i podczas lekkiego wysiłku.","note":"Bez urządzenia z oporem są to głównie ćwiczenia kontroli i wytrzymałości oddechowej, nie precyzyjny trening siły mięśni wdechowych. Przy chorobach płuc/serca dawkę należy ustalić indywidualnie.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Most z pauzą 2-3 s","description":"Leżenie na plecach. Na wydechu unieś miednicę do mostu. Utrzymując pozycję, wykonaj 2-3 spokojne oddechy do dolnych żeber i opuść biodra. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie wstrzymuj oddechu w górze.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Krzesło - dłuższe utrzymanie","description":"Stań, cofnij biodra jak do siadania i ugnij kolana. Utrzymuj pozycję, wykonując spokojne wdechy nosem i dłuższe wydechy. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Przerwij przy duszności nieproporcjonalnej do wysiłku lub zawrotach głowy.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Oddech przeponowy w leżeniu - progresja","description":"Połóż jedną dłoń na mostku, drugą na brzuchu/dolnych żebrach. Wdech kieruj w dół i na boki, wydech swobodny. Z czasem wydłużaj serię bez zwiększania objętości pojedynczego oddechu. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch ręki na górnej klatce ma być niewielki.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Oddech przeponowy w klęku podpartym - progresja","description":"Klęk podparty, kręgosłup neutralny. Wdech nosem do boków i tyłu dolnych żeber; wydech spokojny, z lekkim napięciem brzucha. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie zapadaj się w barkach i nie unoś ich przy wdechu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Marsz w miejscu bez stałego podparcia","description":"Maszeruj spokojnie, unosząc kolana do komfortowej wysokości. Utrzymuj rytm: 2-3 kroki na wdech i 3-4 kroki na wydech, bez zadyszki. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Tempo pozwala mówić krótkim zdaniem; przerwij przy bólu w klatce lub znacznej duszności.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat18","name":"Ból barku / stożek rotatorów","goal":"Poprawa tolerancji unoszenia ramienia i stopniowe wzmacnianie stożka rotatorów oraz łopatki.","note":"Ćwiczenia dobieraj do drażliwości. Po świeżym urazie z nagłą utratą siły lub niemożnością uniesienia ramienia wymagana jest dalsza diagnostyka.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Szczeniak przy ścianie - progresja","description":"Stań przed ścianą, oprzyj dłonie i cofnij biodra, wydłużając boki tułowia oraz obręcz barkową bez wciskania barku w ból. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Zakres ma być swobodny; nie unoś barków do uszu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Orzeł - ramiona - progresja","description":"Skrzyżuj ramiona przed klatką, unieś łokcie do wygodnej wysokości i spokojnie oddychaj w górną część pleców. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Bez mrowienia i ostrego bólu barku.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Izometria rotacji zewnętrznej przy ścianie - progresja","description":"Stań bokiem do ściany, łokieć przy tułowiu i delikatnie naciskaj grzbietem dłoni na ścianę bez ruchu barku. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Siła umiarkowana; ból nie powinien narastać po serii.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Ślizg ramion po ścianie z pauzą","description":"Przesuwaj przedramiona w górę po ścianie, utrzymując szyję rozluźnioną i łopatkę płynnie obracającą się ku górze. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie wypychaj żeber do przodu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Scaption bez obciążenia - progresja","description":"Unieś ramiona w płaszczyźnie około 30° przed bokiem ciała do tolerowanego zakresu, powoli opuść. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch kontrolowany, bez szarpania i unoszenia barków.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat19","name":"Kontrola łopatki / dyskineza","goal":"Poprawa kontroli łopatki podczas unoszenia i obciążania kończyny górnej.","note":"Celem nie jest sztywne „ściąganie łopatek”, lecz płynna współpraca łopatki z ramieniem i klatką piersiową.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Koci grzbiet z aktywnym odepchnięciem dłoni - progresja","description":"W klęku podpartym zaokrąglij łagodnie odcinek piersiowy, aktywnie odpychając podłoże i pozwalając łopatkom rozsunąć się. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie zapadaj się między barkami.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Deska - dłuższa pauza","description":"W podporze na dłoniach utrzymaj łokcie proste i delikatnie „odepchnij podłogę”, nie zaokrąglając przesadnie pleców. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Zacznij z kolan, jeśli pełny podpor jest za trudny.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Serratus punch w leżeniu - progresja","description":"Leżąc na plecach unieś rękę do sufitu, a następnie bez zginania łokcia sięgnij dłonią wyżej, unosząc łopatkę od podłoża. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch mały i płynny.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wall slide z wolnym opuszczaniem","description":"Przesuwaj przedramiona po ścianie do góry, utrzymując lekkie odepchnięcie i spokojną szyję. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie dociskaj łopatek do kręgosłupa.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Y przy ścianie - progresja","description":"Stań twarzą do ściany, unieś ręce po skosie do litery Y i delikatnie odklej dłonie bez unoszenia barków. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zakres mniejszy, jeśli pojawia się kompensacja szyją.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat20","name":"Sztywność barku / zamrożony bark","goal":"Stopniowa poprawa tolerancji ruchu i funkcji bez forsowania bolesnego końcowego zakresu.","note":"W wysokiej drażliwości preferuj częste, krótkie i łagodne ruchy. Agresywne rozciąganie może nasilić objawy.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pozycja dziecka z sięganiem bocznym","description":"Oprzyj dłonie na krześle lub łóżku i cofnij biodra, pozwalając barkom wejść w wygodne zgięcie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie wciskaj barku w ból.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Orzeł - łagodny wariant ramion - progresja","description":"Skrzyżuj ramiona przed klatką i unieś łokcie tylko do komfortowego poziomu. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Pomiń przy ostrym bólu przedniej części barku.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Wahadło Codmana - progresja","description":"Podeprzyj się zdrową ręką, rozluźnij bolesną kończynę i wykonuj małe koła oraz ruchy przód-tył. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ramię ma być rozluźnione.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Ślizg ręki po stole - progresja","description":"Siedząc przesuń dłoń po stole do przodu, pozwalając tułowi lekko pochylić się za ręką. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie unoś barku do ucha.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspinanie palcami po ścianie - progresja","description":"Wejdź palcami po ścianie do tolerowanego poziomu i powoli wróć. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie utrzymuj długo bolesnego końca zakresu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat21","name":"Łokieć tenisisty","goal":"Zmniejszenie bólu podczas chwytu i stopniowe zwiększenie tolerancji prostowników nadgarstka na obciążenie.","note":"Zmniejsz przeciążenie chwytu, ale unikaj całkowitego unieruchamiania. Nasilający się deficyt wyprostu palców wymaga diagnostyki neurologicznej.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Dłonie odwrócone w klęku - łagodnie - progresja","description":"W klęku podpartym ustaw dłonie palcami w stronę kolan tylko w tolerowanym zakresie i delikatnie cofnij biodra. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Bez drętwienia i ostrego bólu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Orzeł - ramiona - progresja","description":"Skrzyżuj ramiona i wydłuż tył barków, utrzymując przedramiona rozluźnione. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie zaciskaj dłoni.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Izometria wyprostu nadgarstka - progresja","description":"Przedramię oprzyj na stole, drugą dłonią staw opór grzbietowi ręki bez ruchu w nadgarstku. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Siła umiarkowana.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Powolny wyprost nadgarstka bez ciężaru - progresja","description":"Przedramię na stole, dłoń poza krawędzią. Unieś i bardzo powoli opuść nadgarstek. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch ma być płynny.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrolowany chwyt ręcznika - progresja","description":"Ściskaj zrolowany ręcznik do umiarkowanej siły i powoli rozluźniaj. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie prowokuj bólu utrzymującego się po ćwiczeniu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat22","name":"Łokieć golfisty","goal":"Stopniowe zwiększenie tolerancji zginaczy i pronatorów przedramienia na chwyt i obciążenie.","note":"Przy drętwieniu IV-V palca lub wyraźnym osłabieniu dłoni różnicuj problem z nerwem łokciowym.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Dłonie grzbietami przed klatką - progresja","description":"Połącz grzbiety dłoni przed klatką piersiową i delikatnie opuszczaj łokcie, utrzymując komfort w nadgarstkach. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Bez mrowienia.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Szczeniak z dłońmi na podwyższeniu - progresja","description":"Oprzyj dłonie na krześle, cofnij biodra i wydłuż ramiona oraz boki tułowia. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Łokcie miękkie, bez przeprostu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Izometria zgięcia nadgarstka - progresja","description":"Drugą dłonią staw opór stronie dłoniowej ręki bez wykonywania ruchu. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Siła umiarkowana.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Powolne zgięcie nadgarstka bez ciężaru - progresja","description":"Przedramię na stole, dłoń poza krawędzią. Zegnij i powoli wróć do neutralnej pozycji. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie ściskaj palców.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Pronacja i supinacja kontrolowana - progresja","description":"Z łokciem przy tułowiu obracaj dłoń ku górze i ku dołowi w pełnym komfortowym zakresie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch wolny, łokieć stabilny.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat23","name":"Cieśń nadgarstka / nerw pośrodkowy","goal":"Zmniejszenie prowokacji objawów i utrzymanie łagodnego ślizgu nerwu pośrodkowego oraz ruchomości nadgarstka.","note":"Nasilające się drętwienie, zanik kłębu kciuka lub utrwalona słabość wymagają dalszej diagnostyki.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra z otwartymi dłońmi - progresja","description":"Stań swobodnie, ramiona wzdłuż tułowia, palce dłoni wydłużone i rozluźnione. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie utrzymuj nadgarstków w skrajnym zgięciu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Anjali Mudra - dłonie przed klatką - progresja","description":"Złącz dłonie przed klatką na wysokości, która nie wywołuje parestezji. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Zmniejsz kąt w nadgarstku przy mrowieniu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie i zamykanie dłoni - progresja","description":"Naprzemiennie szeroko rozprostuj palce i lekko zamknij dłoń bez silnego ścisku. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch bez bólu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu w większym bezbolesnym zakresie","description":"Wykonuj stopniowe ustawienia dłoni, łokcia i barku jako płynny ślizg bez utrzymywania napięcia. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie rozciągaj nerwu na końcu ruchu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrola nadgarstka przy lekkim podporze - progresja","description":"Oprzyj dłonie o ścianę i delikatnie przenoś ciężar przód-tył. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Przerwij przy nasileniu drętwienia.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat24","name":"Sztywność odcinka piersiowego / garb posturalny","goal":"Poprawa wyprostu i rotacji odcinka piersiowego oraz pracy łopatek.","note":"Przy osteoporozie unikaj forsownego zgięcia i rotacji; ćwiczenia dobierz indywidualnie.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Szczeniak - Uttana Shishosana - progresja","description":"Z klęku podpartego przesuń dłonie do przodu, pozostawiając biodra nad kolanami i wydłużając klatkę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie zapadaj szyi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Kobra niska - progresja","description":"Leżąc na brzuchu oprzyj przedramiona lub dłonie i unieś mostek, utrzymując ruch głównie w piersiowym odcinku. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Bez kompresji lędźwi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie książki z pełniejszym oddechem","description":"Leżąc na boku obracaj górne ramię i klatkę do tyłu, kolana pozostają razem. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch płynny.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wyprost piersiowy na oparciu - progresja","description":"Usiądź, oprzyj górny odcinek pleców o krawędź oparcia i wykonaj łagodny wyprost. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie odchylaj głowy gwałtownie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Wall angel - progresja","description":"Plecy przy ścianie, przesuwaj ramiona w górę i w dół bez wypychania żeber. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zakres dostosuj do barków.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat25","name":"Ból lędźwiowy nieswoisty","goal":"Utrzymanie ruchu, poprawa kontroli tułowia i stopniowy powrót do obciążeń dnia codziennego.","note":"Nie ma jednego kierunku ruchu dobrego dla wszystkich. Dobieraj ćwiczenia do reakcji objawów i funkcji.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Kot-krowa z oddechem","description":"W klęku podpartym płynnie przechodź między łagodnym zgięciem i wyprostem kręgosłupa. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Ruch bez forsowania.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Pozycja dziecka z sięganiem bocznym","description":"Cofnij biodra w kierunku pięt, ręce przed sobą i oddychaj spokojnie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Pomiń, jeśli zgięcie nasila objawy.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Przetaczanie miednicy - progresja","description":"Leżąc na plecach wykonuj małe ruchy przodo- i tyłopochylenia miednicy. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Bez mocnego dociskania pleców.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Most z pauzą 2-3 s","description":"Unieś biodra do linii tułowia i ud, utrzymując swobodny oddech. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie przeprostuj lędźwi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Bird dog z pauzą 3 s","description":"Z klęku podpartego wyprostuj przeciwną rękę i nogę bez rotacji miednicy. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zakres mniejszy przy bólu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat26","name":"Stabilizacja miednicy / okolica SI","goal":"Poprawa kontroli obciążania miednicy i bioder w podporze obunóż i jednonóż.","note":"Ból okolicy SI wymaga różnicowania z odcinkiem lędźwiowym, biodrem i innymi źródłami bólu.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Wojownik I - krótki wykrok - progresja","description":"Ustaw krótki wykrok i utrzymaj miednicę skierowaną do przodu, bez zapadania tułowia. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Obie stopy stabilne.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Most z pauzą 2-3 s","description":"Unieś biodra i wykonaj spokojne 2-3 oddechy, potem powoli opuść. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Bez bólu punktowego w okolicy SI.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Naprzemienne odrywanie stopy w leżeniu - progresja","description":"W leżeniu z ugiętymi kolanami unieś jedną stopę kilka centymetrów i odstaw bez kołysania miednicą. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Miednica spokojna.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Most z pauzą 2-3 s","description":"W górze mostu odrywaj na zmianę jedną stopę minimalnie od podłoża. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie opadaj biodrem.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Step-down z niskiego stopnia - progresja","description":"Stań na niskim stopniu i powoli opuszczaj drugą piętę do podłoża, kontrolując miednicę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Kolano w osi stopy.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat27","name":"Ból rzepkowo-udowy","goal":"Zwiększenie tolerancji kolana na zgięcie i obciążenie oraz poprawa siły biodra i uda.","note":"Ćwiczenia powinny być dozowane według 24-godzinnej reakcji objawów. Nie dąż do „ustawiania rzepki” na siłę.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Krzesło - dłuższe utrzymanie","description":"Cofnij biodra jak do siadania, ugnij kolana tylko do komfortowego zakresu i utrzymaj stopy stabilnie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Kolana nad stopami.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Wojownik II z dłuższym utrzymaniem","description":"Ugnij przednie kolano w małym zakresie, utrzymując oś biodro-kolano-stopa. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie zapadaj kolana do środka.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Wyprost kolana w siadzie - progresja","description":"Siedząc powoli wyprostuj kolano do tolerowanego zakresu i wróć. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch bez szarpania.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wstawanie z niższego krzesła","description":"Wstań i usiądź powoli, utrzymując kolana w osi stóp. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zacznij od wyższego siedziska.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Step-down - progresja","description":"Z niskiego stopnia opuszczaj wolną piętę ku podłożu i wracaj. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Miednica i kolano stabilne.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat28","name":"Ścięgno Achillesa / łydka","goal":"Stopniowe zwiększenie siły i tolerancji ścięgna Achillesa oraz mięśni łydki.","note":"Nagły trzask, utrata odepchnięcia lub dodatni test Thompsona wymagają pilnej diagnostyki ruptury.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - łagodnie - progresja","description":"Unieś biodra, kolana mogą być ugięte, a pięty wysoko. Stopniowo wydłużaj łydki bez ostrego bólu. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Bez sprężynowania.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Wykrok z tylną piętą na ziemi - progresja","description":"Stań w wykroku i delikatnie przenieś ciężar do przodu, utrzymując tylną piętę na podłożu. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Rozciąganie łagodne.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Wspięcia z pauzą w górze","description":"Przy podparciu unieś obie pięty i powoli opuść. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch spokojny.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Wspięcia z pauzą w górze","description":"Unieś pięty obunóż, przenieś nieco więcej ciężaru na jedną stronę podczas opuszczania. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Bez gwałtownego spadania pięty.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia z pauzą w górze","description":"Przy lekkim podparciu wykonuj wspięcia na jednej nodze. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zakres i tempo dostosuj do reakcji następnego dnia.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat29","name":"Ból pięty / rozcięgno podeszwowe","goal":"Poprawa tolerancji rozcięgna podeszwowego i łydki na obciążenie oraz kontrola łuku stopy.","note":"Przy bólu pięty z drętwieniem, znacznym obrzękiem lub urazem różnicuj inne przyczyny.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół z ugiętymi kolanami - progresja","description":"Utrzymaj biodra wysoko, pięty uniesione i stopniowo prostuj kolana bez wywoływania ostrego bólu pięty. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie wymuszaj pięt na ziemi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Góra z aktywnym łukiem - progresja","description":"Stań boso i utrzymaj trójnóg stopy, delikatnie unosząc łuk bez podwijania palców. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Palce rozluźnione.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Rozciąganie palucha w siadzie - progresja","description":"Załóż nogę na nogę i delikatnie odciągnij paluch ku górze, czując napięcie pod stopą. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Bez ostrego bólu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Krótka stopa w staniu","description":"Aktywuj łuk stopy bez zginania palców i utrzymaj kilka sekund. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nacisk pod piętą i podstawami I/V śródstopia.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia z pauzą w górze","description":"Umieść zrolowany ręcznik pod palcami i wykonuj powolne wspięcia na palce. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Zacznij obunóż.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat30","name":"Równowaga i stabilizacja","goal":"Poprawa kontroli postawy, reakcji równoważnych i pewności w podporze jednonóż.","note":"Zapewnij stabilne podparcie w zasięgu ręki. Przy częstych upadkach potrzebna jest pełna ocena ryzyka upadku.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra - Tadasana - progresja","description":"Stań boso lub w stabilnym obuwiu, ciężar rozłóż równo na stopach i utrzymuj wzrok na stałym punkcie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Oddychaj swobodnie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Drzewo z podparciem - progresja","description":"Stań przy ścianie, oprzyj stopę nogi wolnej o kostkę lub łydkę i utrzymaj pozycję. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie stawiaj stopy bezpośrednio na kolanie.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Przenoszenie ciężaru + zatrzymanie","description":"Stań szerzej i powoli przenoś ciężar z jednej nogi na drugą bez unoszenia stóp. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Miednica nad stopą podporową.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Stanie tandem - progresja","description":"Ustaw jedną stopę przed drugą jak na linie i utrzymaj równowagę. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Podparcie ręką dostępne.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż z sięganiem - progresja","description":"Stań na jednej nodze i wykonuj drugą stopą lekkie sięgnięcia w przód, bok i tył. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch wolny i kontrolowany.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat31","name":"Chód / przenoszenie ciężaru / wysoki marsz","goal":"Poprawa inicjacji kroku, obciążania kończyn i kontroli stopy podczas chodu.","note":"Przy chorobach neurologicznych dobierz objętość do zmęczenia, spastyczności i bezpieczeństwa. Nowy nagły deficyt wymaga diagnostyki.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra z przenoszeniem ciężaru - progresja","description":"Stań stabilnie i powoli przesuwaj ciężar przód-tył oraz bok-bok w małym zakresie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie odrywaj stóp.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Wojownik II z dłuższym utrzymaniem","description":"Stań szeroko przy blacie, ugnij jedną nogę i utrzymaj stabilne obciążenie obu stóp. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Podparcie ręką dozwolone.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Marsz w miejscu bez stałego podparcia","description":"Trzymając się blatu unoś naprzemiennie kolana do wygodnej wysokości. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Tułów możliwie pionowo.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Krok w przód i powrót - progresja","description":"Z pozycji stojącej wykonaj krok w przód, przenieś ciężar na przednią nogę i wróć. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Pełny kontakt stopy z podłożem.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Chód po linii z zatrzymaniem - progresja","description":"Idź powoli po wyznaczonej linii, co kilka kroków zatrzymaj się i ustabilizuj. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Asekuracja według potrzeb.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat32","name":"Stopa po unieruchomieniu / po gipsie","goal":"Odzyskanie ruchomości stawu skokowego, kontroli stopy, siły łydki i pewnego obciążania po zakończeniu unieruchomienia.","note":"Zakres obciążania musi być zgodny z zaleceniem lekarza prowadzącego. Narastający obrzęk, zaczerwienienie lub ból łydki wymagają oceny.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - odciążony - progresja","description":"Z podporu unieś biodra, pozostaw kolana ugięte i przenoś delikatnie ciężar między stopami. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Bez forsowania pięty.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"JOGA 2","title":"Góra z równym obciążeniem - progresja","description":"Stań przy podparciu i stopniowo wyrównuj ciężar na obu stopach. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"30-45 s x 2-3","tip":"Nie unikaj stopy, ale też nie przekraczaj zaleceń obciążania.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 1 - łatwy","title":"Alfabet stopą - progresja","description":"Siedząc wykonuj stopą małe ruchy jak przy pisaniu liter alfabetu. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Ruch z kostki, nie całej nogi.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 2 - średni","title":"Kolano do ściany z większym zakresem","description":"Przy pięcie na podłożu przesuwaj kolano w stronę ściany i wracaj. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Bez ostrego bólu.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż przy podparciu - progresja","description":"Przenieś ciężar na leczoną nogę i utrzymaj równowagę przy ścianie lub blacie. W tej fazie zwiększ zakres tylko wtedy, gdy technika pozostaje dobra i następnego dnia nie ma pogorszenia.","dose":"10-15 powt. x 2-3 serie","tip":"Nie progresuj, jeśli obrzęk wyraźnie narasta.  Jeśli objawy utrzymują się dłużej po ćwiczeniu, wróć do etapu 1."}]},{"id":"cat33","name":"Wzmocnienie pośladków","goal":"Zwiększenie czasu napięcia i kontroli pośladków podczas wyprostu i odwodzenia biodra.","note":"Przechodź dalej tylko, jeśli po etapie 1 nie ma wyraźnego pogorszenia następnego dnia.","source":"supplement_user_requested","exercises":[{"kind":"JOGA 1","title":"Most z dłuższym utrzymaniem","description":"Unieś miednicę do komfortowej wysokości i utrzymaj pozycję, cały czas oddychając oraz utrzymując równy nacisk obu stóp.","dose":"30-45 s x 2","tip":"Nie pozwalaj miednicy opadać na jedną stronę."},{"kind":"JOGA 2","title":"Wojownik II","description":"Stań szeroko, ugnij przednie kolano i utrzymaj miednicę stabilnie. Tylna noga pozostaje aktywna, tułów pionowo.","dose":"20-30 s/stronę x 2-3","tip":"Kolano przedniej nogi nad stopą, bez zapadania do środka."},{"kind":"POZIOM 1 - łatwy","title":"Most z 3-sekundowym zatrzymaniem","description":"Unieś biodra, zatrzymaj na 3 sekundy i powoli opuść.","dose":"10-12 x 2-3 serie","tip":"Utrzymuj napięcie pośladków, nie lędźwi."},{"kind":"POZIOM 2 - średni","title":"Odwodzenie nogi bokiem z pauzą","description":"Unieś wyprostowaną nogę w bok, zatrzymaj na 2-3 sekundy i powoli opuść.","dose":"10-15/stronę x 2-3","tip":"Miednica nie cofa się."},{"kind":"POZIOM 3 - trudniejszy","title":"Wstawanie z krzesła z hip hinge","description":"Usiądź na brzegu krzesła. Cofnij biodra, pochyl tułów z długim kręgosłupem i wstań przez wyprost bioder. Powoli usiądź.","dose":"8-12 x 2-3","tip":"Nacisk na całe stopy, na górze dopnij pośladki bez przeprostu pleców."}]}]},{"meta":{"id":"week4","label":"+4. tydzień","short":"+4 tydzień","desc":"Etap funkcjonalny - mniej podparcia, większa kontrola i tolerancja obciążenia."},"categories":[{"id":"cat01","name":"Rwa kulszowa","goal":"Łagodne utrzymanie ruchu, poprawa tolerancji obciążenia i ślizgu struktur nerwowych bez nasilania objawów w nodze.","note":"W rwie nie ma jednego dobrego kierunku ruchu dla wszystkich. Wybieraj ćwiczenia, po których ból/drętwienie nie schodzi dalej do stopy. Pilna konsultacja: drętwienie okolicy krocza, zaburzenia oddawania moczu/stolca, szybko narastające osłabienie nogi lub objawy obustronne.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Sfinks -> niska kobra, jeśli tolerowana","description":"Połóż się na brzuchu, oprzyj przedramiona pod barkami i unieś klatkę bez zaciskania pośladków. Biodra zostają na podłożu. Oddychaj spokojnie. Wykonuj tylko wtedy, gdy objawy w nodze nie nasilają się ani nie schodzą niżej. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Ruch ma być komfortowy; może być odczuwalny w plecach, ale nie powinien zwiększać promieniowania.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Pozycja dziecka -> klęk podparty","description":"Usiądź pośladkami w kierunku pięt, kolana ustaw szerzej i wyciągnij ręce do przodu. Nie wciskaj się na siłę w zgięcie. Jeśli zgięcie nasila promieniowanie, pomiń tę pozycję. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Wybieraj tylko kierunek, po którym noga czuje się tak samo lub lepiej.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Ślizg nerwu w pozycji funkcjonalnej","description":"Połóż się na plecach. Zegnij biodro i kolano do wygodnej pozycji, podtrzymując udo rękami. Powoli prostuj kolano i jednocześnie kieruj palce stopy do siebie; wracając, zegnij kolano i rozluźnij stopę. To ma być płynny ślizg, nie mocne rozciąganie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Bez długiego przytrzymania i bez wywoływania narastającego mrowienia.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Most z marszem naprzemiennym","description":"Leżenie na plecach, kolana ugięte, stopy na szerokość bioder. Lekko napnij brzuch i unieś miednicę do linii barki-biodrakolana. Opuść powoli. Nie wyginaj mocno odcinka lędźwiowego. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ciężar rozłóż równo na obu stopach.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Bird dog kolano-łokieć","description":"Klęk podparty. Utrzymaj spokojny tułów i wyprostuj jednocześnie jedną nogę oraz przeciwną rękę. Wróć bez kołysania miednicą i zmień stronę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zakres kończyny mniejszy, jeśli pojawia się ból promieniujący.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat02","name":"Przodopochylenie miednicy","goal":"Nauka ustawienia miednicy bliżej pozycji neutralnej, poprawa kontroli mięśni brzucha i pośladków oraz tolerancji wyprostu biodra.","note":"Samo przodopochylenie nie jest chorobą. Ćwiczymy wtedy, gdy to ustawienie wiąże się z bólem, przeciążeniem lub słabą kontrolą ruchu.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Niski wykrok z podwinięciem miednicy - wariant funkcjonalny","description":"Z klęku wysuń jedną stopę do przodu. Delikatnie podwiń miednicę „ogon pod siebie”, napnij pośladek nogi zakrocznej i przesuń tułów minimalnie do przodu. Nie rób przeprostu lędźwi. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Rozciąganie powinno być z przodu biodra nogi zakrocznej.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Pozycja dziecka -> klęk podparty","description":"Usiądź w kierunku pięt i wydłuż plecy, wyciągając ręce przed siebie. Oddychaj do dolnych żeber i rozluźnij odcinek lędźwiowy. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie dociskaj pośladków na siłę do pięt.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Tyłopochylenie miednicy w leżeniu - wariant funkcjonalny","description":"Leżenie na plecach, kolana ugięte. Na wydechu delikatnie zbliż dolne żebra do miednicy i spłaszcz lędźwie do podłoża. Wróć do neutralnej pozycji bez odrywania stóp. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch ma pochodzić z miednicy, nie z mocnego napinania szyi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Most z marszem naprzemiennym","description":"Najpierw delikatnie ustaw miednicę neutralnie lub lekko podwiń, potem unieś biodra. Utrzymaj żebra „nad miednicą”, bez wypychania brzucha w górę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Poczuj pośladki, nie tylko lędźwie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Wykrok w tył z kontrolą tułowia - wariant funkcjonalny","description":"Stań prosto, zrób krok w tył i zejdź w dół. Utrzymuj żebra nad miednicą, brzuch lekko aktywny i pośladek nogi podporowej napięty. Wróć do stania. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie pozwalaj, aby miednica uciekała w duży przeprost lędźwiowy.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat03","name":"Tyłopochylenie miednicy","goal":"Poprawa tolerancji lekkiego wyprostu, nauka swobodnego przodopochylenia miednicy i lepszego zgięcia w biodrach zamiast „podwijania” całych pleców.","note":"Tyłopochylenie samo w sobie bywa wariantem postawy. Ćwiczenia mają poprawiać kontrolę ruchu, a nie wymuszać jedną stałą pozycję.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Sfinks -> niska kobra, jeśli tolerowana","description":"Połóż się na brzuchu i oprzyj na przedramionach. Unieś mostek, pozostawiając biodra i brzuch rozluźnione. Nie zaciskaj odcinka lędźwiowego. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Oddychaj spokojnie; zmniejsz zakres przy bólu lędźwi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Krowa w klęku podpartym - wariant funkcjonalny","description":"Z klęku podpartego delikatnie unieś kość ogonową i mostek, tworząc łagodny łuk. Nie zapadaj się w barkach. Następnie wróć do neutralnej pozycji. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Ruch wykonuj segmentalnie i bez bólu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Przodopochylenie miednicy w siadzie - wariant funkcjonalny","description":"Usiądź na brzegu krzesła. Bez poruszania klatką piersiową przetocz miednicę do przodu tak, aby poczuć ciężar bardziej na przedniej części guzów kulszowych. Wróć do środka. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Mały, precyzyjny ruch jest lepszy niż duże wyginanie pleców.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Hip hinge przy ścianie - wariant funkcjonalny","description":"Stań 20-30 cm przed ścianą tyłem do niej. Cofnij biodra, jakbyś chciał dotknąć pośladkami ściany, utrzymując długi kręgosłup. Wróć przez wyprost bioder. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Kolana lekko ugięte, ciężar na całej stopie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Skłon rumuński bez obciążenia - wariant funkcjonalny","description":"Stań prosto. Cofnij biodra i pochyl tułów z prostym, wydłużonym kręgosłupem, aż poczujesz tył ud. Wróć, napinając pośladki. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie podwijaj miednicy w dolnej fazie i nie zaokrąglaj lędźwi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat04","name":"Koślawość kolan","goal":"Poprawa kontroli osi biodro-kolano-stopa podczas przysiadu, wstawania i podporu jednonóż.","note":"U dzieci i dorosłych część koślawości może wynikać z budowy anatomicznej. Ćwiczenia poprawiają kontrolę funkcjonalną, ale nie „prostują kości”.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Wojownik II z płynnym przejściem przód-tył","description":"Stań szeroko. Ugnij przednie kolano nad stopą, pilnując aby kierowało się w stronę 2.-3. palca. Tylna noga wyprostowana, miednica stabilna. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Kolano nie zapada się do środka.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Krzesło z wolnym wstawaniem i siadaniem","description":"Stań na szerokość bioder, cofnij biodra jak do siadania i ugnij kolana. Utrzymuj stopy w trzech punktach podparcia i kolana nad stopami. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie ściskaj kolan na siłę; utrzymuj naturalną oś.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Odwodzenie nogi bokiem w leżeniu - wariant funkcjonalny","description":"Połóż się na boku, dolna noga może być ugięta. Górną nogę wyprostuj i unieś lekko w bok, z palcami skierowanymi do przodu. Powoli opuść. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie obracaj miednicy do tyłu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wstawanie z asymetrycznym ustawieniem stóp","description":"Usiądź na brzegu krzesła, stopy na szerokość bioder. Wstań, utrzymując kolana w osi stóp, potem powoli usiądź. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Możesz zacząć od wyższego krzesła.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad jednonóż do krzesła - wariant funkcjonalny","description":"Stań przed wysokim krzesłem na jednej nodze. Cofnij biodro i dotknij pośladkiem siedziska, następnie wstań. Kolano utrzymuj nad 2.-3. palcem stopy. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zacznij od bardzo wysokiego podparcia i małego zakresu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat05","name":"Płaskostopie","goal":"Aktywacja mięśni krótkich stopy, poprawa kontroli łuku podłużnego i równowagi bez „zaciskania” palców.","note":"Ćwiczenia mogą poprawiać funkcję stopy, ale nie każda płaska stopa wymaga korekcji. Szczególnie u dzieci ocena zależy od wieku, elastyczności i objawów.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Góra - Tadasana z „trójnogiem” stopy - wariant funkcjonalny","description":"Stań boso. Dociśnij trzy punkty: piętę, podstawę palucha i podstawę małego palca. Palce rozluźnione. Delikatnie unieś łuk stopy bez podwijania palców. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Ciężar równomiernie na całej stopie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Pies z głową w dół - wariant funkcjonalny","description":"Z podporu unieś biodra w górę i cofnij je. Pięty mogą zostać uniesione. Wydłużaj tył nóg i łydki bez bólu w stopie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie wymuszaj kontaktu pięt z podłożem.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Krótka stopa w podporze jednonóż","description":"Siedząc lub stojąc, utrzymaj piętę i głowy I oraz V kości śródstopia na podłożu. Delikatnie „skróć” stopę, przyciągając przodostopie w stronę pięty bez zginania palców. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Palce mają pozostać długie i rozluźnione.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wspięcia jednonóż / większe obciążenie jednej nogi","description":"Stań przy ścianie. Utrzymaj trójnóg stopy i unieś pięty. Powoli zejdź w dół, nie pozwalając kostkom zapadać się do środka. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nacisk pozostaje także pod podstawą palucha.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż z krótką stopą - wariant funkcjonalny","description":"Stań na jednej nodze i utrzymaj aktywny łuk bez chwytania podłoża palcami. Gdy jest łatwo, wykonuj powolne ruchy drugą nogą w przód, bok i tył. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Kolano ustawione nad stopą, miednica stabilna.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat06","name":"Wzmocnienie mięśni core","goal":"Poprawa kontroli tułowia podczas ruchu kończyn, bez wstrzymywania oddechu i bez nadmiernego usztywnienia.","note":"„Core” to nie tylko mięśnie brzucha. W ćwiczeniach współpracują przepona, mięśnie brzucha, grzbietu, dna miednicy i obręczy biodrowej.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Deska z naprzemiennym ruchem kończyny","description":"Oprzyj dłonie lub przedramiona pod barkami. Utrzymaj linię głowa-tułów-miednica. Zacznij od wersji na kolanach, potem przejdź na stopy. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Oddychaj, nie zapadaj lędźwi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Łódka - łatwa wersja - wariant funkcjonalny","description":"Usiądź, ugnij kolana i odchyl tułów lekko do tyłu. Unieś jedną, a potem obie stopy, utrzymując długi kręgosłup. Ręce mogą trzymać uda. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Zmniejsz zakres, jeśli czujesz lędźwie bardziej niż brzuch.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Napięcie brzucha + ślizg pięty - wariant funkcjonalny","description":"Leżenie na plecach, kolana ugięte. Delikatnie napnij brzuch jak przed kaszlnięciem i wysuwaj jedną piętę po podłożu, nie zmieniając ustawienia miednicy. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Oddychaj swobodnie przez cały ruch.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Dead bug - wariant funkcjonalny","description":"Leżenie na plecach, biodra i kolana około 90°. Utrzymując stabilny tułów, opuszczaj jedną piętę w stronę podłogi i wracaj. Trudniej: dodaj przeciwną rękę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Plecy nie muszą być mocno dociśnięte - ważna jest kontrola bez bólu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Deska z naprzemiennym ruchem kończyny","description":"Pozycja wysokiej deski. Oderwij jedną dłoń i dotknij przeciwnego barku, nie kołysząc miednicą. Zmień stronę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ustaw stopy szerzej, jeśli trudno utrzymać stabilność.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat07","name":"Poprawa ruchomości całego kręgosłupa","goal":"Łagodny ruch odcinka szyjnego, piersiowego i lędźwiowego w kilku kierunkach, bez forsowania końcowych zakresów.","note":"Przy osteoporozie, świeżym urazie, zawrotach głowy po ruchu szyi lub objawach neurologicznych zakres powinien ustalić fizjoterapeuta.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Kot-krowa + przejście do neutralnej stabilizacji","description":"W klęku podpartym na wydechu zaokrąglij plecy i opuść głowę, a na wdechu delikatnie unieś mostek i kość ogonową. Ruch prowadź płynnie od miednicy po szyję. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie dociskaj szyi do końcowego zakresu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Sfinks -> niska kobra, jeśli tolerowana","description":"Z pozycji dziecka przejdź płynnie do leżenia na brzuchu i podeprzyj się na przedramionach w sfinksie. Następnie wróć. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Ruch spokojny, bez ostrego bólu i bez szarpania.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie książki z sięganiem ramienia","description":"Leżenie na boku, biodra i kolana ugięte, ręce wyciągnięte przed sobą. Otwórz górną rękę do tyłu, prowadząc za nią klatkę piersiową. Kolana pozostają razem. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Głowa może podążać za dłonią, jeśli nie wywołuje zawrotów.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wyprost piersiowy na krześle - wariant funkcjonalny","description":"Usiądź, oprzyj górną część pleców o oparcie. Dłonie za głową. Delikatnie odchyl klatkę piersiową nad oparciem, bez dużego przeprostu lędźwi. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch ma być głównie w piersiowym odcinku kręgosłupa.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Skłon + wyprost segmentalny w staniu - wariant funkcjonalny","description":"Z pozycji stojącej powoli opuszczaj brodę i zaokrąglaj kręgosłup od góry, schodząc tylko do wygodnego zakresu. Wróć powoli, ustawiając kręgi „jeden po drugim”. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie wykonuj przy osteoporozie bez wcześniejszej konsultacji.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat08","name":"Ból głowy","goal":"Zmniejszenie napięcia szyi i obręczy barkowej przy bólach napięciowych lub szyjnopochodnych oraz poprawa kontroli odcinka szyjnego.","note":"Te ćwiczenia nie są przeznaczone do nagłego, bardzo silnego bólu głowy ani bólu z niedowładem/drętwieniem twarzy lub kończyn, zaburzeniami mowy, widzenia, równowagi, gorączką ze sztywnością karku albo po urazie głowy.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pozycja dziecka -> klęk podparty","description":"Usiądź w kierunku pięt, oprzyj czoło na dłoniach lub poduszce i pozwól barkom opaść. Oddychaj spokojnie, wydłużając wydech. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Szyja ma być całkowicie rozluźniona.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Nogi na ścianie - Viparita Karani - wariant funkcjonalny","description":"Połóż się na plecach blisko ściany i oprzyj na niej nogi. Podeprzyj głowę cienką poduszką, jeśli tego potrzebujesz. Rozluźnij szczękę i barki. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Pomiń, jeśli pozycja zwiększa ból głowy lub ciśnienie w głowie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody + mała rotacja","description":"Siedząc lub leżąc, przesuń głowę poziomo do tyłu, jakbyś robił delikatny „podwójny podbródek”. Nie pochylaj głowy w dół. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch ma być mały i bez bólu promieniującego.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Łopatki w dół i lekko do tyłu - wariant funkcjonalny","description":"Usiądź prosto. Delikatnie ustaw łopatki w dół i do środka, bez wypinania klatki i bez unoszenia barków. Utrzymaj, rozluźnij. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie ściskaj łopatek maksymalnie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrolowana rotacja szyi - wariant funkcjonalny","description":"Usiądź prosto. Powoli obróć głowę w prawo do komfortowego zakresu, wróć do środka i powtórz w lewo. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Przerwij przy zawrotach, zaburzeniach widzenia lub wyraźnym nasileniu bólu głowy.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat09","name":"Ból karku","goal":"Utrzymanie ruchomości szyi, aktywacja głębokich mięśni szyi i poprawa pracy łopatek.","note":"Przy bólu po urazie, nasilającej się słabości ręki, niezgrabności dłoni, zaburzeniach chodu lub nowych zaburzeniach zwieraczy potrzebna jest pilna ocena lekarska.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Szczeniak - Uttana Shishosana - wariant funkcjonalny","description":"Z klęku podpartego cofnij biodra lekko w stronę pięt, a dłonie wysuń daleko do przodu. Klatkę kieruj w dół, ale szyję utrzymuj długą i swobodną. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie wciskaj głowy w podłoże.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Orzeł - same ramiona - wariant funkcjonalny","description":"Siedząc lub stojąc, skrzyżuj ramiona przed sobą i połącz przedramiona tak, jak pozwala zakres. Unieś łokcie lekko, oddychając w górną część pleców. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Barki pozostają z dala od uszu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody + mała rotacja","description":"Przesuń głowę prosto do tyłu, utrzymując wzrok na wprost. Utrzymaj krótko i wróć. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie unoś ani nie opuszczaj brody.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Izometria szyi - wariant funkcjonalny","description":"Połóż dłoń na czole i delikatnie napieraj głową na dłoń bez ruchu. Powtórz z dłonią z boku głowy po obu stronach. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Siła umiarkowana, bez zaciskania zębów.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Anioł przy ścianie - wariant funkcjonalny","description":"Oprzyj plecy o ścianę, broda lekko cofnięta. Przesuwaj ramiona po ścianie w górę i w dół w wygodnym zakresie, utrzymując łopatki pod kontrolą. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie wypychaj żeber do przodu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat10","name":"Drętwienie palców u dłoni","goal":"Łagodny ruch szyi, łopatki i nerwów kończyny górnej po wcześniejszej ocenie przyczyny objawów.","note":"Drętwienie palców może pochodzić z szyi, nadgarstka, łokcia lub innych przyczyn. Zestaw należy dobrać do rozpoznania. Pilna ocena, jeśli narasta osłabienie/chwyt, pojawia się niezgrabność obu rąk, zaburzenia chodu lub nagłe objawy neurologiczne.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Góra z rozluźnieniem barków - wariant funkcjonalny","description":"Stań prosto, dłonie skieruj do przodu, barki opuść i wydłuż szyję. Zrób 5-6 spokojnych oddechów, nie zaciskając palców. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Dłonie i szczęka pozostają rozluźnione.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Anjali Mudra - dłonie przed klatką - wariant funkcjonalny","description":"Złącz dłonie przed mostkiem bez mocnego dociskania. Ustaw nadgarstki neutralnie lub tylko lekko zgięte. Oddychaj spokojnie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Jeśli drętwienie się nasila, zmniejsz zgięcie nadgarstka lub pomiń.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody + mała rotacja","description":"Usiądź prosto. Lekko cofnij brodę, a łopatkę po stronie objawów ustaw swobodnie w dół. Nie ciągnij barku na siłę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Objawy w dłoni nie powinny narastać.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu w pozycji funkcjonalnej","description":"Ramię przy boku, łokieć zgięty. Powoli prostuj łokieć, jednocześnie odchylając nadgarstek i palce tylko do lekkiego napięcia, potem wróć. Stosuj szczególnie, gdy objawy obejmują kciuk, palec wskazujący i środkowy - po ocenie fizjoterapeuty. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"To ma być ślizg, nie mocne rozciąganie. Nie przytrzymuj końcowej pozycji.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Ślizg po ścianie + odklejenie dłoni","description":"Stań twarzą do ściany, przedramiona oprzyj o nią. Powoli przesuwaj ręce w górę, pozwalając łopatkom obracać się w górę, potem wróć. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Przerwij, jeśli drętwienie wyraźnie narasta lub utrzymuje się po ćwiczeniu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat11","name":"Drętwienie pośladków","goal":"Poprawa ruchu lędźwi i bioder oraz tolerancji pozycji siedzącej, jeśli przyczyna ma charakter mechaniczny i poważne przyczyny neurologiczne zostały wykluczone.","note":"Drętwienie obu pośladków lub okolicy krocza, zwłaszcza z zaburzeniami oddawania moczu/stolca, jest objawem alarmowym - nie ćwiczyć, tylko pilnie zgłosić się do pomocy medycznej.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Gołąb na plecach - „4” - wariant funkcjonalny","description":"Leżąc na plecach, połóż kostkę jednej nogi na przeciwległym udzie. Przyciągnij udo do siebie tylko do łagodnego rozciągania pośladka. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie dociskaj kolana na siłę.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Kot-krowa + przejście do neutralnej stabilizacji","description":"W klęku podpartym naprzemiennie zaokrąglaj i delikatnie wyginaj kręgosłup, poruszając miednicą. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Wybierz zakres, który nie zwiększa drętwienia.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Przetaczanie miednicy w leżeniu - wariant funkcjonalny","description":"Leżenie na plecach, kolana ugięte. Naprzemiennie delikatnie spłaszczaj lędźwie i wracaj do lekkiego łuku. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch ma być mały i płynny.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu w pozycji funkcjonalnej","description":"Leżenie na plecach. Unieś udo, podtrzymując je rękami. Prostuj i zginaj kolano w małym zakresie, synchronizując ruch stopy tak, aby nie utrzymywać napięcia. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Bez nasilania drętwienia po ćwiczeniu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Most z marszem naprzemiennym","description":"Unieś miednicę z leżenia na plecach, utrzymując ciężar na obu stopach i spokojny oddech. Powoli wróć. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Jeśli objawy stają się bardziej rozlane lub schodzą niżej do nogi - przerwij.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat12","name":"Drętwienie ud","goal":"Poprawa ruchomości biodra i odcinka lędźwiowego oraz zmniejszenie drażnienia tkanek w okolicy pachwiny/uda, gdy objawy są ocenione jako mechaniczne.","note":"Drętwienie bocznej części uda może mieć inne źródło niż drętwienie przedniej lub tylnej części. Przy narastającej słabości nogi, zaburzeniu chodu lub objawach obustronnych wymagana jest ocena neurologiczna.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Niski wykrok - wariant funkcjonalny","description":"Jedna noga z przodu, drugie kolano na podłożu. Delikatnie podwiń miednicę i przesuń ją do przodu, czując przód biodra nogi zakrocznej. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie rób przeprostu lędźwi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Sfinks -> niska kobra, jeśli tolerowana","description":"Leżenie na brzuchu, podpór na przedramionach. Unieś klatkę do komfortowego wyprostu. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Wykonuj tylko, jeśli nie zwiększa drętwienia w udzie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Kołysanie miednicą w leżeniu - wariant funkcjonalny","description":"Leżenie na plecach, kolana ugięte. Powoli przechodź między lekkim spłaszczeniem i lekkim łukiem lędźwi. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Bez forsowania końcowego zakresu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Rozciąganie zginaczy biodra w półklęku - wariant funkcjonalny","description":"Z półklęku podwiń miednicę i napnij pośladek nogi z tyłu. Przesuń ciało lekko do przodu. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie dociskaj do bólu lub mrowienia.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Wykrok w tył - wariant funkcjonalny","description":"Z pozycji stojącej cofnij jedną nogę i obniż ciało. Wróć do stania, aktywnie pracując pośladkiem nogi podporowej. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Utrzymuj stabilną miednicę i kolano nad stopą.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat13","name":"Drętwienie łydek","goal":"Łagodny ruch nerwowo-mięśniowy kończyny dolnej, poprawa pracy stawu skokowego i łydki po wcześniejszej ocenie źródła drętwienia.","note":"Nagłe drętwienie z wyraźnym osłabieniem stopy, opadaniem stopy, obustronnymi objawami lub zaburzeniami zwieraczy wymaga pilnej oceny. Obrzęk, zaczerwienienie i ból łydki wymagają wykluczenia problemu naczyniowego.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół z ugiętymi kolanami - wariant funkcjonalny","description":"Z podporu unieś biodra. Kolana pozostaw lekko ugięte i naprzemiennie kieruj pięty w dół, bez mocnego ciągnięcia łydki. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie trzymaj rozciągnięcia, jeśli wywołuje mrowienie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Skłon do jednej nogi w siadzie - łagodny - wariant funkcjonalny","description":"Usiądź z jedną nogą wyprostowaną, drugą ugiętą. Pochyl się z bioder tylko do lekkiego napięcia tyłu nogi. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Przy drętwieniu nie pogłębiaj rozciągania nerwu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Pompowanie stopy - wariant funkcjonalny","description":"Siedząc lub leżąc, naprzemiennie kieruj palce stopy do siebie i od siebie w pełnym, komfortowym zakresie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch płynny, bez bolesnego skurczu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu w pozycji funkcjonalnej","description":"Usiądź prosto. Prostuj kolano i jednocześnie unieś głowę; wracając zginaj kolano i lekko opuszczaj brodę. Ruch wykonuj płynnie, bez przytrzymania. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zakres ma nie zwiększać mrowienia po serii.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia jednonóż / większe obciążenie jednej nogi","description":"Stań przy ścianie. Unieś piętę jednej nogi, powoli opuść. Utrzymuj stopę w osi i nie skręcaj kostki. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Jeśli pojawia się narastająca słabość, zakończ i skonsultuj objaw.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat14","name":"Poprawa ruchomości stawów skokowych","goal":"Poprawa zgięcia grzbietowego, ruchomości łydki i kontroli stopy potrzebnej do chodu, przysiadu i schodów.","note":"Po świeżym skręceniu, złamaniu lub operacji zakres obciążania powinien wynikać z zaleceń prowadzącego lekarza/fizjoterapeuty.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - naprzemienne pięty - wariant funkcjonalny","description":"Ustaw się w psie z głową w dół. Naprzemiennie uginaj jedno kolano i kieruj przeciwną piętę w stronę podłoża. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Pięta nie musi dotykać podłogi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Krzesło z wolnym wstawaniem i siadaniem","description":"Z pozycji stojącej cofnij biodra i ugnij kolana, utrzymując pięty na podłożu. Kolana przesuwają się nad stopami w komfortowym zakresie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie zapadaj łuków stóp do środka.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Kolano do ściany w wykroku funkcjonalnym","description":"Stań przodem do ściany, stopa płasko. Prowadź kolano do ściany nad 2.-3. palcem bez odrywania pięty. Jeśli łatwo - odsuń stopę od ściany. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Kolano nie zapada się do środka.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wspięcia jednonóż / większe obciążenie jednej nogi","description":"Stań na obu stopach przy ścianie. Unieś pięty wysoko, zatrzymaj 1 s i opuszczaj przez 3 s. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch symetryczny, ciężar na podstawie palucha i małego palca.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad głęboki z podparciem - wariant funkcjonalny","description":"Trzymając się stabilnego oparcia, zejdź do przysiadu tak głęboko, jak pozwalają biodra i kostki. Pięty pozostają na podłożu. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie wymuszaj głębokości kosztem bólu kolan lub stóp.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat15","name":"Poprawa ruchomości bioder","goal":"Ruch biodra w zgięciu, wyproście, rotacji i odwiedzeniu przy możliwie stabilnej miednicy.","note":"Przy nasilającym się bólu pachwiny, blokowaniu stawu lub bólu nocnym zakres powinien być oceniony indywidualnie.","source":"original17","exercises":[{"kind":"JOGA 1","title":"90/90 - wariant funkcjonalny","description":"Usiądź z jedną nogą z przodu i drugą z boku, obie ugięte około 90°. Usiądź wysoko, a następnie delikatnie pochyl tułów nad przednią nogą. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie dociskaj kolan na siłę do podłogi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Niski wykrok - wariant funkcjonalny","description":"Z półklęku podwiń lekko miednicę i przesuń ją do przodu, czując przód biodra nogi zakrocznej. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie wyginaj lędźwi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Kolano do klatki + krążenie biodrem - wariant funkcjonalny","description":"Leżąc na plecach, przyciągnij jedno kolano do komfortowego zakresu i wykonuj małe kółka udem w stawie biodrowym. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Miednica pozostaje możliwie spokojna.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wycieraczki w leżeniu - wariant funkcjonalny","description":"Leżenie na plecach, kolana ugięte, stopy szerzej. Opuszczaj oba kolana w jedną stronę, wróć i powtórz w drugą. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zakres bez bólu w pachwinie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad kozacki - wariant funkcjonalny","description":"Stań szeroko. Przenieś ciężar na jedną nogę, uginając ją, a drugą pozostaw bardziej wyprostowaną. Wróć przez środek i zmień stronę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zacznij płytko i trzymaj się oparcia, jeśli potrzeba.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat16","name":"Rozluźnienie przepony","goal":"Zmniejszenie nadmiernego udziału górnej klatki i mięśni pomocniczych oddechu, poprawa spokojnego oddechu dolnożebrowego.","note":"Ćwiczenia oddechowe wykonuj bez forsowania. Jeśli pojawi się zawrót głowy, przerwij, odpocznij i wróć do naturalnego oddechu.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pozycja krokodyla - Makarasana - wariant funkcjonalny","description":"Połóż się na brzuchu, czoło oprzyj na złożonych dłoniach. Pozwól, by przy wdechu dolne żebra i brzuch delikatnie naciskały na podłoże. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Barki, szyja i szczęka rozluźnione.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Pozycja dziecka -> klęk podparty","description":"Usiądź w kierunku pięt, oprzyj czoło. Wdychaj powietrze „do dolnych żeber i pleców”, a na wydechu rozluźniaj brzuch i barki. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie staraj się nabierać maksymalnie dużo powietrza.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Oddech 360° w leżeniu - wariant funkcjonalny","description":"Połóż dłonie na dolnych żebrach. Wdech nosem: żebra delikatnie rozszerzają się na boki i do tyłu. Wydech: swobodnie opadają. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Górna część klatki porusza się niewiele.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wydłużony wydech - wariant funkcjonalny","description":"Wdech nosem przez około 3-4 s, następnie spokojny wydech przez lekko złączone usta przez 5-7 s. Nie opróżniaj płuc na siłę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Jeśli kręci się w głowie - skróć oddech i zrób przerwę.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Oddech boczno-żebrowy w leżeniu na boku - wariant funkcjonalny","description":"Połóż się na boku, górną dłoń połóż na dolnych żebrach. Kieruj wdech pod dłoń, a przy wydechu pozwól żebrom opaść. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Oddychaj cicho i bez unoszenia barku.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat17","name":"Wzmocnienie przepony","goal":"Poprawa kontroli i wytrzymałości oddechowej bez sprzętu poprzez pracę przepony w coraz trudniejszych pozycjach i podczas lekkiego wysiłku.","note":"Bez urządzenia z oporem są to głównie ćwiczenia kontroli i wytrzymałości oddechowej, nie precyzyjny trening siły mięśni wdechowych. Przy chorobach płuc/serca dawkę należy ustalić indywidualnie.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Most z marszem naprzemiennym","description":"Leżenie na plecach. Na wydechu unieś miednicę do mostu. Utrzymując pozycję, wykonaj 2-3 spokojne oddechy do dolnych żeber i opuść biodra. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie wstrzymuj oddechu w górze.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Krzesło z wolnym wstawaniem i siadaniem","description":"Stań, cofnij biodra jak do siadania i ugnij kolana. Utrzymuj pozycję, wykonując spokojne wdechy nosem i dłuższe wydechy. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Przerwij przy duszności nieproporcjonalnej do wysiłku lub zawrotach głowy.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Oddech przeponowy w leżeniu - wariant funkcjonalny","description":"Połóż jedną dłoń na mostku, drugą na brzuchu/dolnych żebrach. Wdech kieruj w dół i na boki, wydech swobodny. Z czasem wydłużaj serię bez zwiększania objętości pojedynczego oddechu. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch ręki na górnej klatce ma być niewielki.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Oddech przeponowy w klęku podpartym - wariant funkcjonalny","description":"Klęk podparty, kręgosłup neutralny. Wdech nosem do boków i tyłu dolnych żeber; wydech spokojny, z lekkim napięciem brzucha. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie zapadaj się w barkach i nie unoś ich przy wdechu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Marsz z pauzą na jednej nodze","description":"Maszeruj spokojnie, unosząc kolana do komfortowej wysokości. Utrzymuj rytm: 2-3 kroki na wdech i 3-4 kroki na wydech, bez zadyszki. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Tempo pozwala mówić krótkim zdaniem; przerwij przy bólu w klatce lub znacznej duszności.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat18","name":"Ból barku / stożek rotatorów","goal":"Poprawa tolerancji unoszenia ramienia i stopniowe wzmacnianie stożka rotatorów oraz łopatki.","note":"Ćwiczenia dobieraj do drażliwości. Po świeżym urazie z nagłą utratą siły lub niemożnością uniesienia ramienia wymagana jest dalsza diagnostyka.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Szczeniak przy ścianie - wariant funkcjonalny","description":"Stań przed ścianą, oprzyj dłonie i cofnij biodra, wydłużając boki tułowia oraz obręcz barkową bez wciskania barku w ból. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Zakres ma być swobodny; nie unoś barków do uszu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Orzeł - ramiona - wariant funkcjonalny","description":"Skrzyżuj ramiona przed klatką, unieś łokcie do wygodnej wysokości i spokojnie oddychaj w górną część pleców. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Bez mrowienia i ostrego bólu barku.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Izometria rotacji zewnętrznej przy ścianie - wariant funkcjonalny","description":"Stań bokiem do ściany, łokieć przy tułowiu i delikatnie naciskaj grzbietem dłoni na ścianę bez ruchu barku. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Siła umiarkowana; ból nie powinien narastać po serii.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Ślizg po ścianie + odklejenie dłoni","description":"Przesuwaj przedramiona w górę po ścianie, utrzymując szyję rozluźnioną i łopatkę płynnie obracającą się ku górze. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie wypychaj żeber do przodu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Scaption bez obciążenia - wariant funkcjonalny","description":"Unieś ramiona w płaszczyźnie około 30° przed bokiem ciała do tolerowanego zakresu, powoli opuść. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch kontrolowany, bez szarpania i unoszenia barków.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat19","name":"Kontrola łopatki / dyskineza","goal":"Poprawa kontroli łopatki podczas unoszenia i obciążania kończyny górnej.","note":"Celem nie jest sztywne „ściąganie łopatek”, lecz płynna współpraca łopatki z ramieniem i klatką piersiową.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Koci grzbiet z aktywnym odepchnięciem dłoni - wariant funkcjonalny","description":"W klęku podpartym zaokrąglij łagodnie odcinek piersiowy, aktywnie odpychając podłoże i pozwalając łopatkom rozsunąć się. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie zapadaj się między barkami.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Deska z naprzemiennym ruchem kończyny","description":"W podporze na dłoniach utrzymaj łokcie proste i delikatnie „odepchnij podłogę”, nie zaokrąglając przesadnie pleców. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Zacznij z kolan, jeśli pełny podpor jest za trudny.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Serratus punch w leżeniu - wariant funkcjonalny","description":"Leżąc na plecach unieś rękę do sufitu, a następnie bez zginania łokcia sięgnij dłonią wyżej, unosząc łopatkę od podłoża. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch mały i płynny.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wall slide + lekkie odklejenie dłoni","description":"Przesuwaj przedramiona po ścianie do góry, utrzymując lekkie odepchnięcie i spokojną szyję. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie dociskaj łopatek do kręgosłupa.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Y przy ścianie - wariant funkcjonalny","description":"Stań twarzą do ściany, unieś ręce po skosie do litery Y i delikatnie odklej dłonie bez unoszenia barków. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zakres mniejszy, jeśli pojawia się kompensacja szyją.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat20","name":"Sztywność barku / zamrożony bark","goal":"Stopniowa poprawa tolerancji ruchu i funkcji bez forsowania bolesnego końcowego zakresu.","note":"W wysokiej drażliwości preferuj częste, krótkie i łagodne ruchy. Agresywne rozciąganie może nasilić objawy.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pozycja dziecka -> klęk podparty","description":"Oprzyj dłonie na krześle lub łóżku i cofnij biodra, pozwalając barkom wejść w wygodne zgięcie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie wciskaj barku w ból.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Orzeł - łagodny wariant ramion - wariant funkcjonalny","description":"Skrzyżuj ramiona przed klatką i unieś łokcie tylko do komfortowego poziomu. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Pomiń przy ostrym bólu przedniej części barku.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Wahadło Codmana - wariant funkcjonalny","description":"Podeprzyj się zdrową ręką, rozluźnij bolesną kończynę i wykonuj małe koła oraz ruchy przód-tył. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ramię ma być rozluźnione.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Ślizg ręki po stole - wariant funkcjonalny","description":"Siedząc przesuń dłoń po stole do przodu, pozwalając tułowi lekko pochylić się za ręką. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie unoś barku do ucha.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspinanie palcami po ścianie - wariant funkcjonalny","description":"Wejdź palcami po ścianie do tolerowanego poziomu i powoli wróć. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie utrzymuj długo bolesnego końca zakresu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat21","name":"Łokieć tenisisty","goal":"Zmniejszenie bólu podczas chwytu i stopniowe zwiększenie tolerancji prostowników nadgarstka na obciążenie.","note":"Zmniejsz przeciążenie chwytu, ale unikaj całkowitego unieruchamiania. Nasilający się deficyt wyprostu palców wymaga diagnostyki neurologicznej.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Dłonie odwrócone w klęku - łagodnie - wariant funkcjonalny","description":"W klęku podpartym ustaw dłonie palcami w stronę kolan tylko w tolerowanym zakresie i delikatnie cofnij biodra. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Bez drętwienia i ostrego bólu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Orzeł - ramiona - wariant funkcjonalny","description":"Skrzyżuj ramiona i wydłuż tył barków, utrzymując przedramiona rozluźnione. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie zaciskaj dłoni.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Izometria wyprostu nadgarstka - wariant funkcjonalny","description":"Przedramię oprzyj na stole, drugą dłonią staw opór grzbietowi ręki bez ruchu w nadgarstku. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Siła umiarkowana.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Powolny wyprost nadgarstka bez ciężaru - wariant funkcjonalny","description":"Przedramię na stole, dłoń poza krawędzią. Unieś i bardzo powoli opuść nadgarstek. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch ma być płynny.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrolowany chwyt ręcznika - wariant funkcjonalny","description":"Ściskaj zrolowany ręcznik do umiarkowanej siły i powoli rozluźniaj. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie prowokuj bólu utrzymującego się po ćwiczeniu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat22","name":"Łokieć golfisty","goal":"Stopniowe zwiększenie tolerancji zginaczy i pronatorów przedramienia na chwyt i obciążenie.","note":"Przy drętwieniu IV-V palca lub wyraźnym osłabieniu dłoni różnicuj problem z nerwem łokciowym.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Dłonie grzbietami przed klatką - wariant funkcjonalny","description":"Połącz grzbiety dłoni przed klatką piersiową i delikatnie opuszczaj łokcie, utrzymując komfort w nadgarstkach. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Bez mrowienia.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Szczeniak z dłońmi na podwyższeniu - wariant funkcjonalny","description":"Oprzyj dłonie na krześle, cofnij biodra i wydłuż ramiona oraz boki tułowia. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Łokcie miękkie, bez przeprostu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Izometria zgięcia nadgarstka - wariant funkcjonalny","description":"Drugą dłonią staw opór stronie dłoniowej ręki bez wykonywania ruchu. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Siła umiarkowana.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Powolne zgięcie nadgarstka bez ciężaru - wariant funkcjonalny","description":"Przedramię na stole, dłoń poza krawędzią. Zegnij i powoli wróć do neutralnej pozycji. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie ściskaj palców.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Pronacja i supinacja kontrolowana - wariant funkcjonalny","description":"Z łokciem przy tułowiu obracaj dłoń ku górze i ku dołowi w pełnym komfortowym zakresie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch wolny, łokieć stabilny.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat23","name":"Cieśń nadgarstka / nerw pośrodkowy","goal":"Zmniejszenie prowokacji objawów i utrzymanie łagodnego ślizgu nerwu pośrodkowego oraz ruchomości nadgarstka.","note":"Nasilające się drętwienie, zanik kłębu kciuka lub utrwalona słabość wymagają dalszej diagnostyki.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra z otwartymi dłońmi - wariant funkcjonalny","description":"Stań swobodnie, ramiona wzdłuż tułowia, palce dłoni wydłużone i rozluźnione. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie utrzymuj nadgarstków w skrajnym zgięciu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Anjali Mudra - dłonie przed klatką - wariant funkcjonalny","description":"Złącz dłonie przed klatką na wysokości, która nie wywołuje parestezji. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Zmniejsz kąt w nadgarstku przy mrowieniu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie i zamykanie dłoni - wariant funkcjonalny","description":"Naprzemiennie szeroko rozprostuj palce i lekko zamknij dłoń bez silnego ścisku. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch bez bólu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu w pozycji funkcjonalnej","description":"Wykonuj stopniowe ustawienia dłoni, łokcia i barku jako płynny ślizg bez utrzymywania napięcia. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie rozciągaj nerwu na końcu ruchu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrola nadgarstka przy lekkim podporze - wariant funkcjonalny","description":"Oprzyj dłonie o ścianę i delikatnie przenoś ciężar przód-tył. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Przerwij przy nasileniu drętwienia.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat24","name":"Sztywność odcinka piersiowego / garb posturalny","goal":"Poprawa wyprostu i rotacji odcinka piersiowego oraz pracy łopatek.","note":"Przy osteoporozie unikaj forsownego zgięcia i rotacji; ćwiczenia dobierz indywidualnie.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Szczeniak - Uttana Shishosana - wariant funkcjonalny","description":"Z klęku podpartego przesuń dłonie do przodu, pozostawiając biodra nad kolanami i wydłużając klatkę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie zapadaj szyi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Kobra niska - wariant funkcjonalny","description":"Leżąc na brzuchu oprzyj przedramiona lub dłonie i unieś mostek, utrzymując ruch głównie w piersiowym odcinku. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Bez kompresji lędźwi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie książki z sięganiem ramienia","description":"Leżąc na boku obracaj górne ramię i klatkę do tyłu, kolana pozostają razem. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch płynny.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wyprost piersiowy na oparciu - wariant funkcjonalny","description":"Usiądź, oprzyj górny odcinek pleców o krawędź oparcia i wykonaj łagodny wyprost. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie odchylaj głowy gwałtownie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Wall angel - wariant funkcjonalny","description":"Plecy przy ścianie, przesuwaj ramiona w górę i w dół bez wypychania żeber. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zakres dostosuj do barków.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat25","name":"Ból lędźwiowy nieswoisty","goal":"Utrzymanie ruchu, poprawa kontroli tułowia i stopniowy powrót do obciążeń dnia codziennego.","note":"Nie ma jednego kierunku ruchu dobrego dla wszystkich. Dobieraj ćwiczenia do reakcji objawów i funkcji.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Kot-krowa + przejście do neutralnej stabilizacji","description":"W klęku podpartym płynnie przechodź między łagodnym zgięciem i wyprostem kręgosłupa. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Ruch bez forsowania.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Pozycja dziecka -> klęk podparty","description":"Cofnij biodra w kierunku pięt, ręce przed sobą i oddychaj spokojnie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Pomiń, jeśli zgięcie nasila objawy.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Przetaczanie miednicy - wariant funkcjonalny","description":"Leżąc na plecach wykonuj małe ruchy przodo- i tyłopochylenia miednicy. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Bez mocnego dociskania pleców.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Most z marszem naprzemiennym","description":"Unieś biodra do linii tułowia i ud, utrzymując swobodny oddech. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie przeprostuj lędźwi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Bird dog kolano-łokieć","description":"Z klęku podpartego wyprostuj przeciwną rękę i nogę bez rotacji miednicy. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zakres mniejszy przy bólu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat26","name":"Stabilizacja miednicy / okolica SI","goal":"Poprawa kontroli obciążania miednicy i bioder w podporze obunóż i jednonóż.","note":"Ból okolicy SI wymaga różnicowania z odcinkiem lędźwiowym, biodrem i innymi źródłami bólu.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Wojownik I - krótki wykrok - wariant funkcjonalny","description":"Ustaw krótki wykrok i utrzymaj miednicę skierowaną do przodu, bez zapadania tułowia. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Obie stopy stabilne.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Most z marszem naprzemiennym","description":"Unieś biodra i wykonaj spokojne 2-3 oddechy, potem powoli opuść. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Bez bólu punktowego w okolicy SI.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Naprzemienne odrywanie stopy w leżeniu - wariant funkcjonalny","description":"W leżeniu z ugiętymi kolanami unieś jedną stopę kilka centymetrów i odstaw bez kołysania miednicą. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Miednica spokojna.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Most z marszem naprzemiennym","description":"W górze mostu odrywaj na zmianę jedną stopę minimalnie od podłoża. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie opadaj biodrem.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Step-down z niskiego stopnia - wariant funkcjonalny","description":"Stań na niskim stopniu i powoli opuszczaj drugą piętę do podłoża, kontrolując miednicę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Kolano w osi stopy.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat27","name":"Ból rzepkowo-udowy","goal":"Zwiększenie tolerancji kolana na zgięcie i obciążenie oraz poprawa siły biodra i uda.","note":"Ćwiczenia powinny być dozowane według 24-godzinnej reakcji objawów. Nie dąż do „ustawiania rzepki” na siłę.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Krzesło z wolnym wstawaniem i siadaniem","description":"Cofnij biodra jak do siadania, ugnij kolana tylko do komfortowego zakresu i utrzymaj stopy stabilnie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Kolana nad stopami.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Wojownik II z płynnym przejściem przód-tył","description":"Ugnij przednie kolano w małym zakresie, utrzymując oś biodro-kolano-stopa. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie zapadaj kolana do środka.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Wyprost kolana w siadzie - wariant funkcjonalny","description":"Siedząc powoli wyprostuj kolano do tolerowanego zakresu i wróć. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch bez szarpania.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wstawanie z asymetrycznym ustawieniem stóp","description":"Wstań i usiądź powoli, utrzymując kolana w osi stóp. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zacznij od wyższego siedziska.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Step-down - wariant funkcjonalny","description":"Z niskiego stopnia opuszczaj wolną piętę ku podłożu i wracaj. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Miednica i kolano stabilne.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat28","name":"Ścięgno Achillesa / łydka","goal":"Stopniowe zwiększenie siły i tolerancji ścięgna Achillesa oraz mięśni łydki.","note":"Nagły trzask, utrata odepchnięcia lub dodatni test Thompsona wymagają pilnej diagnostyki ruptury.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - łagodnie - wariant funkcjonalny","description":"Unieś biodra, kolana mogą być ugięte, a pięty wysoko. Stopniowo wydłużaj łydki bez ostrego bólu. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Bez sprężynowania.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Wykrok z tylną piętą na ziemi - wariant funkcjonalny","description":"Stań w wykroku i delikatnie przenieś ciężar do przodu, utrzymując tylną piętę na podłożu. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Rozciąganie łagodne.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Wspięcia jednonóż / większe obciążenie jednej nogi","description":"Przy podparciu unieś obie pięty i powoli opuść. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch spokojny.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Wspięcia jednonóż / większe obciążenie jednej nogi","description":"Unieś pięty obunóż, przenieś nieco więcej ciężaru na jedną stronę podczas opuszczania. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Bez gwałtownego spadania pięty.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia jednonóż / większe obciążenie jednej nogi","description":"Przy lekkim podparciu wykonuj wspięcia na jednej nodze. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zakres i tempo dostosuj do reakcji następnego dnia.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat29","name":"Ból pięty / rozcięgno podeszwowe","goal":"Poprawa tolerancji rozcięgna podeszwowego i łydki na obciążenie oraz kontrola łuku stopy.","note":"Przy bólu pięty z drętwieniem, znacznym obrzękiem lub urazem różnicuj inne przyczyny.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół z ugiętymi kolanami - wariant funkcjonalny","description":"Utrzymaj biodra wysoko, pięty uniesione i stopniowo prostuj kolana bez wywoływania ostrego bólu pięty. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie wymuszaj pięt na ziemi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Góra z aktywnym łukiem - wariant funkcjonalny","description":"Stań boso i utrzymaj trójnóg stopy, delikatnie unosząc łuk bez podwijania palców. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Palce rozluźnione.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Rozciąganie palucha w siadzie - wariant funkcjonalny","description":"Załóż nogę na nogę i delikatnie odciągnij paluch ku górze, czując napięcie pod stopą. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Bez ostrego bólu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Krótka stopa w podporze jednonóż","description":"Aktywuj łuk stopy bez zginania palców i utrzymaj kilka sekund. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nacisk pod piętą i podstawami I/V śródstopia.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia jednonóż / większe obciążenie jednej nogi","description":"Umieść zrolowany ręcznik pod palcami i wykonuj powolne wspięcia na palce. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Zacznij obunóż.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat30","name":"Równowaga i stabilizacja","goal":"Poprawa kontroli postawy, reakcji równoważnych i pewności w podporze jednonóż.","note":"Zapewnij stabilne podparcie w zasięgu ręki. Przy częstych upadkach potrzebna jest pełna ocena ryzyka upadku.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra - Tadasana - wariant funkcjonalny","description":"Stań boso lub w stabilnym obuwiu, ciężar rozłóż równo na stopach i utrzymuj wzrok na stałym punkcie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Oddychaj swobodnie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Drzewo z podparciem - wariant funkcjonalny","description":"Stań przy ścianie, oprzyj stopę nogi wolnej o kostkę lub łydkę i utrzymaj pozycję. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie stawiaj stopy bezpośrednio na kolanie.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Przenoszenie ciężaru z krokiem","description":"Stań szerzej i powoli przenoś ciężar z jednej nogi na drugą bez unoszenia stóp. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Miednica nad stopą podporową.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Stanie tandem - wariant funkcjonalny","description":"Ustaw jedną stopę przed drugą jak na linie i utrzymaj równowagę. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Podparcie ręką dostępne.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż z sięganiem - wariant funkcjonalny","description":"Stań na jednej nodze i wykonuj drugą stopą lekkie sięgnięcia w przód, bok i tył. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch wolny i kontrolowany.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat31","name":"Chód / przenoszenie ciężaru / wysoki marsz","goal":"Poprawa inicjacji kroku, obciążania kończyn i kontroli stopy podczas chodu.","note":"Przy chorobach neurologicznych dobierz objętość do zmęczenia, spastyczności i bezpieczeństwa. Nowy nagły deficyt wymaga diagnostyki.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra z przenoszeniem ciężaru - wariant funkcjonalny","description":"Stań stabilnie i powoli przesuwaj ciężar przód-tył oraz bok-bok w małym zakresie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie odrywaj stóp.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Wojownik II z płynnym przejściem przód-tył","description":"Stań szeroko przy blacie, ugnij jedną nogę i utrzymaj stabilne obciążenie obu stóp. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Podparcie ręką dozwolone.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Marsz z pauzą na jednej nodze","description":"Trzymając się blatu unoś naprzemiennie kolana do wygodnej wysokości. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Tułów możliwie pionowo.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Krok w przód i powrót - wariant funkcjonalny","description":"Z pozycji stojącej wykonaj krok w przód, przenieś ciężar na przednią nogę i wróć. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Pełny kontakt stopy z podłożem.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Chód po linii z zatrzymaniem - wariant funkcjonalny","description":"Idź powoli po wyznaczonej linii, co kilka kroków zatrzymaj się i ustabilizuj. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Asekuracja według potrzeb.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat32","name":"Stopa po unieruchomieniu / po gipsie","goal":"Odzyskanie ruchomości stawu skokowego, kontroli stopy, siły łydki i pewnego obciążania po zakończeniu unieruchomienia.","note":"Zakres obciążania musi być zgodny z zaleceniem lekarza prowadzącego. Narastający obrzęk, zaczerwienienie lub ból łydki wymagają oceny.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - odciążony - wariant funkcjonalny","description":"Z podporu unieś biodra, pozostaw kolana ugięte i przenoś delikatnie ciężar między stopami. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Bez forsowania pięty.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"JOGA 2","title":"Góra z równym obciążeniem - wariant funkcjonalny","description":"Stań przy podparciu i stopniowo wyrównuj ciężar na obu stopach. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"30-60 s x 2-3","tip":"Nie unikaj stopy, ale też nie przekraczaj zaleceń obciążania.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 1 - łatwy","title":"Alfabet stopą - wariant funkcjonalny","description":"Siedząc wykonuj stopą małe ruchy jak przy pisaniu liter alfabetu. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Ruch z kostki, nie całej nogi.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 2 - średni","title":"Kolano do ściany w wykroku funkcjonalnym","description":"Przy pięcie na podłożu przesuwaj kolano w stronę ściany i wracaj. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Bez ostrego bólu.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż przy podparciu - wariant funkcjonalny","description":"Przenieś ciężar na leczoną nogę i utrzymaj równowagę przy ścianie lub blacie. Wykonuj wolniej i z mniejszym podparciem lub większą kontrolą, ale bez utraty jakości ruchu.","dose":"8-15 powt. x 2-4 serie","tip":"Nie progresuj, jeśli obrzęk wyraźnie narasta.  Jakość ruchu jest ważniejsza niż zakres i liczba powtórzeń."}]},{"id":"cat33","name":"Wzmocnienie pośladków","goal":"Przeniesienie siły pośladków do podporu jednonóż, wykroku i kontroli miednicy.","note":"To etap funkcjonalny. Zmniejsz zakres, jeśli technika się pogarsza lub pojawia się ból stawu biodrowego/kolana.","source":"supplement_user_requested","exercises":[{"kind":"JOGA 1","title":"Wojownik III z podparciem","description":"Oprzyj dłonie o ścianę lub blat, przenieś ciężar na jedną nogę i pochyl tułów, unosząc drugą nogę w tył.","dose":"15-25 s/stronę x 2","tip":"Miednica skierowana do podłoża, noga podporowa stabilna."},{"kind":"JOGA 2","title":"Krzesło - większy zakres","description":"Cofnij biodra głębiej niż w etapie wcześniejszym, zachowując stabilne stopy i kolana w osi.","dose":"20-35 s x 2-3","tip":"Głębokość dobierz do kontroli i tolerancji."},{"kind":"POZIOM 1 - łatwy","title":"Most jednonóż - wersja podparta","description":"Unieś biodra w moście, jedną stopę odciąż lub unieś minimalnie. Utrzymaj miednicę poziomo.","dose":"6-10/stronę x 2","tip":"Jeśli miednica opada, wróć do mostu obunóż."},{"kind":"POZIOM 2 - średni","title":"Step-up na niski stopień","description":"Wejdź na niski stopień jedną nogą, wyprostuj biodro i kolano, potem zejdź powoli.","dose":"8-12/stronę x 2-3","tip":"Nie odbijaj się mocno nogą dolną."},{"kind":"POZIOM 3 - trudniejszy","title":"Wykrok w tył z kontrolą miednicy","description":"Zrób krok w tył i zejdź w dół w kontrolowanym zakresie. Wróć do stania przez pracę nogi przedniej.","dose":"6-10/stronę x 2-3","tip":"Miednica stabilna, kolano w osi stopy."}]}]},{"meta":{"id":"maint","label":"Podtrzymanie","short":"Podtrzymanie","desc":"Utrzymanie efektu - mniejsza częstotliwość, dobra jakość i funkcjonalne warianty."},"categories":[{"id":"cat01","name":"Rwa kulszowa","goal":"Łagodne utrzymanie ruchu, poprawa tolerancji obciążenia i ślizgu struktur nerwowych bez nasilania objawów w nodze.","note":"W rwie nie ma jednego dobrego kierunku ruchu dla wszystkich. Wybieraj ćwiczenia, po których ból/drętwienie nie schodzi dalej do stopy. Pilna konsultacja: drętwienie okolicy krocza, zaburzenia oddawania moczu/stolca, szybko narastające osłabienie nogi lub objawy obustronne.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Sfinks/kobra - płynna mobilizacja","description":"Połóż się na brzuchu, oprzyj przedramiona pod barkami i unieś klatkę bez zaciskania pośladków. Biodra zostają na podłożu. Oddychaj spokojnie. Wykonuj tylko wtedy, gdy objawy w nodze nie nasilają się ani nie schodzą niżej. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Ruch ma być komfortowy; może być odczuwalny w plecach, ale nie powinien zwiększać promieniowania.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Pozycja dziecka jako reset ruchowy","description":"Usiądź pośladkami w kierunku pięt, kolana ustaw szerzej i wyciągnij ręce do przodu. Nie wciskaj się na siłę w zgięcie. Jeśli zgięcie nasila promieniowanie, pomiń tę pozycję. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Wybieraj tylko kierunek, po którym noga czuje się tak samo lub lepiej.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Ślizg nerwu - dawka podtrzymująca","description":"Połóż się na plecach. Zegnij biodro i kolano do wygodnej pozycji, podtrzymując udo rękami. Powoli prostuj kolano i jednocześnie kieruj palce stopy do siebie; wracając, zegnij kolano i rozluźnij stopę. To ma być płynny ślizg, nie mocne rozciąganie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Bez długiego przytrzymania i bez wywoływania narastającego mrowienia.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Most - 2 serie kontrolne 2-3x/tydz.","description":"Leżenie na plecach, kolana ugięte, stopy na szerokość bioder. Lekko napnij brzuch i unieś miednicę do linii barki-biodrakolana. Opuść powoli. Nie wyginaj mocno odcinka lędźwiowego. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ciężar rozłóż równo na obu stopach.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Bird dog - seria jakościowa 2-3x/tydz.","description":"Klęk podparty. Utrzymaj spokojny tułów i wyprostuj jednocześnie jedną nogę oraz przeciwną rękę. Wróć bez kołysania miednicą i zmień stronę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zakres kończyny mniejszy, jeśli pojawia się ból promieniujący.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat02","name":"Przodopochylenie miednicy","goal":"Nauka ustawienia miednicy bliżej pozycji neutralnej, poprawa kontroli mięśni brzucha i pośladków oraz tolerancji wyprostu biodra.","note":"Samo przodopochylenie nie jest chorobą. Ćwiczymy wtedy, gdy to ustawienie wiąże się z bólem, przeciążeniem lub słabą kontrolą ruchu.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Niski wykrok z podwinięciem miednicy - wariant podtrzymujący","description":"Z klęku wysuń jedną stopę do przodu. Delikatnie podwiń miednicę „ogon pod siebie”, napnij pośladek nogi zakrocznej i przesuń tułów minimalnie do przodu. Nie rób przeprostu lędźwi. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Rozciąganie powinno być z przodu biodra nogi zakrocznej.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Pozycja dziecka jako reset ruchowy","description":"Usiądź w kierunku pięt i wydłuż plecy, wyciągając ręce przed siebie. Oddychaj do dolnych żeber i rozluźnij odcinek lędźwiowy. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie dociskaj pośladków na siłę do pięt.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Tyłopochylenie miednicy w leżeniu - wariant podtrzymujący","description":"Leżenie na plecach, kolana ugięte. Na wydechu delikatnie zbliż dolne żebra do miednicy i spłaszcz lędźwie do podłoża. Wróć do neutralnej pozycji bez odrywania stóp. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch ma pochodzić z miednicy, nie z mocnego napinania szyi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Most - 2 serie kontrolne 2-3x/tydz.","description":"Najpierw delikatnie ustaw miednicę neutralnie lub lekko podwiń, potem unieś biodra. Utrzymaj żebra „nad miednicą”, bez wypychania brzucha w górę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Poczuj pośladki, nie tylko lędźwie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Wykrok w tył z kontrolą tułowia - wariant podtrzymujący","description":"Stań prosto, zrób krok w tył i zejdź w dół. Utrzymuj żebra nad miednicą, brzuch lekko aktywny i pośladek nogi podporowej napięty. Wróć do stania. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie pozwalaj, aby miednica uciekała w duży przeprost lędźwiowy.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat03","name":"Tyłopochylenie miednicy","goal":"Poprawa tolerancji lekkiego wyprostu, nauka swobodnego przodopochylenia miednicy i lepszego zgięcia w biodrach zamiast „podwijania” całych pleców.","note":"Tyłopochylenie samo w sobie bywa wariantem postawy. Ćwiczenia mają poprawiać kontrolę ruchu, a nie wymuszać jedną stałą pozycję.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Sfinks/kobra - płynna mobilizacja","description":"Połóż się na brzuchu i oprzyj na przedramionach. Unieś mostek, pozostawiając biodra i brzuch rozluźnione. Nie zaciskaj odcinka lędźwiowego. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Oddychaj spokojnie; zmniejsz zakres przy bólu lędźwi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Krowa w klęku podpartym - wariant podtrzymujący","description":"Z klęku podpartego delikatnie unieś kość ogonową i mostek, tworząc łagodny łuk. Nie zapadaj się w barkach. Następnie wróć do neutralnej pozycji. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Ruch wykonuj segmentalnie i bez bólu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Przodopochylenie miednicy w siadzie - wariant podtrzymujący","description":"Usiądź na brzegu krzesła. Bez poruszania klatką piersiową przetocz miednicę do przodu tak, aby poczuć ciężar bardziej na przedniej części guzów kulszowych. Wróć do środka. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Mały, precyzyjny ruch jest lepszy niż duże wyginanie pleców.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Hip hinge przy ścianie - wariant podtrzymujący","description":"Stań 20-30 cm przed ścianą tyłem do niej. Cofnij biodra, jakbyś chciał dotknąć pośladkami ściany, utrzymując długi kręgosłup. Wróć przez wyprost bioder. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Kolana lekko ugięte, ciężar na całej stopie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Skłon rumuński bez obciążenia - wariant podtrzymujący","description":"Stań prosto. Cofnij biodra i pochyl tułów z prostym, wydłużonym kręgosłupem, aż poczujesz tył ud. Wróć, napinając pośladki. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie podwijaj miednicy w dolnej fazie i nie zaokrąglaj lędźwi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat04","name":"Koślawość kolan","goal":"Poprawa kontroli osi biodro-kolano-stopa podczas przysiadu, wstawania i podporu jednonóż.","note":"U dzieci i dorosłych część koślawości może wynikać z budowy anatomicznej. Ćwiczenia poprawiają kontrolę funkcjonalną, ale nie „prostują kości”.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Wojownik II podtrzymująco","description":"Stań szeroko. Ugnij przednie kolano nad stopą, pilnując aby kierowało się w stronę 2.-3. palca. Tylna noga wyprostowana, miednica stabilna. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Kolano nie zapada się do środka.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Krzesło podtrzymująco 2-3x/tydz.","description":"Stań na szerokość bioder, cofnij biodra jak do siadania i ugnij kolana. Utrzymuj stopy w trzech punktach podparcia i kolana nad stopami. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie ściskaj kolan na siłę; utrzymuj naturalną oś.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Odwodzenie nogi bokiem w leżeniu - wariant podtrzymujący","description":"Połóż się na boku, dolna noga może być ugięta. Górną nogę wyprostuj i unieś lekko w bok, z palcami skierowanymi do przodu. Powoli opuść. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie obracaj miednicy do tyłu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wstawanie - 2 serie 2-3x/tydz.","description":"Usiądź na brzegu krzesła, stopy na szerokość bioder. Wstań, utrzymując kolana w osi stóp, potem powoli usiądź. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Możesz zacząć od wyższego krzesła.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad jednonóż do krzesła - wariant podtrzymujący","description":"Stań przed wysokim krzesłem na jednej nodze. Cofnij biodro i dotknij pośladkiem siedziska, następnie wstań. Kolano utrzymuj nad 2.-3. palcem stopy. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zacznij od bardzo wysokiego podparcia i małego zakresu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat05","name":"Płaskostopie","goal":"Aktywacja mięśni krótkich stopy, poprawa kontroli łuku podłużnego i równowagi bez „zaciskania” palców.","note":"Ćwiczenia mogą poprawiać funkcję stopy, ale nie każda płaska stopa wymaga korekcji. Szczególnie u dzieci ocena zależy od wieku, elastyczności i objawów.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Góra - Tadasana z „trójnogiem” stopy - wariant podtrzymujący","description":"Stań boso. Dociśnij trzy punkty: piętę, podstawę palucha i podstawę małego palca. Palce rozluźnione. Delikatnie unieś łuk stopy bez podwijania palców. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Ciężar równomiernie na całej stopie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Pies z głową w dół - wariant podtrzymujący","description":"Z podporu unieś biodra w górę i cofnij je. Pięty mogą zostać uniesione. Wydłużaj tył nóg i łydki bez bólu w stopie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie wymuszaj kontaktu pięt z podłożem.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Krótka stopa podczas chodu i stania","description":"Siedząc lub stojąc, utrzymaj piętę i głowy I oraz V kości śródstopia na podłożu. Delikatnie „skróć” stopę, przyciągając przodostopie w stronę pięty bez zginania palców. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Palce mają pozostać długie i rozluźnione.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wspięcia podtrzymujące 2-3x/tydz.","description":"Stań przy ścianie. Utrzymaj trójnóg stopy i unieś pięty. Powoli zejdź w dół, nie pozwalając kostkom zapadać się do środka. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nacisk pozostaje także pod podstawą palucha.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż z krótką stopą - wariant podtrzymujący","description":"Stań na jednej nodze i utrzymaj aktywny łuk bez chwytania podłoża palcami. Gdy jest łatwo, wykonuj powolne ruchy drugą nogą w przód, bok i tył. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Kolano ustawione nad stopą, miednica stabilna.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat06","name":"Wzmocnienie mięśni core","goal":"Poprawa kontroli tułowia podczas ruchu kończyn, bez wstrzymywania oddechu i bez nadmiernego usztywnienia.","note":"„Core” to nie tylko mięśnie brzucha. W ćwiczeniach współpracują przepona, mięśnie brzucha, grzbietu, dna miednicy i obręczy biodrowej.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Deska podtrzymująco 2-3x/tydz.","description":"Oprzyj dłonie lub przedramiona pod barkami. Utrzymaj linię głowa-tułów-miednica. Zacznij od wersji na kolanach, potem przejdź na stopy. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Oddychaj, nie zapadaj lędźwi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Łódka - łatwa wersja - wariant podtrzymujący","description":"Usiądź, ugnij kolana i odchyl tułów lekko do tyłu. Unieś jedną, a potem obie stopy, utrzymując długi kręgosłup. Ręce mogą trzymać uda. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Zmniejsz zakres, jeśli czujesz lędźwie bardziej niż brzuch.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Napięcie brzucha + ślizg pięty - wariant podtrzymujący","description":"Leżenie na plecach, kolana ugięte. Delikatnie napnij brzuch jak przed kaszlnięciem i wysuwaj jedną piętę po podłożu, nie zmieniając ustawienia miednicy. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Oddychaj swobodnie przez cały ruch.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Dead bug - wariant podtrzymujący","description":"Leżenie na plecach, biodra i kolana około 90°. Utrzymując stabilny tułów, opuszczaj jedną piętę w stronę podłogi i wracaj. Trudniej: dodaj przeciwną rękę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Plecy nie muszą być mocno dociśnięte - ważna jest kontrola bez bólu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Deska podtrzymująco 2-3x/tydz.","description":"Pozycja wysokiej deski. Oderwij jedną dłoń i dotknij przeciwnego barku, nie kołysząc miednicą. Zmień stronę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ustaw stopy szerzej, jeśli trudno utrzymać stabilność.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat07","name":"Poprawa ruchomości całego kręgosłupa","goal":"Łagodny ruch odcinka szyjnego, piersiowego i lędźwiowego w kilku kierunkach, bez forsowania końcowych zakresów.","note":"Przy osteoporozie, świeżym urazie, zawrotach głowy po ruchu szyi lub objawach neurologicznych zakres powinien ustalić fizjoterapeuta.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Kot-krowa jako mobilizacja podtrzymująca","description":"W klęku podpartym na wydechu zaokrąglij plecy i opuść głowę, a na wdechu delikatnie unieś mostek i kość ogonową. Ruch prowadź płynnie od miednicy po szyję. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie dociskaj szyi do końcowego zakresu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Sfinks/kobra - płynna mobilizacja","description":"Z pozycji dziecka przejdź płynnie do leżenia na brzuchu i podeprzyj się na przedramionach w sfinksie. Następnie wróć. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Ruch spokojny, bez ostrego bólu i bez szarpania.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie książki 2-3x/tydz.","description":"Leżenie na boku, biodra i kolana ugięte, ręce wyciągnięte przed sobą. Otwórz górną rękę do tyłu, prowadząc za nią klatkę piersiową. Kolana pozostają razem. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Głowa może podążać za dłonią, jeśli nie wywołuje zawrotów.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wyprost piersiowy na krześle - wariant podtrzymujący","description":"Usiądź, oprzyj górną część pleców o oparcie. Dłonie za głową. Delikatnie odchyl klatkę piersiową nad oparciem, bez dużego przeprostu lędźwi. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch ma być głównie w piersiowym odcinku kręgosłupa.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Skłon + wyprost segmentalny w staniu - wariant podtrzymujący","description":"Z pozycji stojącej powoli opuszczaj brodę i zaokrąglaj kręgosłup od góry, schodząc tylko do wygodnego zakresu. Wróć powoli, ustawiając kręgi „jeden po drugim”. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie wykonuj przy osteoporozie bez wcześniejszej konsultacji.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat08","name":"Ból głowy","goal":"Zmniejszenie napięcia szyi i obręczy barkowej przy bólach napięciowych lub szyjnopochodnych oraz poprawa kontroli odcinka szyjnego.","note":"Te ćwiczenia nie są przeznaczone do nagłego, bardzo silnego bólu głowy ani bólu z niedowładem/drętwieniem twarzy lub kończyn, zaburzeniami mowy, widzenia, równowagi, gorączką ze sztywnością karku albo po urazie głowy.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pozycja dziecka jako reset ruchowy","description":"Usiądź w kierunku pięt, oprzyj czoło na dłoniach lub poduszce i pozwól barkom opaść. Oddychaj spokojnie, wydłużając wydech. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Szyja ma być całkowicie rozluźniona.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Nogi na ścianie - Viparita Karani - wariant podtrzymujący","description":"Połóż się na plecach blisko ściany i oprzyj na niej nogi. Podeprzyj głowę cienką poduszką, jeśli tego potrzebujesz. Rozluźnij szczękę i barki. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Pomiń, jeśli pozycja zwiększa ból głowy lub ciśnienie w głowie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody w przerwach od pracy","description":"Siedząc lub leżąc, przesuń głowę poziomo do tyłu, jakbyś robił delikatny „podwójny podbródek”. Nie pochylaj głowy w dół. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch ma być mały i bez bólu promieniującego.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Łopatki w dół i lekko do tyłu - wariant podtrzymujący","description":"Usiądź prosto. Delikatnie ustaw łopatki w dół i do środka, bez wypinania klatki i bez unoszenia barków. Utrzymaj, rozluźnij. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie ściskaj łopatek maksymalnie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrolowana rotacja szyi - wariant podtrzymujący","description":"Usiądź prosto. Powoli obróć głowę w prawo do komfortowego zakresu, wróć do środka i powtórz w lewo. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Przerwij przy zawrotach, zaburzeniach widzenia lub wyraźnym nasileniu bólu głowy.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat09","name":"Ból karku","goal":"Utrzymanie ruchomości szyi, aktywacja głębokich mięśni szyi i poprawa pracy łopatek.","note":"Przy bólu po urazie, nasilającej się słabości ręki, niezgrabności dłoni, zaburzeniach chodu lub nowych zaburzeniach zwieraczy potrzebna jest pilna ocena lekarska.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Szczeniak - Uttana Shishosana - wariant podtrzymujący","description":"Z klęku podpartego cofnij biodra lekko w stronę pięt, a dłonie wysuń daleko do przodu. Klatkę kieruj w dół, ale szyję utrzymuj długą i swobodną. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie wciskaj głowy w podłoże.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Orzeł - same ramiona - wariant podtrzymujący","description":"Siedząc lub stojąc, skrzyżuj ramiona przed sobą i połącz przedramiona tak, jak pozwala zakres. Unieś łokcie lekko, oddychając w górną część pleców. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Barki pozostają z dala od uszu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody w przerwach od pracy","description":"Przesuń głowę prosto do tyłu, utrzymując wzrok na wprost. Utrzymaj krótko i wróć. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie unoś ani nie opuszczaj brody.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Izometria szyi - wariant podtrzymujący","description":"Połóż dłoń na czole i delikatnie napieraj głową na dłoń bez ruchu. Powtórz z dłonią z boku głowy po obu stronach. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Siła umiarkowana, bez zaciskania zębów.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Anioł przy ścianie - wariant podtrzymujący","description":"Oprzyj plecy o ścianę, broda lekko cofnięta. Przesuwaj ramiona po ścianie w górę i w dół w wygodnym zakresie, utrzymując łopatki pod kontrolą. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie wypychaj żeber do przodu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat10","name":"Drętwienie palców u dłoni","goal":"Łagodny ruch szyi, łopatki i nerwów kończyny górnej po wcześniejszej ocenie przyczyny objawów.","note":"Drętwienie palców może pochodzić z szyi, nadgarstka, łokcia lub innych przyczyn. Zestaw należy dobrać do rozpoznania. Pilna ocena, jeśli narasta osłabienie/chwyt, pojawia się niezgrabność obu rąk, zaburzenia chodu lub nagłe objawy neurologiczne.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Góra z rozluźnieniem barków - wariant podtrzymujący","description":"Stań prosto, dłonie skieruj do przodu, barki opuść i wydłuż szyję. Zrób 5-6 spokojnych oddechów, nie zaciskając palców. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Dłonie i szczęka pozostają rozluźnione.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Anjali Mudra - dłonie przed klatką - wariant podtrzymujący","description":"Złącz dłonie przed mostkiem bez mocnego dociskania. Ustaw nadgarstki neutralnie lub tylko lekko zgięte. Oddychaj spokojnie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Jeśli drętwienie się nasila, zmniejsz zgięcie nadgarstka lub pomiń.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Cofnięcie brody w przerwach od pracy","description":"Usiądź prosto. Lekko cofnij brodę, a łopatkę po stronie objawów ustaw swobodnie w dół. Nie ciągnij barku na siłę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Objawy w dłoni nie powinny narastać.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu - dawka podtrzymująca","description":"Ramię przy boku, łokieć zgięty. Powoli prostuj łokieć, jednocześnie odchylając nadgarstek i palce tylko do lekkiego napięcia, potem wróć. Stosuj szczególnie, gdy objawy obejmują kciuk, palec wskazujący i środkowy - po ocenie fizjoterapeuty. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"To ma być ślizg, nie mocne rozciąganie. Nie przytrzymuj końcowej pozycji.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Ślizg po ścianie 2-3x/tydz.","description":"Stań twarzą do ściany, przedramiona oprzyj o nią. Powoli przesuwaj ręce w górę, pozwalając łopatkom obracać się w górę, potem wróć. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Przerwij, jeśli drętwienie wyraźnie narasta lub utrzymuje się po ćwiczeniu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat11","name":"Drętwienie pośladków","goal":"Poprawa ruchu lędźwi i bioder oraz tolerancji pozycji siedzącej, jeśli przyczyna ma charakter mechaniczny i poważne przyczyny neurologiczne zostały wykluczone.","note":"Drętwienie obu pośladków lub okolicy krocza, zwłaszcza z zaburzeniami oddawania moczu/stolca, jest objawem alarmowym - nie ćwiczyć, tylko pilnie zgłosić się do pomocy medycznej.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Gołąb na plecach - „4” - wariant podtrzymujący","description":"Leżąc na plecach, połóż kostkę jednej nogi na przeciwległym udzie. Przyciągnij udo do siebie tylko do łagodnego rozciągania pośladka. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie dociskaj kolana na siłę.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Kot-krowa jako mobilizacja podtrzymująca","description":"W klęku podpartym naprzemiennie zaokrąglaj i delikatnie wyginaj kręgosłup, poruszając miednicą. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Wybierz zakres, który nie zwiększa drętwienia.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Przetaczanie miednicy w leżeniu - wariant podtrzymujący","description":"Leżenie na plecach, kolana ugięte. Naprzemiennie delikatnie spłaszczaj lędźwie i wracaj do lekkiego łuku. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch ma być mały i płynny.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu - dawka podtrzymująca","description":"Leżenie na plecach. Unieś udo, podtrzymując je rękami. Prostuj i zginaj kolano w małym zakresie, synchronizując ruch stopy tak, aby nie utrzymywać napięcia. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Bez nasilania drętwienia po ćwiczeniu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Most - 2 serie kontrolne 2-3x/tydz.","description":"Unieś miednicę z leżenia na plecach, utrzymując ciężar na obu stopach i spokojny oddech. Powoli wróć. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Jeśli objawy stają się bardziej rozlane lub schodzą niżej do nogi - przerwij.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat12","name":"Drętwienie ud","goal":"Poprawa ruchomości biodra i odcinka lędźwiowego oraz zmniejszenie drażnienia tkanek w okolicy pachwiny/uda, gdy objawy są ocenione jako mechaniczne.","note":"Drętwienie bocznej części uda może mieć inne źródło niż drętwienie przedniej lub tylnej części. Przy narastającej słabości nogi, zaburzeniu chodu lub objawach obustronnych wymagana jest ocena neurologiczna.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Niski wykrok - wariant podtrzymujący","description":"Jedna noga z przodu, drugie kolano na podłożu. Delikatnie podwiń miednicę i przesuń ją do przodu, czując przód biodra nogi zakrocznej. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie rób przeprostu lędźwi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Sfinks/kobra - płynna mobilizacja","description":"Leżenie na brzuchu, podpór na przedramionach. Unieś klatkę do komfortowego wyprostu. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Wykonuj tylko, jeśli nie zwiększa drętwienia w udzie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Kołysanie miednicą w leżeniu - wariant podtrzymujący","description":"Leżenie na plecach, kolana ugięte. Powoli przechodź między lekkim spłaszczeniem i lekkim łukiem lędźwi. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Bez forsowania końcowego zakresu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Rozciąganie zginaczy biodra w półklęku - wariant podtrzymujący","description":"Z półklęku podwiń miednicę i napnij pośladek nogi z tyłu. Przesuń ciało lekko do przodu. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie dociskaj do bólu lub mrowienia.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Wykrok w tył - wariant podtrzymujący","description":"Z pozycji stojącej cofnij jedną nogę i obniż ciało. Wróć do stania, aktywnie pracując pośladkiem nogi podporowej. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Utrzymuj stabilną miednicę i kolano nad stopą.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat13","name":"Drętwienie łydek","goal":"Łagodny ruch nerwowo-mięśniowy kończyny dolnej, poprawa pracy stawu skokowego i łydki po wcześniejszej ocenie źródła drętwienia.","note":"Nagłe drętwienie z wyraźnym osłabieniem stopy, opadaniem stopy, obustronnymi objawami lub zaburzeniami zwieraczy wymaga pilnej oceny. Obrzęk, zaczerwienienie i ból łydki wymagają wykluczenia problemu naczyniowego.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół z ugiętymi kolanami - wariant podtrzymujący","description":"Z podporu unieś biodra. Kolana pozostaw lekko ugięte i naprzemiennie kieruj pięty w dół, bez mocnego ciągnięcia łydki. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie trzymaj rozciągnięcia, jeśli wywołuje mrowienie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Skłon do jednej nogi w siadzie - łagodny - wariant podtrzymujący","description":"Usiądź z jedną nogą wyprostowaną, drugą ugiętą. Pochyl się z bioder tylko do lekkiego napięcia tyłu nogi. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Przy drętwieniu nie pogłębiaj rozciągania nerwu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Pompowanie stopy - wariant podtrzymujący","description":"Siedząc lub leżąc, naprzemiennie kieruj palce stopy do siebie i od siebie w pełnym, komfortowym zakresie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch płynny, bez bolesnego skurczu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu - dawka podtrzymująca","description":"Usiądź prosto. Prostuj kolano i jednocześnie unieś głowę; wracając zginaj kolano i lekko opuszczaj brodę. Ruch wykonuj płynnie, bez przytrzymania. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zakres ma nie zwiększać mrowienia po serii.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia podtrzymujące 2-3x/tydz.","description":"Stań przy ścianie. Unieś piętę jednej nogi, powoli opuść. Utrzymuj stopę w osi i nie skręcaj kostki. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Jeśli pojawia się narastająca słabość, zakończ i skonsultuj objaw.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat14","name":"Poprawa ruchomości stawów skokowych","goal":"Poprawa zgięcia grzbietowego, ruchomości łydki i kontroli stopy potrzebnej do chodu, przysiadu i schodów.","note":"Po świeżym skręceniu, złamaniu lub operacji zakres obciążania powinien wynikać z zaleceń prowadzącego lekarza/fizjoterapeuty.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - naprzemienne pięty - wariant podtrzymujący","description":"Ustaw się w psie z głową w dół. Naprzemiennie uginaj jedno kolano i kieruj przeciwną piętę w stronę podłoża. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Pięta nie musi dotykać podłogi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Krzesło podtrzymująco 2-3x/tydz.","description":"Z pozycji stojącej cofnij biodra i ugnij kolana, utrzymując pięty na podłożu. Kolana przesuwają się nad stopami w komfortowym zakresie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie zapadaj łuków stóp do środka.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Kolano do ściany kontrolnie przed treningiem","description":"Stań przodem do ściany, stopa płasko. Prowadź kolano do ściany nad 2.-3. palcem bez odrywania pięty. Jeśli łatwo - odsuń stopę od ściany. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Kolano nie zapada się do środka.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wspięcia podtrzymujące 2-3x/tydz.","description":"Stań na obu stopach przy ścianie. Unieś pięty wysoko, zatrzymaj 1 s i opuszczaj przez 3 s. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch symetryczny, ciężar na podstawie palucha i małego palca.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad głęboki z podparciem - wariant podtrzymujący","description":"Trzymając się stabilnego oparcia, zejdź do przysiadu tak głęboko, jak pozwalają biodra i kostki. Pięty pozostają na podłożu. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie wymuszaj głębokości kosztem bólu kolan lub stóp.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat15","name":"Poprawa ruchomości bioder","goal":"Ruch biodra w zgięciu, wyproście, rotacji i odwiedzeniu przy możliwie stabilnej miednicy.","note":"Przy nasilającym się bólu pachwiny, blokowaniu stawu lub bólu nocnym zakres powinien być oceniony indywidualnie.","source":"original17","exercises":[{"kind":"JOGA 1","title":"90/90 - wariant podtrzymujący","description":"Usiądź z jedną nogą z przodu i drugą z boku, obie ugięte około 90°. Usiądź wysoko, a następnie delikatnie pochyl tułów nad przednią nogą. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie dociskaj kolan na siłę do podłogi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Niski wykrok - wariant podtrzymujący","description":"Z półklęku podwiń lekko miednicę i przesuń ją do przodu, czując przód biodra nogi zakrocznej. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie wyginaj lędźwi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Kolano do klatki + krążenie biodrem - wariant podtrzymujący","description":"Leżąc na plecach, przyciągnij jedno kolano do komfortowego zakresu i wykonuj małe kółka udem w stawie biodrowym. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Miednica pozostaje możliwie spokojna.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wycieraczki w leżeniu - wariant podtrzymujący","description":"Leżenie na plecach, kolana ugięte, stopy szerzej. Opuszczaj oba kolana w jedną stronę, wróć i powtórz w drugą. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zakres bez bólu w pachwinie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Przysiad kozacki - wariant podtrzymujący","description":"Stań szeroko. Przenieś ciężar na jedną nogę, uginając ją, a drugą pozostaw bardziej wyprostowaną. Wróć przez środek i zmień stronę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zacznij płytko i trzymaj się oparcia, jeśli potrzeba.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat16","name":"Rozluźnienie przepony","goal":"Zmniejszenie nadmiernego udziału górnej klatki i mięśni pomocniczych oddechu, poprawa spokojnego oddechu dolnożebrowego.","note":"Ćwiczenia oddechowe wykonuj bez forsowania. Jeśli pojawi się zawrót głowy, przerwij, odpocznij i wróć do naturalnego oddechu.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Pozycja krokodyla - Makarasana - wariant podtrzymujący","description":"Połóż się na brzuchu, czoło oprzyj na złożonych dłoniach. Pozwól, by przy wdechu dolne żebra i brzuch delikatnie naciskały na podłoże. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Barki, szyja i szczęka rozluźnione.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Pozycja dziecka jako reset ruchowy","description":"Usiądź w kierunku pięt, oprzyj czoło. Wdychaj powietrze „do dolnych żeber i pleców”, a na wydechu rozluźniaj brzuch i barki. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie staraj się nabierać maksymalnie dużo powietrza.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Oddech 360° w leżeniu - wariant podtrzymujący","description":"Połóż dłonie na dolnych żebrach. Wdech nosem: żebra delikatnie rozszerzają się na boki i do tyłu. Wydech: swobodnie opadają. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Górna część klatki porusza się niewiele.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wydłużony wydech - wariant podtrzymujący","description":"Wdech nosem przez około 3-4 s, następnie spokojny wydech przez lekko złączone usta przez 5-7 s. Nie opróżniaj płuc na siłę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Jeśli kręci się w głowie - skróć oddech i zrób przerwę.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Oddech boczno-żebrowy w leżeniu na boku - wariant podtrzymujący","description":"Połóż się na boku, górną dłoń połóż na dolnych żebrach. Kieruj wdech pod dłoń, a przy wydechu pozwól żebrom opaść. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Oddychaj cicho i bez unoszenia barku.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat17","name":"Wzmocnienie przepony","goal":"Poprawa kontroli i wytrzymałości oddechowej bez sprzętu poprzez pracę przepony w coraz trudniejszych pozycjach i podczas lekkiego wysiłku.","note":"Bez urządzenia z oporem są to głównie ćwiczenia kontroli i wytrzymałości oddechowej, nie precyzyjny trening siły mięśni wdechowych. Przy chorobach płuc/serca dawkę należy ustalić indywidualnie.","source":"original17","exercises":[{"kind":"JOGA 1","title":"Most - 2 serie kontrolne 2-3x/tydz.","description":"Leżenie na plecach. Na wydechu unieś miednicę do mostu. Utrzymując pozycję, wykonaj 2-3 spokojne oddechy do dolnych żeber i opuść biodra. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie wstrzymuj oddechu w górze.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Krzesło podtrzymująco 2-3x/tydz.","description":"Stań, cofnij biodra jak do siadania i ugnij kolana. Utrzymuj pozycję, wykonując spokojne wdechy nosem i dłuższe wydechy. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Przerwij przy duszności nieproporcjonalnej do wysiłku lub zawrotach głowy.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Oddech przeponowy w leżeniu - wariant podtrzymujący","description":"Połóż jedną dłoń na mostku, drugą na brzuchu/dolnych żebrach. Wdech kieruj w dół i na boki, wydech swobodny. Z czasem wydłużaj serię bez zwiększania objętości pojedynczego oddechu. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch ręki na górnej klatce ma być niewielki.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Oddech przeponowy w klęku podpartym - wariant podtrzymujący","description":"Klęk podparty, kręgosłup neutralny. Wdech nosem do boków i tyłu dolnych żeber; wydech spokojny, z lekkim napięciem brzucha. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie zapadaj się w barkach i nie unoś ich przy wdechu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Marsz 2-3 min jako podtrzymanie","description":"Maszeruj spokojnie, unosząc kolana do komfortowej wysokości. Utrzymuj rytm: 2-3 kroki na wdech i 3-4 kroki na wydech, bez zadyszki. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Tempo pozwala mówić krótkim zdaniem; przerwij przy bólu w klatce lub znacznej duszności.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat18","name":"Ból barku / stożek rotatorów","goal":"Poprawa tolerancji unoszenia ramienia i stopniowe wzmacnianie stożka rotatorów oraz łopatki.","note":"Ćwiczenia dobieraj do drażliwości. Po świeżym urazie z nagłą utratą siły lub niemożnością uniesienia ramienia wymagana jest dalsza diagnostyka.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Szczeniak przy ścianie - wariant podtrzymujący","description":"Stań przed ścianą, oprzyj dłonie i cofnij biodra, wydłużając boki tułowia oraz obręcz barkową bez wciskania barku w ból. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Zakres ma być swobodny; nie unoś barków do uszu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Orzeł - ramiona - wariant podtrzymujący","description":"Skrzyżuj ramiona przed klatką, unieś łokcie do wygodnej wysokości i spokojnie oddychaj w górną część pleców. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Bez mrowienia i ostrego bólu barku.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Izometria rotacji zewnętrznej przy ścianie - wariant podtrzymujący","description":"Stań bokiem do ściany, łokieć przy tułowiu i delikatnie naciskaj grzbietem dłoni na ścianę bez ruchu barku. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Siła umiarkowana; ból nie powinien narastać po serii.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Ślizg po ścianie 2-3x/tydz.","description":"Przesuwaj przedramiona w górę po ścianie, utrzymując szyję rozluźnioną i łopatkę płynnie obracającą się ku górze. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie wypychaj żeber do przodu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Scaption bez obciążenia - wariant podtrzymujący","description":"Unieś ramiona w płaszczyźnie około 30° przed bokiem ciała do tolerowanego zakresu, powoli opuść. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch kontrolowany, bez szarpania i unoszenia barków.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat19","name":"Kontrola łopatki / dyskineza","goal":"Poprawa kontroli łopatki podczas unoszenia i obciążania kończyny górnej.","note":"Celem nie jest sztywne „ściąganie łopatek”, lecz płynna współpraca łopatki z ramieniem i klatką piersiową.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Koci grzbiet z aktywnym odepchnięciem dłoni - wariant podtrzymujący","description":"W klęku podpartym zaokrąglij łagodnie odcinek piersiowy, aktywnie odpychając podłoże i pozwalając łopatkom rozsunąć się. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie zapadaj się między barkami.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Deska podtrzymująco 2-3x/tydz.","description":"W podporze na dłoniach utrzymaj łokcie proste i delikatnie „odepchnij podłogę”, nie zaokrąglając przesadnie pleców. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Zacznij z kolan, jeśli pełny podpor jest za trudny.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Serratus punch w leżeniu - wariant podtrzymujący","description":"Leżąc na plecach unieś rękę do sufitu, a następnie bez zginania łokcia sięgnij dłonią wyżej, unosząc łopatkę od podłoża. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch mały i płynny.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wall slide podtrzymująco","description":"Przesuwaj przedramiona po ścianie do góry, utrzymując lekkie odepchnięcie i spokojną szyję. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie dociskaj łopatek do kręgosłupa.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Y przy ścianie - wariant podtrzymujący","description":"Stań twarzą do ściany, unieś ręce po skosie do litery Y i delikatnie odklej dłonie bez unoszenia barków. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zakres mniejszy, jeśli pojawia się kompensacja szyją.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat20","name":"Sztywność barku / zamrożony bark","goal":"Stopniowa poprawa tolerancji ruchu i funkcji bez forsowania bolesnego końcowego zakresu.","note":"W wysokiej drażliwości preferuj częste, krótkie i łagodne ruchy. Agresywne rozciąganie może nasilić objawy.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pozycja dziecka jako reset ruchowy","description":"Oprzyj dłonie na krześle lub łóżku i cofnij biodra, pozwalając barkom wejść w wygodne zgięcie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie wciskaj barku w ból.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Orzeł - łagodny wariant ramion - wariant podtrzymujący","description":"Skrzyżuj ramiona przed klatką i unieś łokcie tylko do komfortowego poziomu. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Pomiń przy ostrym bólu przedniej części barku.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Wahadło Codmana - wariant podtrzymujący","description":"Podeprzyj się zdrową ręką, rozluźnij bolesną kończynę i wykonuj małe koła oraz ruchy przód-tył. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ramię ma być rozluźnione.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Ślizg ręki po stole - wariant podtrzymujący","description":"Siedząc przesuń dłoń po stole do przodu, pozwalając tułowi lekko pochylić się za ręką. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie unoś barku do ucha.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspinanie palcami po ścianie - wariant podtrzymujący","description":"Wejdź palcami po ścianie do tolerowanego poziomu i powoli wróć. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie utrzymuj długo bolesnego końca zakresu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat21","name":"Łokieć tenisisty","goal":"Zmniejszenie bólu podczas chwytu i stopniowe zwiększenie tolerancji prostowników nadgarstka na obciążenie.","note":"Zmniejsz przeciążenie chwytu, ale unikaj całkowitego unieruchamiania. Nasilający się deficyt wyprostu palców wymaga diagnostyki neurologicznej.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Dłonie odwrócone w klęku - łagodnie - wariant podtrzymujący","description":"W klęku podpartym ustaw dłonie palcami w stronę kolan tylko w tolerowanym zakresie i delikatnie cofnij biodra. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Bez drętwienia i ostrego bólu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Orzeł - ramiona - wariant podtrzymujący","description":"Skrzyżuj ramiona i wydłuż tył barków, utrzymując przedramiona rozluźnione. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie zaciskaj dłoni.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Izometria wyprostu nadgarstka - wariant podtrzymujący","description":"Przedramię oprzyj na stole, drugą dłonią staw opór grzbietowi ręki bez ruchu w nadgarstku. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Siła umiarkowana.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Powolny wyprost nadgarstka bez ciężaru - wariant podtrzymujący","description":"Przedramię na stole, dłoń poza krawędzią. Unieś i bardzo powoli opuść nadgarstek. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch ma być płynny.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrolowany chwyt ręcznika - wariant podtrzymujący","description":"Ściskaj zrolowany ręcznik do umiarkowanej siły i powoli rozluźniaj. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie prowokuj bólu utrzymującego się po ćwiczeniu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat22","name":"Łokieć golfisty","goal":"Stopniowe zwiększenie tolerancji zginaczy i pronatorów przedramienia na chwyt i obciążenie.","note":"Przy drętwieniu IV-V palca lub wyraźnym osłabieniu dłoni różnicuj problem z nerwem łokciowym.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Dłonie grzbietami przed klatką - wariant podtrzymujący","description":"Połącz grzbiety dłoni przed klatką piersiową i delikatnie opuszczaj łokcie, utrzymując komfort w nadgarstkach. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Bez mrowienia.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Szczeniak z dłońmi na podwyższeniu - wariant podtrzymujący","description":"Oprzyj dłonie na krześle, cofnij biodra i wydłuż ramiona oraz boki tułowia. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Łokcie miękkie, bez przeprostu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Izometria zgięcia nadgarstka - wariant podtrzymujący","description":"Drugą dłonią staw opór stronie dłoniowej ręki bez wykonywania ruchu. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Siła umiarkowana.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Powolne zgięcie nadgarstka bez ciężaru - wariant podtrzymujący","description":"Przedramię na stole, dłoń poza krawędzią. Zegnij i powoli wróć do neutralnej pozycji. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie ściskaj palców.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Pronacja i supinacja kontrolowana - wariant podtrzymujący","description":"Z łokciem przy tułowiu obracaj dłoń ku górze i ku dołowi w pełnym komfortowym zakresie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch wolny, łokieć stabilny.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat23","name":"Cieśń nadgarstka / nerw pośrodkowy","goal":"Zmniejszenie prowokacji objawów i utrzymanie łagodnego ślizgu nerwu pośrodkowego oraz ruchomości nadgarstka.","note":"Nasilające się drętwienie, zanik kłębu kciuka lub utrwalona słabość wymagają dalszej diagnostyki.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra z otwartymi dłońmi - wariant podtrzymujący","description":"Stań swobodnie, ramiona wzdłuż tułowia, palce dłoni wydłużone i rozluźnione. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie utrzymuj nadgarstków w skrajnym zgięciu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Anjali Mudra - dłonie przed klatką - wariant podtrzymujący","description":"Złącz dłonie przed klatką na wysokości, która nie wywołuje parestezji. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Zmniejsz kąt w nadgarstku przy mrowieniu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie i zamykanie dłoni - wariant podtrzymujący","description":"Naprzemiennie szeroko rozprostuj palce i lekko zamknij dłoń bez silnego ścisku. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch bez bólu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Ślizg nerwu - dawka podtrzymująca","description":"Wykonuj stopniowe ustawienia dłoni, łokcia i barku jako płynny ślizg bez utrzymywania napięcia. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie rozciągaj nerwu na końcu ruchu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Kontrola nadgarstka przy lekkim podporze - wariant podtrzymujący","description":"Oprzyj dłonie o ścianę i delikatnie przenoś ciężar przód-tył. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Przerwij przy nasileniu drętwienia.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat24","name":"Sztywność odcinka piersiowego / garb posturalny","goal":"Poprawa wyprostu i rotacji odcinka piersiowego oraz pracy łopatek.","note":"Przy osteoporozie unikaj forsownego zgięcia i rotacji; ćwiczenia dobierz indywidualnie.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Szczeniak - Uttana Shishosana - wariant podtrzymujący","description":"Z klęku podpartego przesuń dłonie do przodu, pozostawiając biodra nad kolanami i wydłużając klatkę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie zapadaj szyi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Kobra niska - wariant podtrzymujący","description":"Leżąc na brzuchu oprzyj przedramiona lub dłonie i unieś mostek, utrzymując ruch głównie w piersiowym odcinku. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Bez kompresji lędźwi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Otwieranie książki 2-3x/tydz.","description":"Leżąc na boku obracaj górne ramię i klatkę do tyłu, kolana pozostają razem. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch płynny.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wyprost piersiowy na oparciu - wariant podtrzymujący","description":"Usiądź, oprzyj górny odcinek pleców o krawędź oparcia i wykonaj łagodny wyprost. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie odchylaj głowy gwałtownie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Wall angel - wariant podtrzymujący","description":"Plecy przy ścianie, przesuwaj ramiona w górę i w dół bez wypychania żeber. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zakres dostosuj do barków.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat25","name":"Ból lędźwiowy nieswoisty","goal":"Utrzymanie ruchu, poprawa kontroli tułowia i stopniowy powrót do obciążeń dnia codziennego.","note":"Nie ma jednego kierunku ruchu dobrego dla wszystkich. Dobieraj ćwiczenia do reakcji objawów i funkcji.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Kot-krowa jako mobilizacja podtrzymująca","description":"W klęku podpartym płynnie przechodź między łagodnym zgięciem i wyprostem kręgosłupa. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Ruch bez forsowania.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Pozycja dziecka jako reset ruchowy","description":"Cofnij biodra w kierunku pięt, ręce przed sobą i oddychaj spokojnie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Pomiń, jeśli zgięcie nasila objawy.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Przetaczanie miednicy - wariant podtrzymujący","description":"Leżąc na plecach wykonuj małe ruchy przodo- i tyłopochylenia miednicy. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Bez mocnego dociskania pleców.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Most - 2 serie kontrolne 2-3x/tydz.","description":"Unieś biodra do linii tułowia i ud, utrzymując swobodny oddech. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie przeprostuj lędźwi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Bird dog - seria jakościowa 2-3x/tydz.","description":"Z klęku podpartego wyprostuj przeciwną rękę i nogę bez rotacji miednicy. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zakres mniejszy przy bólu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat26","name":"Stabilizacja miednicy / okolica SI","goal":"Poprawa kontroli obciążania miednicy i bioder w podporze obunóż i jednonóż.","note":"Ból okolicy SI wymaga różnicowania z odcinkiem lędźwiowym, biodrem i innymi źródłami bólu.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Wojownik I - krótki wykrok - wariant podtrzymujący","description":"Ustaw krótki wykrok i utrzymaj miednicę skierowaną do przodu, bez zapadania tułowia. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Obie stopy stabilne.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Most - 2 serie kontrolne 2-3x/tydz.","description":"Unieś biodra i wykonaj spokojne 2-3 oddechy, potem powoli opuść. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Bez bólu punktowego w okolicy SI.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Naprzemienne odrywanie stopy w leżeniu - wariant podtrzymujący","description":"W leżeniu z ugiętymi kolanami unieś jedną stopę kilka centymetrów i odstaw bez kołysania miednicą. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Miednica spokojna.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Most - 2 serie kontrolne 2-3x/tydz.","description":"W górze mostu odrywaj na zmianę jedną stopę minimalnie od podłoża. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie opadaj biodrem.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Step-down z niskiego stopnia - wariant podtrzymujący","description":"Stań na niskim stopniu i powoli opuszczaj drugą piętę do podłoża, kontrolując miednicę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Kolano w osi stopy.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat27","name":"Ból rzepkowo-udowy","goal":"Zwiększenie tolerancji kolana na zgięcie i obciążenie oraz poprawa siły biodra i uda.","note":"Ćwiczenia powinny być dozowane według 24-godzinnej reakcji objawów. Nie dąż do „ustawiania rzepki” na siłę.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Krzesło podtrzymująco 2-3x/tydz.","description":"Cofnij biodra jak do siadania, ugnij kolana tylko do komfortowego zakresu i utrzymaj stopy stabilnie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Kolana nad stopami.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Wojownik II podtrzymująco","description":"Ugnij przednie kolano w małym zakresie, utrzymując oś biodro-kolano-stopa. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie zapadaj kolana do środka.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Wyprost kolana w siadzie - wariant podtrzymujący","description":"Siedząc powoli wyprostuj kolano do tolerowanego zakresu i wróć. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch bez szarpania.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wstawanie - 2 serie 2-3x/tydz.","description":"Wstań i usiądź powoli, utrzymując kolana w osi stóp. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zacznij od wyższego siedziska.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Step-down - wariant podtrzymujący","description":"Z niskiego stopnia opuszczaj wolną piętę ku podłożu i wracaj. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Miednica i kolano stabilne.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat28","name":"Ścięgno Achillesa / łydka","goal":"Stopniowe zwiększenie siły i tolerancji ścięgna Achillesa oraz mięśni łydki.","note":"Nagły trzask, utrata odepchnięcia lub dodatni test Thompsona wymagają pilnej diagnostyki ruptury.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - łagodnie - wariant podtrzymujący","description":"Unieś biodra, kolana mogą być ugięte, a pięty wysoko. Stopniowo wydłużaj łydki bez ostrego bólu. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Bez sprężynowania.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Wykrok z tylną piętą na ziemi - wariant podtrzymujący","description":"Stań w wykroku i delikatnie przenieś ciężar do przodu, utrzymując tylną piętę na podłożu. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Rozciąganie łagodne.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Wspięcia podtrzymujące 2-3x/tydz.","description":"Przy podparciu unieś obie pięty i powoli opuść. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch spokojny.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Wspięcia podtrzymujące 2-3x/tydz.","description":"Unieś pięty obunóż, przenieś nieco więcej ciężaru na jedną stronę podczas opuszczania. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Bez gwałtownego spadania pięty.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia podtrzymujące 2-3x/tydz.","description":"Przy lekkim podparciu wykonuj wspięcia na jednej nodze. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zakres i tempo dostosuj do reakcji następnego dnia.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat29","name":"Ból pięty / rozcięgno podeszwowe","goal":"Poprawa tolerancji rozcięgna podeszwowego i łydki na obciążenie oraz kontrola łuku stopy.","note":"Przy bólu pięty z drętwieniem, znacznym obrzękiem lub urazem różnicuj inne przyczyny.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół z ugiętymi kolanami - wariant podtrzymujący","description":"Utrzymaj biodra wysoko, pięty uniesione i stopniowo prostuj kolana bez wywoływania ostrego bólu pięty. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie wymuszaj pięt na ziemi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Góra z aktywnym łukiem - wariant podtrzymujący","description":"Stań boso i utrzymaj trójnóg stopy, delikatnie unosząc łuk bez podwijania palców. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Palce rozluźnione.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Rozciąganie palucha w siadzie - wariant podtrzymujący","description":"Załóż nogę na nogę i delikatnie odciągnij paluch ku górze, czując napięcie pod stopą. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Bez ostrego bólu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Krótka stopa podczas chodu i stania","description":"Aktywuj łuk stopy bez zginania palców i utrzymaj kilka sekund. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nacisk pod piętą i podstawami I/V śródstopia.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Wspięcia podtrzymujące 2-3x/tydz.","description":"Umieść zrolowany ręcznik pod palcami i wykonuj powolne wspięcia na palce. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Zacznij obunóż.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat30","name":"Równowaga i stabilizacja","goal":"Poprawa kontroli postawy, reakcji równoważnych i pewności w podporze jednonóż.","note":"Zapewnij stabilne podparcie w zasięgu ręki. Przy częstych upadkach potrzebna jest pełna ocena ryzyka upadku.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra - Tadasana - wariant podtrzymujący","description":"Stań boso lub w stabilnym obuwiu, ciężar rozłóż równo na stopach i utrzymuj wzrok na stałym punkcie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Oddychaj swobodnie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Drzewo z podparciem - wariant podtrzymujący","description":"Stań przy ścianie, oprzyj stopę nogi wolnej o kostkę lub łydkę i utrzymaj pozycję. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie stawiaj stopy bezpośrednio na kolanie.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Przenoszenie ciężaru jako rozgrzewka","description":"Stań szerzej i powoli przenoś ciężar z jednej nogi na drugą bez unoszenia stóp. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Miednica nad stopą podporową.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Stanie tandem - wariant podtrzymujący","description":"Ustaw jedną stopę przed drugą jak na linie i utrzymaj równowagę. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Podparcie ręką dostępne.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż z sięganiem - wariant podtrzymujący","description":"Stań na jednej nodze i wykonuj drugą stopą lekkie sięgnięcia w przód, bok i tył. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch wolny i kontrolowany.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat31","name":"Chód / przenoszenie ciężaru / wysoki marsz","goal":"Poprawa inicjacji kroku, obciążania kończyn i kontroli stopy podczas chodu.","note":"Przy chorobach neurologicznych dobierz objętość do zmęczenia, spastyczności i bezpieczeństwa. Nowy nagły deficyt wymaga diagnostyki.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Góra z przenoszeniem ciężaru - wariant podtrzymujący","description":"Stań stabilnie i powoli przesuwaj ciężar przód-tył oraz bok-bok w małym zakresie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie odrywaj stóp.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Wojownik II podtrzymująco","description":"Stań szeroko przy blacie, ugnij jedną nogę i utrzymaj stabilne obciążenie obu stóp. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Podparcie ręką dozwolone.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Marsz 2-3 min jako podtrzymanie","description":"Trzymając się blatu unoś naprzemiennie kolana do wygodnej wysokości. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Tułów możliwie pionowo.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Krok w przód i powrót - wariant podtrzymujący","description":"Z pozycji stojącej wykonaj krok w przód, przenieś ciężar na przednią nogę i wróć. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Pełny kontakt stopy z podłożem.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Chód po linii z zatrzymaniem - wariant podtrzymujący","description":"Idź powoli po wyznaczonej linii, co kilka kroków zatrzymaj się i ustabilizuj. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Asekuracja według potrzeb.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat32","name":"Stopa po unieruchomieniu / po gipsie","goal":"Odzyskanie ruchomości stawu skokowego, kontroli stopy, siły łydki i pewnego obciążania po zakończeniu unieruchomienia.","note":"Zakres obciążania musi być zgodny z zaleceniem lekarza prowadzącego. Narastający obrzęk, zaczerwienienie lub ból łydki wymagają oceny.","source":"expanded","exercises":[{"kind":"JOGA 1","title":"Pies z głową w dół - odciążony - wariant podtrzymujący","description":"Z podporu unieś biodra, pozostaw kolana ugięte i przenoś delikatnie ciężar między stopami. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Bez forsowania pięty.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"JOGA 2","title":"Góra z równym obciążeniem - wariant podtrzymujący","description":"Stań przy podparciu i stopniowo wyrównuj ciężar na obu stopach. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"30-60 s x 1-2, 2-3x/tydz.","tip":"Nie unikaj stopy, ale też nie przekraczaj zaleceń obciążania.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 1 - łatwy","title":"Alfabet stopą - wariant podtrzymujący","description":"Siedząc wykonuj stopą małe ruchy jak przy pisaniu liter alfabetu. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Ruch z kostki, nie całej nogi.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 2 - średni","title":"Kolano do ściany kontrolnie przed treningiem","description":"Przy pięcie na podłożu przesuwaj kolano w stronę ściany i wracaj. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Bez ostrego bólu.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."},{"kind":"POZIOM 3 - trudniejszy","title":"Stanie jednonóż przy podparciu - wariant podtrzymujący","description":"Przenieś ciężar na leczoną nogę i utrzymaj równowagę przy ścianie lub blacie. Traktuj jako ćwiczenie podtrzymujące: pełny komfortowy zakres, dobra technika i regularność zamiast maksymalnej intensywności.","dose":"8-12 powt. x 2 serie, 2-3x/tydz.","tip":"Nie progresuj, jeśli obrzęk wyraźnie narasta.  Utrzymuj wersję, po której funkcja jest dobra także następnego dnia."}]},{"id":"cat33","name":"Wzmocnienie pośladków","goal":"Utrzymanie siły pośladków i kontroli biodra przy mniejszej częstotliwości treningu.","note":"Wybierz 3-5 ćwiczeń, które najlepiej podtrzymują funkcję. Nie ma potrzeby wykonywania wszystkich na jednej sesji.","source":"supplement_user_requested","exercises":[{"kind":"JOGA 1","title":"Wojownik III - podtrzymanie","description":"Wykonaj kontrolowany wariant z lekkim podparciem lub bez, zależnie od poziomu równowagi.","dose":"20-30 s/stronę x 2, 2-3x/tydz.","tip":"Priorytetem jest stabilna miednica."},{"kind":"JOGA 2","title":"Krzesło - podtrzymanie","description":"Utrzymaj pozycję krzesła w komfortowym zakresie, zachowując kontrolę stóp i kolan.","dose":"20-40 s x 2, 2-3x/tydz.","tip":"Nie schodź głębiej kosztem techniki."},{"kind":"POZIOM 1 - łatwy","title":"Most jednonóż lub obunóż","description":"Wybierz wariant, który pozwala utrzymać równą miednicę i pracę pośladków.","dose":"8-12/stronę x 2, 2-3x/tydz.","tip":"Wersję dobierz do jakości ruchu."},{"kind":"POZIOM 2 - średni","title":"Skłon rumuński jednonóż z sięganiem","description":"Stań na jednej nodze, cofnij biodra i pochyl tułów, sięgając ręką do przodu. Wróć przez wyprost biodra.","dose":"6-10/stronę x 2, 2-3x/tydz.","tip":"Kręgosłup długi, miednica możliwie poziomo."},{"kind":"POZIOM 3 - trudniejszy","title":"Step-up lub step-down","description":"Na niskim stopniu wykonuj kontrolowane wejścia albo zejścia, utrzymując kolano i miednicę stabilnie.","dose":"8-12/stronę x 2-3, 2-3x/tydz.","tip":"Dobierz wysokość stopnia do techniki."}]}]}]};
